{"command":"mkdir -p /workspace/src && cat > /workspace/src/cli.rs <<'EOF'
//! Command line interface definition.

use std::num::NonZeroUsize;

use clap::builder::{PossibleValue, PossibleValuesParser, TypedValueParser};
use clap::{Arg, ArgAction, ArgGroup, ArgMatches, Command, ValueHint};
use clap_complete::Shell;

use crate::langs::{LangKind, LANG_SPECS};

pub const BIN_NAME: &str = "srgn";
pub const VERSION: &str = "0.14.1";

const ABOUT: &str = "A grep-like tool which understands source code syntax and allows for manipulation in addition to search";

const SCOPE_LONG_HELP: &str = "Scope to apply to, as a regular expression pattern.

If string literal mode is requested, will be interpreted as a literal string.

Actions will apply their transformations within this scope only.

The default is the global scope, matching the entire input. Where that default is meaningless or dangerous (e.g., deletion), this argument is required.";

const REPLACE_LONG_HELP: &str = "Replace anything in scope with this value.

Variables are supported: if a regex pattern was used for scoping and captured content in named or numbered capture groups, access these in the replacement value using `$1` etc. for numbered, `$NAME` etc. for named capture groups.

This action is specially treated as a positional argument for ergonomics and compatibility with `tr`.

If given, will run before any other action.";

const GERMAN_LONG_HELP: &str = "Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.

ASCII spellings for Umlauts (ae, oe, ue) and Eszett (ss) are replaced by their respective native Unicode (ä, ö, ü, ß).

Arbitrary compound words are supported.

Words legally containing alternative spellings are not modified.

Words require correct spelling to be detected.";

const SYMBOLS_LONG_HELP: &str = "Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.

Helps translate 'ASCII art' into native Unicode representations.";

const DELETE_LONG_HELP: &str = "Delete anything in scope.

Cannot be used with any other action: there is no point in deleting and performing any other processing. Sibling actions would either receive empty input or have their work wiped.";

const GLOB_LONG_HELP: &str = "Glob of files to work on (instead of reading stdin).

If actions are applied, they overwrite files in-place.

For supported glob syntax, see:
<https://docs.rs/glob/0.3.1/glob/struct.Pattern.html>

Names of processed files are written to stdout.";

const FAIL_NO_FILES_LONG_HELP: &str = "Fail if working on files (e.g. globbing is requested) but none are found.

Processing no files is not an error condition in itself, but might be an unexpected outcome in some contexts. This flag makes the condition explicit.";

const DRY_RUN_LONG_HELP: &str = "Do not destructively overwrite files, instead print rich diff only.

The diff details the names of files which would be modified, alongside all changes inside those files which would be performed outside of dry running. It is similar to git diff with word diffing enabled.";

const INVERT_LONG_HELP: &str = "Undo the effects of passed actions, where applicable.

Requires a 1:1 mapping between replacements and original, which is currently available only for:

- symbols: '≠' <-> '!=' etc.

Other actions:

- german: inverting e.g. 'Ä' is ambiguous (can be 'Ae' or 'AE')

- upper, lower, deletion, squeeze: inversion is impossible as information is
  lost

These may still be passed, but will be ignored for inversion and applied normally.";

const LITERAL_STRING_LONG_HELP: &str = "Do not interpret the scope as a regex. Instead, interpret it as a literal string. Will require a scope to be passed.";

const FAIL_ANY_LONG_HELP: &str = "If anything at all is found to be in scope, fail.

The default is to continue processing normally.";

const FAIL_NONE_LONG_HELP: &str = "If nothing is found to be in scope, fail.

The default is to return the input unchanged (without failure).";

const JOIN_LONG_HELP: &str = "Join (logical 'OR') multiple language scopes, instead of intersecting them.

The default when multiple language scopes are given is to intersect their scopes, left to right. For example, `--go func --go strings` will first scope down to `func` bodies, then look for strings only within those. This flag instead joins (in the set logic sense) all scopes. The example would then scope any `func` bodies, and any strings, anywhere. Language scopers can then also be given in any order.

No effect if only a single language scope is given. Also does not affect non-language scopers (regex pattern etc.), which always intersect.";

const SORTED_LONG_HELP: &str = "Process files in lexicographically sorted order, by file path.

In search mode, this emits results in sorted order. Otherwise, it processes files in sorted order.

Sorted processing disables parallel processing.";

const THREADS_LONG_HELP: &str = "Number of threads to run processing on, when working with files.

If not specified, will default to available parallelism. Set to 1 for sequential, deterministic (but not sorted) output.";

const VERBOSE_LONG_HELP: &str = "Increase log verbosity level.

The base log level to use is read from the `RUST_LOG` environment variable (if unspecified, defaults to 'error'), and increased according to the number of times this flag is given, maxing out at 'trace' verbosity.";

const GERMAN_PREFER_ORIGINAL_LONG_HELP: &str = "When some original version and its replacement are equally legal, prefer the original and do not modify.

For example, \"Busse\" (original) and \"Buße\" (replacement) are equally legal words: by default, the tool would prefer the latter.";

const GERMAN_NAIVE_LONG_HELP: &str = "Always perform any possible replacement ('ae' -> 'ä', 'ss' -> 'ß', etc.), regardless of legality of the resulting word

Useful for names, which are otherwise not modifiable as they do not occur in dictionaries. Called 'naive' as this does not perform legal checks.";

const HEADING_COMPOSABLE: &str = "Composable Actions";
const HEADING_STANDALONE: &str = "Standalone Actions (only usable alone)";
const HEADING_GLOBAL: &str = "Options (global)";
const HEADING_LANGS: &str = "Language scopes";
const HEADING_GERMAN: &str = "Options (german)";

/// A value parser for language scope values, which accepts the fixed set of prepared
/// queries but also dynamic ones (`struct~PATTERN`).
#[derive(Clone)]
struct LangScopeParser {
    kind: LangKind,
}

impl TypedValueParser for LangScopeParser {
    type Value = String;

    fn parse_ref(
        &self,
        cmd: &Command,
        arg: Option<&Arg>,
        value: &std::ffi::OsStr,
    ) -> Result<Self::Value, clap::Error> {
        let spec = &LANG_SPECS[self.kind as usize];
        let s = value.to_str().ok_or_else(|| {
            clap::Error::raw(clap::error::ErrorKind::InvalidUtf8, "invalid utf-8")
                .with_cmd(cmd)
        })?;

        if spec.values.iter().any(|v| !v.dynamic && v.name == s) {
            return Ok(s.to_owned());
        }
        if let Some((prefix, pattern)) = s.split_once('~') {
            if spec
                .values
                .iter()
                .any(|v| v.dynamic && v.name.trim_end_matches("~<PATTERN>") == prefix)
            {
                // Validate the pattern as a regular expression.
                match regex::Regex::new(pattern) {
                    Ok(_) => return Ok(s.to_owned()),
                    Err(e) => {
                        let mut err = clap::Error::new(clap::error::ErrorKind::ValueValidation)
                            .with_cmd(cmd);
                        if let Some(arg) = arg {
                            err.insert(
                                clap::error::ContextKind::InvalidArg,
                                clap::error::ContextValue::String(arg.to_string()),
                            );
                        }
                        err.insert(
                            clap::error::ContextKind::InvalidValue,
                            clap::error::ContextValue::String(s.to_owned()),
                        );
                        err.insert(
                            clap::error::ContextKind::Custom,
                            clap::error::ContextValue::String(e.to_string()),
                        );
                        return Err(err);
                    }
                }
            }
        }

        // Fall back to the regular possible values parser for a nice error message.
        let pv: Vec<PossibleValue> = spec.values.iter().map(|v| v.possible_value()).collect();
        let parser = PossibleValuesParser::new(pv);
        parser.parse_ref(cmd, arg, value)
    }

    fn possible_values(&self) -> Option<Box<dyn Iterator<Item = PossibleValue> + '_>> {
        let spec = &LANG_SPECS[self.kind as usize];
        Some(Box::new(spec.values.iter().map(|v| v.possible_value())))
    }
}

fn flag(id: &'static str, long: &'static str, help: &'static str) -> Arg {
    Arg::new(id)
        .long(long)
        .help(help)
        .action(ArgAction::SetTrue)
}

pub fn build_command() -> Command {
    let mut cmd = Command::new(BIN_NAME)
        .version(VERSION)
        .about(ABOUT)
        .term_width(90)
        .arg(
            Arg::new("scope")
                .value_name("SCOPE")
                .index(1)
                .default_value(".*")
                .help("Scope to apply to, as a regular expression pattern.")
                .long_help(SCOPE_LONG_HELP),
        )
        .arg(
            Arg::new("shell")
                .long("completions")
                .value_name("SHELL")
                .value_parser(clap::value_parser!(Shell))
                .help("Print shell completions for the given shell.")
                .action(ArgAction::Set),
        )
        // Composable actions
        .arg(
            flag("upper", "upper", "Uppercase anything in scope.")
                .short('u')
                .env("UPPER")
                .help_heading(HEADING_COMPOSABLE),
        )
        .arg(
            flag("lower", "lower", "Lowercase anything in scope.")
                .short('l')
                .env("LOWER")
                .help_heading(HEADING_COMPOSABLE),
        )
        .arg(
            flag("titlecase", "titlecase", "Titlecase anything in scope.")
                .short('t')
                .env("TITLECASE")
                .help_heading(HEADING_COMPOSABLE),
        )
        .arg(
            flag(
                "normalize",
                "normalize",
                "Normalize (Normalization Form D) anything in scope, and throw away marks.",
            )
            .short('n')
            .env("NORMALIZE")
            .help_heading(HEADING_COMPOSABLE),
        )
        .arg(
            flag(
                "german",
                "german",
                "Perform substitutions on German words, such as 'Abenteuergruesse' to 'Abenteuergrüße', for anything in scope.",
            )
            .short('g')
            .long_help(GERMAN_LONG_HELP)
            .help_heading(HEADING_COMPOSABLE),
        )
        .arg(
            flag(
                "symbols",
                "symbols",
                "Perform substitutions on symbols, such as '!=' to '≠', '->' to '→', on anything in scope.",
            )
            .short('S')
            .long_help(SYMBOLS_LONG_HELP)
            .help_heading(HEADING_COMPOSABLE),
        )
        .arg(
            Arg::new("replace")
                .value_name("REPLACEMENT")
                .index(2)
                .last(true)
                .env("REPLACE")
                .help("Replace anything in scope with this value.")
                .long_help(REPLACE_LONG_HELP)
                .help_heading(HEADING_COMPOSABLE),
        )
        // Standalone actions
        .arg(
            flag("delete", "delete", "Delete anything in scope.")
                .short('d')
                .long_help(DELETE_LONG_HELP)
                .requires("scope")
                .conflicts_with_all([
                    "replace",
                    "upper",
                    "lower",
                    "titlecase",
                    "normalize",
                    "german",
                    "symbols",
                ])
                .help_heading(HEADING_STANDALONE),
        )
        .arg(
            flag(
                "squeeze",
                "squeeze",
                "Squeeze consecutive occurrences of scope into one.",
            )
            .short('s')
            .env("SQUEEZE")
            .visible_alias("squeeze-repeats")
            .requires("scope")
            .help_heading(HEADING_STANDALONE),
        )
        .group(
            ArgGroup::new("standalone_actions")
                .args(["delete", "squeeze"])
                .multiple(false),
        )
        // Global options
        .arg(
            Arg::new("glob")
                .short('G')
                .long("glob")
                .value_name("GLOB")
                .value_parser(parse_glob)
                .help("Glob of files to work on (instead of reading stdin).")
                .long_help(GLOB_LONG_HELP)
                .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "fail_no_files",
                "fail-no-files",
                "Fail if working on files (e.g. globbing is requested) but none are found.",
            )
            .long_help(FAIL_NO_FILES_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "dry_run",
                "dry-run",
                "Do not destructively overwrite files, instead print rich diff only.",
            )
            .long_help(DRY_RUN_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "invert",
                "invert",
                "Undo the effects of passed actions, where applicable.",
            )
            .short('i')
            .env("INVERT")
            .long_help(INVERT_LONG_HELP)
            .requires("symbols")
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "literal_string",
                "literal-string",
                "Do not interpret the scope as a regex. Instead, interpret it as a literal string. Will require a scope to be passed.",
            )
            .short('L')
            .env("LITERAL_STRING")
            .long_help(LITERAL_STRING_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "fail_any",
                "fail-any",
                "If anything at all is found to be in scope, fail.",
            )
            .long_help(FAIL_ANY_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "fail_none",
                "fail-none",
                "If nothing is found to be in scope, fail.",
            )
            .long_help(FAIL_NONE_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "join_language_scopes",
                "join-language-scopes",
                "Join (logical 'OR') multiple language scopes, instead of intersecting them.",
            )
            .short('j')
            .long_help(JOIN_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "line_numbers",
                "line-numbers",
                "Prepend line numbers to output.",
            )
            .hide(true)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "only_matching",
                "only-matching",
                "Print only matching lines.",
            )
            .hide(true)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "hidden",
                "hidden",
                "Do not ignore hidden files and directories.",
            )
            .short('H')
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "gitignored",
                "gitignored",
                "Do not ignore `.gitignore`d files and directories.",
            )
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            flag(
                "sorted",
                "sorted",
                "Process files in lexicographically sorted order, by file path.",
            )
            .long_help(SORTED_LONG_HELP)
            .help_heading(HEADING_GLOBAL),
        )
        .arg(
            Arg::new("stdin_detection")
                .long("stdin-detection")
                .value_name("STDIN_DETECTION")
                .default_value("auto")
                .value_parser(PossibleValuesParser::new([
                    PossibleValue::new("auto").help("Automatically detect if stdin is readable"),
                    PossibleValue::new("force-readable").help("Act as if stdin is readable"),
                    PossibleValue::new("force-unreadable")
                        .help("Act as if stdin is not readable"),
                ]))
                .help("Control heuristics for stdin readability detection, and force to value.")
                .help_heading(HEADING_GLOBAL),
        )
        .arg(
            Arg::new("stdout_detection")
                .long("stdout-detection")
                .value_name("STDOUT_DETECTION")
                .default_value("auto")
                .value_parser(PossibleValuesParser::new([
                    PossibleValue::new("auto")
                        .help("Automatically detect if stdout is a TTY and act accordingly"),
                    PossibleValue::new("force-tty").help("Act as if stdout is a TTY"),
                    PossibleValue::new("force-pipe")
                        .help("Act as if stdout is not a TTY, e.g. a pipe, redirect"),
                ]))
                .help("Control heuristics for stdout detection, and potentially force to value.")
                .help_heading(HEADING_GLOBAL),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .value_name("THREADS")
                .value_parser(clap::value_parser!(NonZeroUsize))
                .help("Number of threads to run processing on, when working with files.")
                .long_help(THREADS_LONG_HELP)
                .help_heading(HEADING_GLOBAL),
        )
        .arg(
            Arg::new("additional_verbosity")
                .short('v')
                .long("verbose")
                .action(ArgAction::Count)
                .help("Increase log verbosity level.")
                .long_help(VERBOSE_LONG_HELP)
                .help_heading(HEADING_GLOBAL),
        );

    // Language scopes
    for spec in LANG_SPECS.iter() {
        let flag_name = spec.flag;
        let env_base = spec.env;
        let mut scope_arg = Arg::new(spec.flag)
            .long(spec.flag)
            .value_name(env_base)
            .env(env_base)
            .action(ArgAction::Append)
            .value_parser(LangScopeParser { kind: spec.kind })
            .help(format!("Scope {} code using a prepared query.", spec.display))
            .help_heading(HEADING_LANGS);
        if let Some(alias) = spec.alias {
            scope_arg = scope_arg.visible_alias(alias);
        }
        let query_id: &'static str = Box::leak(format!("{flag_name}-query").into_boxed_str());
        let query_file_id: &'static str =
            Box::leak(format!("{flag_name}-query-file").into_boxed_str());
        let query_env: &'static str = Box::leak(format!("{env_base}_QUERY").into_boxed_str());
        let query_file_env: &'static str =
            Box::leak(format!("{env_base}_QUERY_FILE").into_boxed_str());

        scope_arg = scope_arg.conflicts_with_all([query_id, query_file_id]);

        let query_arg = Arg::new(query_id)
            .long(query_id)
            .value_name("TREE-SITTER-QUERY-VALUE")
            .env(query_env)
            .action(ArgAction::Append)
            .help(format!(
                "Scope {} code using a custom tree-sitter query.",
                spec.display
            ))
            .help_heading(HEADING_LANGS);
        let query_file_arg = Arg::new(query_file_id)
            .long(query_file_id)
            .value_name("TREE-SITTER-QUERY-FILENAME")
            .env(query_file_env)
            .action(ArgAction::Append)
            .value_hint(ValueHint::FilePath)
            .conflicts_with(query_id)
            .help(format!(
                "Scope {} code using a custom tree-sitter query from file.",
                spec.display
            ))
            .help_heading(HEADING_LANGS);
        cmd = cmd.arg(scope_arg).arg(query_arg).arg(query_file_arg);
    }

    cmd = cmd
        .arg(
            flag(
                "german_prefer_original",
                "german-prefer-original",
                "When some original version and its replacement are equally legal, prefer the original and do not modify.",
            )
            .env("GERMAN_PREFER_ORIGINAL")
            .long_help(GERMAN_PREFER_ORIGINAL_LONG_HELP)
            .help_heading(HEADING_GERMAN),
        )
        .arg(
            flag(
                "german_naive",
                "german-naive",
                "Always perform any possible replacement ('ae' -> 'ä', 'ss' -> 'ß', etc.), regardless of legality of the resulting word",
            )
            .env("GERMAN_NAIVE")
            .long_help(GERMAN_NAIVE_LONG_HELP)
            .help_heading(HEADING_GERMAN),
        );

    cmd
}

fn parse_glob(s: &str) -> Result<glob::Pattern, String> {
    glob::Pattern::new(s).map_err(|e| e.to_string())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StdinDetection {
    Auto,
    ForceReadable,
    ForceUnreadable,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StdoutDetection {
    Auto,
    ForceTty,
    ForcePipe,
}

#[derive(Debug)]
pub struct ComposableActions {
    pub replace: Option<String>,
    pub upper: bool,
    pub lower: bool,
    pub titlecase: bool,
    pub normalize: bool,
    pub german: bool,
    pub symbols: bool,
}

impl ComposableActions {
    pub fn any(&self) -> bool {
        self.replace.is_some()
            || self.upper
            || self.lower
            || self.titlecase
            || self.normalize
            || self.german
            || self.symbols
    }
}

#[derive(Debug)]
pub struct StandaloneActions {
    pub delete: bool,
    pub squeeze: bool,
}

#[derive(Debug)]
pub struct GlobalOptions {
    pub glob: Option<glob::Pattern>,
    pub fail_no_files: bool,
    pub dry_run: bool,
    pub invert: bool,
    pub literal_string: bool,
    pub fail_any: bool,
    pub fail_none: bool,
    pub join_language_scopes: bool,
    pub line_numbers: bool,
    pub only_matching: bool,
    pub hidden: bool,
    pub gitignored: bool,
    pub sorted: bool,
    pub stdin_detection: StdinDetection,
    pub stdout_detection: StdoutDetection,
    pub threads: Option<NonZeroUsize>,
    pub additional_verbosity: u8,
}

#[derive(Debug)]
pub struct GermanOptions {
    pub german_prefer_original: bool,
    pub german_naive: bool,
}

/// A custom tree-sitter query, given literally.
pub struct QueryLiteral(pub String);

impl std::fmt::Debug for QueryLiteral {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "QueryLiteral({:?})", self.0)
    }
}

/// Scoping options for one language.
pub struct LangScope {
    pub kind: LangKind,
    /// Prepared queries, as given on the command line (e.g. `comments`, `struct~Foo`).
    pub prepared: Vec<String>,
    pub queries: Vec<QueryLiteral>,
    pub query_files: Vec<String>,
}

impl std::fmt::Debug for LangScope {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let spec = &LANG_SPECS[self.kind as usize];
        let field = spec.field;
        let prepared: Vec<PreparedDebug> = self
            .prepared
            .iter()
            .map(|p| PreparedDebug(self.kind, p.clone()))
            .collect();
        f.debug_struct(spec.struct_name)
            .field(field, &prepared)
            .field(&format!("{field}_query"), &self.queries)
            .field(&format!("{field}_query_file"), &self.query_files)
            .finish()
    }
}

struct PreparedDebug(LangKind, String);

impl std::fmt::Debug for PreparedDebug {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let spec = &LANG_SPECS[self.0 as usize];
        if let Some((prefix, pattern)) = self.1.split_once('~') {
            if let Some(v) = spec
                .values
                .iter()
                .find(|v| v.dynamic && v.name.trim_end_matches("~<PATTERN>") == prefix)
            {
                return write!(
                    f,
                    "{}(TreeSitterRegex(Regex({:?})))",
                    v.variant, pattern
                );
            }
        }
        match spec.values.iter().find(|v| !v.dynamic && v.name == self.1) {
            Some(v) => write!(f, "{}", v.variant),
            None => write!(f, "{}", self.1),
        }
    }
}

pub struct LanguageScopes {
    pub c: Option<LangScope>,
    pub csharp: Option<LangScope>,
    pub go: Option<LangScope>,
    pub hcl: Option<LangScope>,
    pub python: Option<LangScope>,
    pub rust: Option<LangScope>,
    pub typescript: Option<LangScope>,
}

impl std::fmt::Debug for LanguageScopes {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("LanguageScopes")
            .field("c", &self.c)
            .field("csharp", &self.csharp)
            .field("go", &self.go)
            .field("hcl", &self.hcl)
            .field("python", &self.python)
            .field("rust", &self.rust)
            .field("typescript", &self.typescript)
            .finish()
    }
}

impl LanguageScopes {
    /// All given language scopes, in canonical order.
    pub fn all(&self) -> Vec<&LangScope> {
        [
            &self.c,
            &self.csharp,
            &self.go,
            &self.hcl,
            &self.python,
            &self.rust,
            &self.typescript,
        ]
        .into_iter()
        .flatten()
        .collect()
    }

    pub fn is_empty(&self) -> bool {
        self.all().is_empty()
    }
}

#[derive(Debug)]
pub struct Args {
    pub scope: String,
    pub shell: Option<Shell>,
    pub composable_actions: ComposableActions,
    pub standalone_actions: StandaloneActions,
    pub options: GlobalOptions,
    pub languages_scopes: LanguageScopes,
    pub german_options: GermanOptions,
}

/// Whether the scope argument was explicitly given (as opposed to defaulted).
pub fn scope_explicitly_given(matches: &ArgMatches) -> bool {
    matches!(
        matches.value_source("scope"),
        Some(clap::parser::ValueSource::CommandLine) | Some(clap::parser::ValueSource::EnvVariable)
    )
}

fn lang_scope(matches: &ArgMatches, spec: &crate::langs::LangSpec) -> Option<LangScope> {
    let prepared: Vec<String> = matches
        .get_many::<String>(spec.flag)
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let queries: Vec<QueryLiteral> = matches
        .get_many::<String>(&format!("{}-query", spec.flag))
        .map(|v| v.map(|s| QueryLiteral(s.clone())).collect())
        .unwrap_or_default();
    let query_files: Vec<String> = matches
        .get_many::<String>(&format!("{}-query-file", spec.flag))
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    if prepared.is_empty() && queries.is_empty() && query_files.is_empty() {
        None
    } else {
        Some(LangScope {
            kind: spec.kind,
            prepared,
            queries,
            query_files,
        })
    }
}

pub fn args_from_matches(matches: &ArgMatches) -> Args {
    let flag = |id: &str| matches.get_flag(id);

    let german_prefer_original = flag("german_prefer_original");
    let german_naive = flag("german_naive");

    let languages_scopes = LanguageScopes {
        c: lang_scope(matches, &LANG_SPECS[LangKind::C as usize]),
        csharp: lang_scope(matches, &LANG_SPECS[LangKind::CSharp as usize]),
        go: lang_scope(matches, &LANG_SPECS[LangKind::Go as usize]),
        hcl: lang_scope(matches, &LANG_SPECS[LangKind::Hcl as usize]),
        python: lang_scope(matches, &LANG_SPECS[LangKind::Python as usize]),
        rust: lang_scope(matches, &LANG_SPECS[LangKind::Rust as usize]),
        typescript: lang_scope(matches, &LANG_SPECS[LangKind::TypeScript as usize]),
    };

    Args {
        scope: matches
            .get_one::<String>("scope")
            .cloned()
            .unwrap_or_else(|| ".*".to_owned()),
        shell: matches.get_one::<Shell>("shell").copied(),
        composable_actions: ComposableActions {
            replace: matches.get_one::<String>("replace").cloned(),
            upper: flag("upper"),
            lower: flag("lower"),
            titlecase: flag("titlecase"),
            normalize: flag("normalize"),
            german: flag("german") || german_prefer_original || german_naive,
            symbols: flag("symbols"),
        },
        standalone_actions: StandaloneActions {
            delete: flag("delete"),
            squeeze: flag("squeeze"),
        },
        options: GlobalOptions {
            glob: matches.get_one::<glob::Pattern>("glob").cloned(),
            fail_no_files: flag("fail_no_files"),
            dry_run: flag("dry_run"),
            invert: flag("invert"),
            literal_string: flag("literal_string"),
            fail_any: flag("fail_any"),
            fail_none: flag("fail_none"),
            join_language_scopes: flag("join_language_scopes"),
            line_numbers: flag("line_numbers"),
            only_matching: flag("only_matching"),
            hidden: flag("hidden"),
            gitignored: flag("gitignored"),
            sorted: flag("sorted"),
            stdin_detection: match matches
                .get_one::<String>("stdin_detection")
                .map(String::as_str)
            {
                Some("force-readable") => StdinDetection::ForceReadable,
                Some("force-unreadable") => StdinDetection::ForceUnreadable,
                _ => StdinDetection::Auto,
            },
            stdout_detection: match matches
                .get_one::<String>("stdout_detection")
                .map(String::as_str)
            {
                Some("force-tty") => StdoutDetection::ForceTty,
                Some("force-pipe") => StdoutDetection::ForcePipe,
                _ => StdoutDetection::Auto,
            },
            threads: matches.get_one::<NonZeroUsize>("threads").copied(),
            additional_verbosity: matches.get_count("additional_verbosity"),
        },
        languages_scopes,
        german_options: GermanOptions {
            german_prefer_original,
            german_naive,
        },
    }
}
EOF
echo done"}

