//! Scoped views: an input string broken into pieces which are either in or out of
//! scope.

use std::collections::BTreeMap;
use std::fmt;

/// Capture groups of a regex match, used for variable substitution in replacements.
#[derive(Clone, Default, PartialEq, Eq)]
pub struct CaptureGroups {
    pub numbered: BTreeMap<usize, String>,
    pub named: BTreeMap<String, String>,
}

impl CaptureGroups {
    pub fn get(&self, name: &str) -> Option<&str> {
        if let Ok(n) = name.parse::<usize>() {
            if let Some(v) = self.numbered.get(&n) {
                return Some(v.as_str());
            }
        }
        self.named.get(name).map(String::as_str)
    }
}

impl fmt::Debug for CaptureGroups {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "CaptureGroups({{")?;
        let mut first = true;
        for (k, v) in &self.numbered {
            if !first {
                write!(f, ", ")?;
            }
            first = false;
            write!(f, "Numbered({k}): {v:?}")?;
        }
        for (k, v) in &self.named {
            if !first {
                write!(f, ", ")?;
            }
            first = false;
            write!(f, "Named({k:?}): {v:?}")?;
        }
        write!(f, "}})")
    }
}

/// A piece of the input.
#[derive(Clone, PartialEq, Eq)]
pub struct Piece {
    pub text: String,
    pub in_scope: bool,
    pub context: Option<CaptureGroups>,
}

impl fmt::Debug for Piece {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if self.in_scope {
            write!(f, "In({:?}, {:?})", self.text, self.context)
        } else {
            write!(f, "Out({:?})", self.text)
        }
    }
}

/// An input, split into in-scope and out-of-scope pieces.
#[derive(Clone, Default)]
pub struct View {
    pub pieces: Vec<Piece>,
}

impl fmt::Debug for View {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "ScopedView {{ scopes: RWScopes([")?;
        for (i, p) in self.pieces.iter().enumerate() {
            if i > 0 {
                write!(f, ", ")?;
            }
            write!(f, "RWScope({p:?})")?;
        }
        write!(f, "]) }}")
    }
}

impl View {
    /// A view with the entire input in scope.
    pub fn new(input: &str) -> Self {
        if input.is_empty() {
            return Self { pieces: vec![] };
        }
        Self {
            pieces: vec![Piece {
                text: input.to_owned(),
                in_scope: true,
                context: None,
            }],
        }
    }

    /// Explode each in-scope piece using the given function, which maps the piece's
    /// text to a list of in-scope byte ranges (sorted, non-overlapping) with optional
    /// capture context.
    pub fn explode<F>(&mut self, mut f: F)
    where
        F: FnMut(&str) -> Vec<(std::ops::Range<usize>, Option<CaptureGroups>)>,
    {
        let mut new_pieces = Vec::with_capacity(self.pieces.len());
        for piece in self.pieces.drain(..) {
            if !piece.in_scope {
                new_pieces.push(piece);
                continue;
            }
            let ranges = f(&piece.text);
            let mut pos = 0;
            for (range, ctx) in ranges {
                if range.start > pos {
                    new_pieces.push(Piece {
                        text: piece.text[pos..range.start].to_owned(),
                        in_scope: false,
                        context: None,
                    });
                }
                if range.end > range.start {
                    new_pieces.push(Piece {
                        text: piece.text[range.start..range.end].to_owned(),
                        in_scope: true,
                        context: ctx,
                    });
                }
                pos = range.end;
            }
            if pos < piece.text.len() {
                new_pieces.push(Piece {
                    text: piece.text[pos..].to_owned(),
                    in_scope: false,
                    context: None,
                });
            }
            log::debug!(
                "Scopes: {:?}",
                ROScopes(&new_pieces[new_pieces.len().saturating_sub(0)..])
            );
        }
        self.pieces = new_pieces;
    }

    /// Whether anything is in scope.
    pub fn has_any_in_scope(&self) -> bool {
        self.pieces.iter().any(|p| p.in_scope && !p.text.is_empty())
    }

    /// Squeeze: remove in-scope pieces immediately following another in-scope piece.
    pub fn squeeze(&mut self) {
        let mut out: Vec<Piece> = Vec::with_capacity(self.pieces.len());
        for piece in self.pieces.drain(..) {
            if piece.in_scope {
                if let Some(last) = out.last() {
                    if last.in_scope {
                        continue;
                    }
                }
            }
            out.push(piece);
        }
        self.pieces = out;
    }

    /// Apply a mapping function to all in-scope pieces.
    pub fn map_in_scope<F>(&mut self, mut f: F) -> Result<(), crate::actions::ActionError>
    where
        F: FnMut(&str, Option<&CaptureGroups>) -> Result<String, crate::actions::ActionError>,
    {
        for piece in &mut self.pieces {
            if piece.in_scope {
                log::debug!("Mapping with context: {:?}", piece.context);
                let new = f(&piece.text, piece.context.as_ref())?;
                log::debug!("Replacing '{}' with '{}'", piece.text, new);
                piece.text = new;
            } else {
                log::debug!("Appending '{}'", piece.text);
            }
        }
        Ok(())
    }

    /// The full text of the view.
    pub fn to_string(&self) -> String {
        let mut s = String::new();
        for p in &self.pieces {
            s.push_str(&p.text);
        }
        s
    }
}

struct ROScopes<'a>(&'a [Piece]);

impl fmt::Debug for ROScopes<'_> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "[")?;
        for (i, p) in self.0.iter().enumerate() {
            if i > 0 {
                write!(f, ", ")?;
            }
            write!(f, "ROScope({p:?})")?;
        }
        write!(f, "]")
    }
}
EOF
