//! Scopers: regex and literal string scoping.

use crate::view::CaptureGroups;
use std::ops::Range;

pub struct RegexScoper {
    regex: fancy_regex::Regex,
    /// Names of capture groups, by index (index 0 is the whole match).
    names: Vec<Option<String>>,
}

#[derive(Debug)]
pub struct RegexError(pub String);

impl std::fmt::Display for RegexError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Invalid regex: {}", self.0)
    }
}

impl std::error::Error for RegexError {}

fn format_regex_error(e: &fancy_regex::Error) -> String {
    // Newer regex engines report syntax errors of the inner engine tersely.
    if let fancy_regex::Error::CompileError(fancy_regex::CompileError::InnerError(inner)) = e {
        if let regex::Error::Syntax(_) = inner {
            return "Error compiling regex: Regex error: error parsing pattern 0".to_owned();
        }
    }
    e.to_string()
}

impl RegexScoper {
    pub fn new(pattern: &str) -> Result<Self, RegexError> {
        let regex = fancy_regex::Regex::new(pattern).map_err(|e| RegexError(format_regex_error(&e)))?;
        let names = regex
            .capture_names()
            .map(|n| n.map(|s| s.to_owned()))
            .collect();
        Ok(Self { regex, names })
    }

    pub fn from_literal(literal: &str) -> Self {
        let escaped = fancy_regex::escape(literal);
        Self::new(&escaped).expect("escaped literal is a valid regex")
    }

    /// Find all non-empty matches in the given text.
    pub fn ranges(&self, text: &str) -> Vec<(Range<usize>, Option<CaptureGroups>)> {
        let mut out = Vec::new();
        for caps in self.regex.captures_iter(text) {
            let caps = match caps {
                Ok(c) => c,
                Err(_) => break,
            };
            let whole = match caps.get(0) {
                Some(m) => m,
                None => continue,
            };
            if whole.start() == whole.end() {
                continue;
            }
            let mut groups = CaptureGroups::default();
            for (i, name) in self.names.iter().enumerate() {
                if let Some(m) = caps.get(i) {
                    match name {
                        Some(n) => {
                            groups.named.insert(n.clone(), m.as_str().to_owned());
                        }
                        None => {
                            groups.numbered.insert(i, m.as_str().to_owned());
                        }
                    }
                }
            }
            out.push((whole.start()..whole.end(), Some(groups)));
        }
        out
    }
}
