//! Actions, applied to in-scope pieces.

pub mod german;
pub mod normalize;
pub mod replace;
pub mod symbols;
pub mod titlecase;

use crate::view::CaptureGroups;

#[derive(Debug)]
pub enum ActionError {
    Replacement(replace::ReplacementError),
}

impl std::fmt::Display for ActionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ActionError::Replacement(e) => {
                write!(f, "Error in an action: Action failed in replacement: {e}")
            }
        }
    }
}

impl std::error::Error for ActionError {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ActionKind {
    Replacement,
    Deletion,
    Upper,
    Lower,
    Titlecase,
    Normalization,
    German,
    Symbols,
}

/// All configured actions, in application order.
pub struct Actions {
    pub replacement: Option<String>,
    pub delete: bool,
    pub upper: bool,
    pub lower: bool,
    pub titlecase: bool,
    pub normalize: bool,
    pub german: Option<german::German>,
    pub symbols: Option<symbols::Symbols>,
}

impl Actions {
    pub fn is_empty(&self) -> bool {
        self.replacement.is_none()
            && !self.delete
            && !self.upper
            && !self.lower
            && !self.titlecase
            && !self.normalize
            && self.german.is_none()
            && self.symbols.is_none()
    }

    pub fn kinds(&self) -> Vec<ActionKind> {
        let mut v = Vec::new();
        if self.replacement.is_some() {
            v.push(ActionKind::Replacement);
        }
        if self.delete {
            v.push(ActionKind::Deletion);
        }
        if self.upper {
            v.push(ActionKind::Upper);
        }
        if self.lower {
            v.push(ActionKind::Lower);
        }
        if self.titlecase {
            v.push(ActionKind::Titlecase);
        }
        if self.normalize {
            v.push(ActionKind::Normalization);
        }
        if self.german.is_some() {
            v.push(ActionKind::German);
        }
        if self.symbols.is_some() {
            v.push(ActionKind::Symbols);
        }
        v
    }

    /// Apply all actions to a single in-scope piece of text.
    pub fn apply(&self, text: &str, ctx: Option<&CaptureGroups>) -> Result<String, ActionError> {
        let mut s: String = text.to_owned();
        if let Some(r) = &self.replacement {
            s = replace::substitute(r, ctx).map_err(ActionError::Replacement)?;
        }
        if self.delete {
            s = String::new();
        }
        if self.upper {
            s = upper(&s);
        }
        if self.lower {
            s = s.to_lowercase();
        }
        if self.titlecase {
            s = titlecase::titlecase(&s);
        }
        if self.normalize {
            s = normalize::normalize(&s);
        }
        if let Some(g) = &self.german {
            s = g.apply(&s);
        }
        if let Some(sym) = &self.symbols {
            s = sym.apply(&s);
        }
        Ok(s)
    }
}

/// Uppercase, treating the German sharp s specially (it has a proper capital form).
pub fn upper(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        if c == 'ß' {
            out.push('ẞ');
        } else {
            for u in c.to_uppercase() {
                out.push(u);
            }
        }
    }
    out
}
