//! Replacement with variable substitution.

use crate::view::CaptureGroups;

#[derive(Debug)]
pub enum ReplacementError {
    UndefinedVariable(String),
    MismatchedBraces(String),
}

impl std::fmt::Display for ReplacementError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ReplacementError::UndefinedVariable(v) => write!(
                f,
                "Error in variable expressions: Undefined variable, unable to substitute: '{v}'"
            ),
            ReplacementError::MismatchedBraces(v) => write!(
                f,
                "Error in variable expressions: Mismatched braces for variable: '{v}'"
            ),
        }
    }
}

impl std::error::Error for ReplacementError {}

fn is_var_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

/// Substitute `$name`, `${name}` and `$$` in the replacement string.
pub fn substitute(replacement: &str, ctx: Option<&CaptureGroups>) -> Result<String, ReplacementError> {
    let mut out = String::with_capacity(replacement.len());
    let mut chars = replacement.char_indices().peekable();
    while let Some((i, c)) = chars.next() {
        if c != '$' {
            out.push(c);
            continue;
        }
        match chars.peek().copied() {
            Some((_, '$')) => {
                chars.next();
                out.push('$');
            }
            Some((_, '{')) => {
                chars.next();
                let mut name = String::new();
                let mut closed = false;
                while let Some((_, nc)) = chars.peek().copied() {
                    if nc == '}' {
                        chars.next();
                        closed = true;
                        break;
                    }
                    if !is_var_char(nc) {
                        break;
                    }
                    name.push(nc);
                    chars.next();
                }
                if !closed {
                    if name.is_empty() {
                        // Not a variable expression after all; emit literally.
                        out.push_str("${");
                        continue;
                    }
                    return Err(ReplacementError::MismatchedBraces(name));
                }
                if name.is_empty() {
                    out.push_str("${}");
                    continue;
                }
                let value = ctx
                    .and_then(|c| c.get(&name))
                    .ok_or_else(|| ReplacementError::UndefinedVariable(name.clone()))?;
                out.push_str(value);
            }
            Some((_, nc)) if is_var_char(nc) => {
                let mut name = String::new();
                while let Some((_, nc)) = chars.peek().copied() {
                    if !is_var_char(nc) {
                        break;
                    }
                    name.push(nc);
                    chars.next();
                }
                let value = ctx
                    .and_then(|c| c.get(&name))
                    .ok_or_else(|| ReplacementError::UndefinedVariable(name.clone()))?;
                out.push_str(value);
            }
            _ => {
                let _ = i;
                out.push('$');
            }
        }
    }
    Ok(out)
}

/// Process escape sequences in the replacement string given on the command line.
///
/// Returns `None` if an invalid escape sequence is encountered.
pub fn unescape(s: &str) -> Option<String> {
    let mut out = String::with_capacity(s.len());
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next()? {
            'b' => out.push('\u{0008}'),
            'f' => out.push('\u{000C}'),
            'n' => out.push('\n'),
            'r' => out.push('\r'),
            't' => out.push('\t'),
            '\'' => out.push('\''),
            '"' => out.push('"'),
            '\\' => out.push('\\'),
            'u' => {
                let mut hex = String::new();
                for _ in 0..4 {
                    hex.push(chars.next()?);
                }
                let v = u32::from_str_radix(&hex, 16).ok()?;
                out.push(char::from_u32(v)?);
            }
            'x' => {
                let mut hex = String::new();
                for _ in 0..2 {
                    hex.push(chars.next()?);
                }
                let v = u32::from_str_radix(&hex, 16).ok()?;
                out.push(char::from_u32(v)?);
            }
            _ => return None,
        }
    }
    Some(out)
}
