//! ASCII symbol to Unicode symbol substitution.

const FORWARD: &[(&str, &str)] = &[
    ("!=", "≠"),
    ("->", "→"),
    ("<-", "←"),
    ("=>", "⇒"),
    ("<=", "≤"),
    (">=", "≥"),
    ("--", "–"),
    ("---", "—"),
    ("-->", "⟶"),
    ("<--", "⟵"),
    ("<->", "↔"),
];

const INVERSE: &[(&str, &str)] = &[
    ("≠", "!="),
    ("→", "->"),
    ("←", "<-"),
    ("⇒", "=>"),
    ("≤", "<="),
    ("≥", ">="),
    ("–", "--"),
    ("—", "---"),
    ("⟶", "-->"),
    ("⟵", "<--"),
    ("↔", "<->"),
    ("…", "..."),
];

pub struct Symbols {
    invert: bool,
}

impl Symbols {
    pub fn new(invert: bool) -> Self {
        Self { invert }
    }

    pub fn apply(&self, s: &str) -> String {
        let table = if self.invert { INVERSE } else { FORWARD };
        let mut out = String::with_capacity(s.len());
        let mut i = 0;
        while i < s.len() {
            let rest = &s[i..];
            // Longest match wins.
            let mut best: Option<(&str, &str)> = None;
            for (from, to) in table {
                if rest.starts_with(from) {
                    if best.map_or(true, |(b, _)| from.len() > b.len()) {
                        best = Some((from, to));
                    }
                }
            }
            match best {
                Some((from, to)) => {
                    out.push_str(to);
                    i += from.len();
                }
                None => {
                    let c = rest.chars().next().unwrap();
                    out.push(c);
                    i += c.len_utf8();
                }
            }
        }
        out
    }
}
