//! Unicode normalization (NFD) with removal of combining marks.

use crate::unicode_data::{DECOMPOSITIONS, MARK_RANGES};

const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = 588;
const S_COUNT: u32 = 11172;

fn decompose_char(c: char, out: &mut String) {
    let cp = c as u32;
    if (S_BASE..S_BASE + S_COUNT).contains(&cp) {
        let s_index = cp - S_BASE;
        let l = L_BASE + s_index / N_COUNT;
        let v = V_BASE + (s_index % N_COUNT) / T_COUNT;
        let t = T_BASE + s_index % T_COUNT;
        out.push(char::from_u32(l).unwrap());
        out.push(char::from_u32(v).unwrap());
        if t != T_BASE {
            out.push(char::from_u32(t).unwrap());
        }
        return;
    }
    match DECOMPOSITIONS.binary_search_by_key(&cp, |(k, _)| *k) {
        Ok(i) => out.push_str(DECOMPOSITIONS[i].1),
        Err(_) => out.push(c),
    }
}

pub fn is_mark(c: char) -> bool {
    let cp = c as u32;
    MARK_RANGES
        .binary_search_by(|(a, b)| {
            if cp < *a {
                std::cmp::Ordering::Greater
            } else if cp > *b {
                std::cmp::Ordering::Less
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}

/// Decompose to NFD, then drop all combining marks.
pub fn normalize(s: &str) -> String {
    let mut decomposed = String::with_capacity(s.len());
    for c in s.chars() {
        decompose_char(c, &mut decomposed);
    }
    decomposed.chars().filter(|c| !is_mark(*c)).collect()
}
