//! Title-casing, following the common "small words stay lowercase" convention.

use std::sync::LazyLock;

use fancy_regex::Regex;

const SMALL_WORDS: &[&str] = &[
    "a", "an", "and", "as", "at", "but", "by", "en", "for", "if", "in", "of", "on", "or", "the",
    "to", "v", "v.", "via", "vs", "vs.",
];

const SMALL_RE: &str = r"a|an|and|as|at|but|by|en|for|if|in|of|on|or|the|to|v\.?|via|vs\.?";
const ASCII_PUNCT: &str = r"[!-/:-@\[-`{-~]";

fn is_small(w: &str) -> bool {
    let lower = w.to_lowercase();
    SMALL_WORDS.contains(&lower.as_str())
}

const WC_PUNCT: &[char] = &['_', '\'', '’', '(', ')', '[', ']', '.', ':', '@', '&', '-', '/'];
const TRANSPARENT: &[char] = &['(', '_'];
const CORE_STRIP: &[char] = &['\'', '’', '[', ']', '.', ':', '(', '_', '&', '@'];

fn is_wc(c: char) -> bool {
    c.is_alphanumeric() || WC_PUNCT.contains(&c)
}

fn is_url_char(c: char) -> bool {
    c.is_ascii_alphabetic() || c == '-' || c == '_'
}

/// Does the text start with something URL/email/domain-like?
fn starts_with_url(s: &str) -> bool {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() && is_url_char(chars[i]) {
        i += 1;
    }
    if i == 0 || i >= chars.len() {
        return false;
    }
    if !matches!(chars[i], '@' | '.' | ':') {
        return false;
    }
    i += 1;
    let start = i;
    while i < chars.len() && (is_url_char(chars[i]) || matches!(chars[i], '@' | '.' | ':' | '/')) {
        i += 1;
    }
    i > start
}

fn is_path(s: &str) -> bool {
    let mut chars = s.chars();
    if chars.next() != Some('/') {
        return false;
    }
    match chars.next() {
        Some(c) => is_wc(c) && c != '-' && c != '/',
        None => false,
    }
}

fn has_inner_caps(w: &str) -> bool {
    let mut seen = false;
    for c in w.chars() {
        if c.is_alphabetic() {
            if seen && c.is_uppercase() {
                return true;
            }
            seen = true;
        }
    }
    false
}

fn upper_char(c: char) -> char {
    c.to_uppercase().next().unwrap_or(c)
}

fn lower_char(c: char) -> char {
    c.to_lowercase().next().unwrap_or(c)
}

fn cap_at(chars: &mut [char], start: usize, end: usize) {
    let mut j = start;
    while j < end && TRANSPARENT.contains(&chars[j]) {
        j += 1;
    }
    if j < end && chars[j].is_alphabetic() {
        chars[j] = upper_char(chars[j]);
    }
}

fn process_token(tok: &str) -> String {
    let prefix_len = tok.chars().take_while(|c| *c == '_').count();
    let prefix: String = tok.chars().take(prefix_len).collect();
    let body: String = tok.chars().skip(prefix_len).collect();
    if body.is_empty() {
        return tok.to_owned();
    }
    if starts_with_url(&body) || is_path(&body) {
        return tok.to_owned();
    }
    if is_small(&body) {
        return format!("{prefix}{}", body.to_lowercase());
    }
    let chars: Vec<char> = body.chars().collect();
    let n = chars.len();
    // Parts, separated by '-' or '/'.
    let mut parts: Vec<(usize, usize)> = Vec::new();
    let mut start = 0;
    for (i, c) in chars.iter().enumerate() {
        if *c == '-' || *c == '/' {
            parts.push((start, i));
            start = i + 1;
        }
    }
    parts.push((start, n));
    let mut res = chars.clone();
    let nparts = parts.len();
    let lead_hyphen_hyphenated = chars[0] == '-'
        && nparts > 2
        && parts[1..nparts - 1]
            .iter()
            .any(|(_, e)| *e < n && chars[*e] == '-');

    for (idx, (s, e)) in parts.iter().copied().enumerate() {
        if s >= e {
            continue;
        }
        let part: String = chars[s..e].iter().collect();
        if starts_with_url(&part) && part.chars().all(|c| is_url_char(c) || matches!(c, '@' | '.' | ':' | '/')) {
            let lead: String = part.chars().take_while(|c| is_url_char(*c)).collect();
            if is_small(&lead) && idx > 0 && s >= 2 && is_wc(chars[s - 2]) {
                res[s] = upper_char(res[s]);
            }
            continue;
        }
        let coff = chars[s..e].iter().take_while(|c| CORE_STRIP.contains(c)).count();
        let core: String = chars[s + coff..e].iter().collect();
        if has_inner_caps(&part) {
            continue;
        }
        if !core.is_empty() && is_small(&core) {
            for (k, c) in core.chars().enumerate() {
                res[s + coff + k] = lower_char(c);
            }
            if idx > 0 {
                if s >= 2 && is_wc(chars[s - 2]) {
                    res[s + coff] = upper_char(res[s + coff]);
                }
            } else if coff > 0 && chars[s] == '(' {
                res[s + coff] = upper_char(res[s + coff]);
            }
            continue;
        }
        if idx == 0 {
            cap_at(&mut res, s, e);
        } else {
            let sep = chars[s - 1];
            if s >= 2 {
                let prev = chars[s - 2];
                if is_wc(prev) {
                    if sep == '-' && prev == '/' {
                        if s - 2 == 0 {
                            cap_at(&mut res, s, e);
                        }
                    } else {
                        cap_at(&mut res, s, e);
                    }
                }
            } else if sep == '-' && lead_hyphen_hyphenated {
                cap_at(&mut res, s, e);
            }
        }
    }
    let mut out = prefix;
    out.extend(res);
    out
}

fn ucfirst(w: &str) -> String {
    let mut c = w.chars();
    match c.next() {
        Some(f) => upper_char(f).to_string() + c.as_str(),
        None => String::new(),
    }
}

static RULE_START: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(&format!(
        r#"(?i)(\A{p}*|[:.;?!][ ]+|[ ]['"“‘(\[]|[ ]\([-_'’()\[\]@.:/&]*)({s})\b"#,
        p = ASCII_PUNCT,
        s = SMALL_RE
    ))
    .unwrap()
});

static RULE_END: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(&format!(
        r#"(?i)\b({s})(?={p}*\z|['"’”)\]][ ])"#,
        p = ASCII_PUNCT,
        s = SMALL_RE
    ))
    .unwrap()
});

static RULE_HYPHEN: LazyLock<Regex> = LazyLock::new(|| {
    Regex::new(&format!(r"(?i)\b({s})(?=[(_]*[-/])", s = SMALL_RE)).unwrap()
});

fn replace_all<F>(re: &Regex, s: &str, f: F) -> String
where
    F: Fn(&fancy_regex::Captures) -> String,
{
    let mut out = String::with_capacity(s.len());
    let mut last = 0;
    for caps in re.captures_iter(s).flatten() {
        let m = caps.get(0).unwrap();
        out.push_str(&s[last..m.start()]);
        out.push_str(&f(&caps));
        last = m.end();
    }
    out.push_str(&s[last..]);
    out
}

pub fn titlecase(input: &str) -> String {
    let trimmed = input.trim();
    if trimmed.is_empty() {
        return String::new();
    }
    let text: String = if trimmed.to_uppercase() == trimmed {
        trimmed.to_lowercase()
    } else {
        trimmed.to_owned()
    };

    let chars: Vec<char> = text.chars().collect();
    let mut out = String::with_capacity(text.len());
    let mut i = 0;
    while i < chars.len() {
        if is_wc(chars[i]) {
            let mut j = i;
            while j < chars.len() && is_wc(chars[j]) {
                j += 1;
            }
            let tok: String = chars[i..j].iter().collect();
            out.push_str(&process_token(&tok));
            i = j;
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }

    let out = replace_all(&RULE_START, &out, |c| {
        format!("{}{}", &c[1], ucfirst(&c[2]))
    });
    let out = replace_all(&RULE_END, &out, |c| ucfirst(&c[1]));
    replace_all(&RULE_HYPHEN, &out, |c| ucfirst(&c[1]))
}
EOF
