//! Formatting of processed views for output.

use colored::Colorize;

use crate::view::View;

/// How to display a view.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Highlight {
    None,
    Red,
    Green,
}

pub struct DisplayOptions<'a> {
    /// Label for the source, e.g. `(stdin)` or a file path.
    pub label: &'a str,
    pub tty: bool,
    pub line_numbers: bool,
    pub only_matching: bool,
    pub highlight: Highlight,
}

/// Lines of a text, with byte ranges of in-scope parts per line.
struct LineInfo<'a> {
    content: &'a str,
    ranges: Vec<(usize, usize)>,
}

fn lines_with_ranges(view: &View) -> (String, Vec<LineInfo<'static>>) {
    // Build the full text and the in-scope ranges.
    let mut text = String::new();
    let mut in_scope: Vec<(usize, usize)> = Vec::new();
    for p in &view.pieces {
        let start = text.len();
        text.push_str(&p.text);
        if p.in_scope && !p.text.is_empty() {
            in_scope.push((start, text.len()));
        }
    }
    (text, Vec::new()).0;
    // We need the lines to borrow from text; return owned text and compute lines in caller.
    let text_leaked: &'static str = Box::leak(text.clone().into_boxed_str());
    let mut lines = Vec::new();
    let mut pos = 0;
    let mut idx = 0;
    for line in text_leaked.split_inclusive('\n') {
        let ls = pos;
        let le = pos + line.len();
        let mut ranges = Vec::new();
        // Advance idx past ranges that end before this line.
        while idx < in_scope.len() && in_scope[idx].1 <= ls {
            idx += 1;
        }
        let mut k = idx;
        while k < in_scope.len() && in_scope[k].0 < le {
            let (s, e) = in_scope[k];
            let cs = s.max(ls) - ls;
            let ce = e.min(le) - ls;
            if ce > cs {
                ranges.push((cs, ce));
            }
            k += 1;
        }
        lines.push(LineInfo {
            content: line,
            ranges,
        });
        pos = le;
    }
    (text, lines)
}

/// Format a view for display. Returns the text to be written.
pub fn format_view(view: &View, opts: &DisplayOptions) -> String {
    if !opts.line_numbers && !opts.only_matching {
        return view.to_string();
    }
    let (_text, lines) = lines_with_ranges(view);
    let mut out = String::new();
    for (i, line) in lines.iter().enumerate() {
        if opts.only_matching && line.ranges.is_empty() {
            continue;
        }
        let lineno = i + 1;
        if opts.tty {
            if opts.line_numbers {
                out.push_str(&format!("{}:", lineno.to_string().green()));
            }
            let mut last = 0;
            for &(s, e) in &line.ranges {
                out.push_str(&line.content[last..s]);
                let piece = &line.content[s..e];
                match opts.highlight {
                    Highlight::None => out.push_str(piece),
                    Highlight::Red => out.push_str(&piece.red().bold().to_string()),
                    Highlight::Green => out.push_str(&piece.green().bold().to_string()),
                }
                last = e;
            }
            out.push_str(&line.content[last..]);
        } else {
            out.push_str(opts.label);
            out.push(':');
            if opts.line_numbers {
                out.push_str(&lineno.to_string());
                out.push(':');
            }
            let ranges: Vec<String> = line
                .ranges
                .iter()
                .map(|(s, e)| format!("{s}-{e}"))
                .collect();
            out.push_str(&ranges.join(";"));
            out.push(':');
            out.push_str(line.content);
        }
    }
    out
}

/// Color all in-scope pieces of a view red (for dry-run display of the original).
pub fn colorize_in_scope_red(view: &mut View) {
    for p in &mut view.pieces {
        if p.in_scope {
            p.text = p.text.red().bold().to_string();
        }
    }
}
