//! srgn - a code surgeon.

mod actions;
mod cli;
mod langs;
mod output;
mod scopers;
mod unicode_data;
mod view;

use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

use anyhow::Context;
use colored::Colorize;
use log::{debug, error, info, trace, warn};

use crate::actions::Actions;
use crate::cli::{Args, StdinDetection, StdoutDetection};
use crate::langs::LangKind;
use crate::output::{DisplayOptions, Highlight};
use crate::scopers::RegexScoper;
use crate::view::View;

/// Errors from processing a single input.
#[derive(Debug)]
enum ApplyError {
    NoneInScope,
    SomeInScope,
    Action(actions::ActionError),
}

impl std::fmt::Display for ApplyError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ApplyError::NoneInScope => write!(f, "No input was in scope"),
            ApplyError::SomeInScope => write!(f, "Some input was in scope"),
            ApplyError::Action(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for ApplyError {}

#[derive(Debug)]
enum ProgramError {
    /// Error applying to stdin.
    Applying(ApplyError),
    /// Error processing a path during the file walk.
    ProcessingPath(String),
    NoFilesFound,
    Io(std::io::Error),
    /// A bare apply error (used in file mode).
    Bare(ApplyError),
}

impl std::fmt::Display for ProgramError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProgramError::Applying(e) => write!(f, "Error applying: {e}"),
            ProgramError::ProcessingPath(e) => write!(f, "Error processing path: {e}"),
            ProgramError::NoFilesFound => write!(f, "No files found"),
            ProgramError::Io(e) => write!(f, "I/O error: {e}"),
            ProgramError::Bare(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for ProgramError {}

/// A scoper for one language, holding all its queries.
struct LangScoper {
    kind: LangKind,
    queries: Vec<langs::query::Query>,
}

impl LangScoper {
    fn ranges(&self, src: &str) -> Vec<langs::Range> {
        let mut all = Vec::new();
        for q in &self.queries {
            all.extend(q.ranges(self.kind, src));
        }
        langs::normalize_ranges(all)
    }
}

struct Pipeline {
    lang_scopers: Vec<LangScoper>,
    join: bool,
    regex: RegexScoper,
    actions: Actions,
    squeeze: bool,
    fail_any: bool,
    fail_none: bool,
}

impl Pipeline {
    /// Build the view for an input: apply all scopers.
    fn build_view(&self, input: &str) -> View {
        debug!("Building view.");
        let mut view = View::new(input);
        if self.join {
            if !self.lang_scopers.is_empty() {
                view.explode(|text| {
                    let mut all = Vec::new();
                    for s in &self.lang_scopers {
                        all.extend(s.ranges(text));
                    }
                    langs::normalize_ranges(all)
                        .into_iter()
                        .map(|r| (r, None))
                        .collect()
                });
            }
        } else {
            for s in &self.lang_scopers {
                view.explode(|text| s.ranges(text).into_iter().map(|r| (r, None)).collect());
            }
        }
        view.explode(|text| self.regex.ranges(text));
        debug!("Done building view: {view:?}");
        view
    }

    /// Scope and check fail conditions, returning the scoped view (before actions).
    fn scope(&self, input: &str) -> Result<View, ApplyError> {
        let view = self.build_view(input);
        let any = view.has_any_in_scope();
        if self.fail_any && any {
            return Err(ApplyError::SomeInScope);
        }
        if self.fail_none && !any {
            return Err(ApplyError::NoneInScope);
        }
        Ok(view)
    }

    /// Apply squeeze and all actions to the view.
    fn apply(&self, view: &mut View) -> Result<(), ApplyError> {
        if self.squeeze {
            view.squeeze();
        }
        debug!("Applying actions to view.");
        view.map_in_scope(|text, ctx| self.actions.apply(text, ctx))
            .map_err(ApplyError::Action)
    }
}

struct OutputMode {
    tty: bool,
    line_numbers: bool,
    only_matching: bool,
    search_mode: bool,
    dry_run: bool,
}

/// Process a single input, producing the text destined for the output.
fn process(pipeline: &Pipeline, input: &str, label: &str, mode: &OutputMode) -> Result<String, ApplyError> {
    let scoped = pipeline.scope(input)?;
    if mode.dry_run {
        let mut old = scoped.clone();
        let mut new = scoped;
        pipeline.apply(&mut new)?;
        if !mode.tty {
            output::colorize_in_scope_red(&mut old);
        } else if pipeline.squeeze {
            // keep as is
        }
        let opts = DisplayOptions {
            label,
            tty: mode.tty,
            line_numbers: true,
            only_matching: true,
            highlight: Highlight::None,
        };
        debug!("Writing to destination.");
        let out = output::format_dry_run(&old, &new, &opts);
        debug!("Done writing to destination.");
        return Ok(out);
    }
    let mut view = scoped;
    pipeline.apply(&mut view)?;
    let highlight = if mode.tty && mode.search_mode {
        Highlight::Red
    } else {
        Highlight::None
    };
    let opts = DisplayOptions {
        label,
        tty: mode.tty,
        line_numbers: mode.line_numbers,
        only_matching: mode.only_matching,
        highlight,
    };
    debug!("Writing to destination.");
    let out = output::format_view(&view, &opts);
    debug!("Done writing to destination.");
    Ok(out)
}

fn is_stdin_readable() -> bool {
    use std::os::unix::fs::FileTypeExt;
    let stdin = std::io::stdin();
    let fd = std::os::fd::AsRawFd::as_raw_fd(&stdin);
    let mut st: libc::stat = unsafe { std::mem::zeroed() };
    if unsafe { libc::fstat(fd, &mut st) } != 0 {
        return false;
    }
    let mode = st.st_mode & libc::S_IFMT;
    let is_file = mode == libc::S_IFREG;
    let is_fifo = mode == libc::S_IFIFO;
    let is_socket = mode == libc::S_IFSOCK;
    let _ = FileTypeExt::is_fifo;
    let is_readable = is_file || is_fifo || is_socket;
    debug!(
        target: "grep_cli",
        "for heuristic stdin detection on Unix, found that is_file={is_file}, is_fifo={is_fifo} and is_socket={is_socket}, and thus concluded that is_stdin_readable={is_readable}"
    );
    is_readable
}

fn is_stdout_tty() -> bool {
    unsafe { libc::isatty(1) == 1 }
}

fn init_logging(verbosity: u8) {
    use log::LevelFilter;
    let base = std::env::var("RUST_LOG").ok();
    let base_level = match base.as_deref().map(|s| s.trim().to_lowercase()) {
        None => LevelFilter::Error,
        Some(s) => match s.as_str() {
            "off" => LevelFilter::Off,
            "error" => LevelFilter::Error,
            "warn" => LevelFilter::Warn,
            "info" => LevelFilter::Info,
            "debug" => LevelFilter::Debug,
            "trace" => LevelFilter::Trace,
            _ => LevelFilter::Error,
        },
    };
    let levels = [
        LevelFilter::Off,
        LevelFilter::Error,
        LevelFilter::Warn,
        LevelFilter::Info,
        LevelFilter::Debug,
        LevelFilter::Trace,
    ];
    let idx = levels.iter().position(|l| *l == base_level).unwrap_or(1);
    let level = levels[(idx + verbosity as usize).min(levels.len() - 1)];
    let mut builder = env_logger::Builder::new();
    builder
        .filter_level(level)
        .format_timestamp_micros()
        .init();
}

fn main() {
    let code = match run() {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("Error: {e:?}");
            1
        }
    };
    std::process::exit(code);
}

fn build_pipeline(args: &Args) -> anyhow::Result<Pipeline> {
    debug!("Assembling scopers.");
    let mut lang_scopers = Vec::new();
    for ls in args.languages_scopes.all() {
        let mut queries = Vec::new();
        for p in &ls.prepared {
            queries.push(langs::query::Query::Prepared(p.clone()));
        }
        for q in &ls.queries {
            queries.push(langs::query::Query::parse(&q.0).context("Failed parsing tree-sitter query")?);
        }
        for f in &ls.query_files {
            let contents = std::fs::read_to_string(f).map_err(ProgramError::Io)?;
            queries.push(
                langs::query::Query::parse(&contents).context("Failed parsing tree-sitter query")?,
            );
        }
        lang_scopers.push(LangScoper {
            kind: ls.kind,
            queries,
        });
    }
    let regex = if args.options.literal_string {
        RegexScoper::from_literal(&args.scope)
    } else {
        RegexScoper::new(&args.scope).context("Failed building regex")?
    };
    debug!("Done assembling scopers.");

    debug!("Assembling actions.");
    let replacement = match &args.composable_actions.replace {
        Some(r) => Some(
            actions::replace::unescape(r)
                .ok_or_else(|| anyhow::anyhow!("Contains invalid escape sequences: '{r}'"))
                .context("Failed building replacement string")?,
        ),
        None => None,
    };
    let actions = Actions {
        replacement,
        delete: args.standalone_actions.delete,
        upper: args.composable_actions.upper,
        lower: args.composable_actions.lower,
        titlecase: args.composable_actions.titlecase,
        normalize: args.composable_actions.normalize,
        german: if args.composable_actions.german {
            Some(actions::german::German::new(
                args.german_options.german_prefer_original,
                args.german_options.german_naive,
            ))
        } else {
            None
        },
        symbols: if args.composable_actions.symbols {
            Some(actions::symbols::Symbols::new(args.options.invert))
        } else {
            None
        },
    };
    for k in actions.kinds() {
        debug!("Loaded action: {k:?}");
    }
    debug!("Done assembling actions.");

    Ok(Pipeline {
        lang_scopers,
        join: args.options.join_language_scopes,
        regex,
        actions,
        squeeze: args.standalone_actions.squeeze,
        fail_any: args.options.fail_any,
        fail_none: args.options.fail_none,
    })
}

fn run() -> anyhow::Result<()> {
    let cmd = cli::build_command();
    let matches = cmd.get_matches();
    let args = cli::args_from_matches(&matches);

    init_logging(args.options.additional_verbosity);
    info!("Launching app with args: {args:?}");

    if let Some(shell) = args.shell {
        let mut cmd = cli::build_command();
        clap_complete::generate(shell, &mut cmd, cli::BIN_NAME, &mut std::io::stdout());
        return Ok(());
    }

    if args.options.literal_string && !cli::scope_explicitly_given(&matches) {
        let mut cmd = cli::build_command();
        cmd.build();
        let err = cmd.error(
            clap::error::ErrorKind::MissingRequiredArgument,
            "The following required argument was not provided: scope",
        );
        err.exit();
    }

    let mut pipeline = build_pipeline(&args)?;

    debug!("Detecting if stdout is a TTY");
    let tty = match args.options.stdout_detection {
        StdoutDetection::Auto => is_stdout_tty(),
        StdoutDetection::ForceTty => true,
        StdoutDetection::ForcePipe => false,
    };
    info!("Treating stdout as tty: {tty}.");

    let stdin_readable = match args.options.stdin_detection {
        StdinDetection::Auto => {
            debug!("Detecting if stdin is readable");
            is_stdin_readable()
        }
        StdinDetection::ForceReadable => true,
        StdinDetection::ForceUnreadable => false,
    };
    info!("Treating stdin as readable: {stdin_readable}.");

    let has_langs = !args.languages_scopes.is_empty();
    let search_mode = has_langs && pipeline.actions.is_empty();
    let dry_run = args.options.dry_run;

    if search_mode || dry_run {
        info!("Will use search mode.");
        pipeline.fail_none = true;
    } else if pipeline.actions.is_empty() {
        error!("No actions specified, and not in search mode. Will return input unchanged, if any.");
    }

    let mode = OutputMode {
        tty,
        line_numbers: args.options.line_numbers || search_mode || dry_run,
        only_matching: args.options.only_matching || search_mode || dry_run,
        search_mode,
        dry_run,
    };

    let wants_files = args.options.glob.is_some() || has_langs;

    if stdin_readable {
        if wants_files {
            error!("Detected stdin, and request for files: will use stdin and ignore files.");
        }
        info!("Will read from stdin and write to stdout, applying actions.");
        info!("Will use stdin to stdout.");
        run_stdin(&pipeline, &mode)?;
    } else if wants_files {
        info!("Will walk file tree, applying actions.");
        run_files(&pipeline, &args, &mode)?;
    } else {
        info!("Will read from stdin and write to stdout, applying actions.");
        info!("Will use stdin to stdout.");
        run_stdin(&pipeline, &mode)?;
    }

    info!("Done, exiting");
    Ok(())
}

fn run_stdin(pipeline: &Pipeline, mode: &OutputMode) -> anyhow::Result<()> {
    let mut input = String::new();
    std::io::stdin()
        .read_to_string(&mut input)
        .map_err(ProgramError::Io)?;
    let out = process(pipeline, &input, "(stdin)", mode).map_err(ProgramError::Applying)?;
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes()).map_err(ProgramError::Io)?;
    lock.flush().map_err(ProgramError::Io)?;
    Ok(())
}

/// Whether a file path is of interest for the given languages.
fn language_matches(path: &Path, kinds: &[LangKind]) -> bool {
    let ext = match path.extension().and_then(|e| e.to_str()) {
        Some(e) => e,
        None => return false,
    };
    kinds
        .iter()
        .any(|k| langs::LANG_SPECS[*k as usize].extensions.contains(&ext))
}

struct FileResult {
    output: String,
}

/// Process one file. Returns the output to print (if any).
fn process_file(
    pipeline: &Pipeline,
    abs_path: &Path,
    rel_path: &Path,
    mode: &OutputMode,
) -> Result<Option<FileResult>, ProgramError> {
    let label = rel_path.to_string_lossy().into_owned();
    debug!("Processing path: {label}");
    let bytes = std::fs::read(abs_path).map_err(ProgramError::Io)?;
    let contents = match String::from_utf8(bytes) {
        Ok(s) => s,
        Err(_) => {
            warn!(
                "File contains unreadable data (binary? invalid utf-8?), skipped: {}",
                abs_path.display()
            );
            return Ok(None);
        }
    };

    let scoped = match pipeline.scope(&contents) {
        Ok(v) => v,
        Err(ApplyError::SomeInScope) => {
            info!("Match at {}, exiting early", abs_path.display());
            return Err(ProgramError::Bare(ApplyError::SomeInScope));
        }
        Err(ApplyError::NoneInScope) => {
            // Nothing in scope in this file: not an error on its own.
            return Ok(None);
        }
        Err(e) => return Err(ProgramError::Applying(e)),
    };
    if !scoped.has_any_in_scope() {
        return Ok(None);
    }

    if mode.dry_run {
        let mut old = scoped.clone();
        let mut new = scoped;
        pipeline.apply(&mut new).map_err(ProgramError::Applying)?;
        if !mode.tty {
            output::colorize_in_scope_red(&mut old);
        }
        let opts = DisplayOptions {
            label: &label,
            tty: mode.tty,
            line_numbers: true,
            only_matching: true,
            highlight: Highlight::None,
        };
        let body = output::format_dry_run(&old, &new, &opts);
        let output = if mode.tty {
            format!("{}\n{}\n", label.magenta(), body)
        } else {
            body
        };
        return Ok(Some(FileResult { output }));
    }

    let mut view = scoped;
    pipeline.apply(&mut view).map_err(ProgramError::Applying)?;

    if mode.search_mode {
        let opts = DisplayOptions {
            label: &label,
            tty: mode.tty,
            line_numbers: true,
            only_matching: true,
            highlight: if mode.tty { Highlight::Red } else { Highlight::None },
        };
        debug!("Writing to destination.");
        let body = output::format_view(&view, &opts);
        debug!("Done writing to destination.");
        let output = if mode.tty {
            format!("{}\n{}\n", label.magenta(), body)
        } else {
            body
        };
        return Ok(Some(FileResult { output }));
    }

    // In-place processing.
    let opts = DisplayOptions {
        label: &label,
        tty: mode.tty,
        line_numbers: mode.line_numbers,
        only_matching: mode.only_matching,
        highlight: Highlight::None,
    };
    debug!("Writing to destination.");
    let new_contents = output::format_view(&view, &opts);
    debug!("Done writing to destination.");
    if new_contents != contents {
        debug!("Got new file contents, writing to file: {label}");
        std::fs::write(abs_path, new_contents.as_bytes()).map_err(ProgramError::Io)?;
        debug!("Done processing file: {label}");
        return Ok(Some(FileResult {
            output: format!("{label}\n"),
        }));
    }
    debug!("Done processing file: {label}");
    Ok(None)
}

fn run_files(pipeline: &Pipeline, args: &Args, mode: &OutputMode) -> anyhow::Result<()> {
    let root = std::env::current_dir();
    let kinds: Vec<LangKind> = args.languages_scopes.all().iter().map(|l| l.kind).collect();
    let glob = args.options.glob.clone();

    let root_path: PathBuf = match &root {
        Ok(r) => r.clone(),
        Err(e) => {
            return Err(ProgramError::Io(std::io::Error::new(e.kind(), e.to_string())).into());
        }
    };

    let mut builder = ignore::WalkBuilder::new(&root_path);
    builder
        .hidden(!args.options.hidden)
        .git_ignore(!args.options.gitignored);

    let n_seen = Arc::new(AtomicUsize::new(0));
    let n_processed = Arc::new(AtomicUsize::new(0));
    let any_in_scope = Arc::new(AtomicBool::new(false));
    let first_error: Arc<Mutex<Option<ProgramError>>> = Arc::new(Mutex::new(None));
    let stdout_lock = Arc::new(Mutex::new(()));

    let is_wanted = |path: &Path| -> Option<PathBuf> {
        if !path.is_file() {
            return None;
        }
        let rel = path.strip_prefix(&root_path).unwrap_or(path).to_path_buf();
        if let Some(g) = &glob {
            if !g.matches_path(&rel) {
                return None;
            }
        } else if !language_matches(&rel, &kinds) {
            return None;
        }
        Some(rel)
    };

    let handle = |abs: &Path, rel: &Path| -> Result<bool, ProgramError> {
        n_seen.fetch_add(1, Ordering::SeqCst);
        match process_file(pipeline, abs, rel, mode) {
            Ok(Some(res)) => {
                n_processed.fetch_add(1, Ordering::SeqCst);
                any_in_scope.store(true, Ordering::SeqCst);
                let _g = stdout_lock.lock().unwrap();
                let stdout = std::io::stdout();
                let mut lock = stdout.lock();
                let _ = lock.write_all(res.output.as_bytes());
                let _ = lock.flush();
                Ok(true)
            }
            Ok(None) => Ok(true),
            Err(e) => Err(e),
        }
    };

    if args.options.sorted {
        info!(
            "Will walk file tree sequentially, in sorted order, starting from: {root:?}"
        );
        builder.sort_by_file_path(|a, b| a.cmp(b));
        for entry in builder.build() {
            let entry = match entry {
                Ok(e) => e,
                Err(e) => {
                    error!("Error walking: {e}");
                    continue;
                }
            };
            let path = entry.path();
            let rel = match is_wanted(path) {
                Some(r) => r,
                None => continue,
            };
            match handle(path, &rel) {
                Ok(_) => {}
                Err(e) => {
                    if mode.search_mode || mode.dry_run {
                        if let ProgramError::Bare(ApplyError::SomeInScope) = e {
                            return Err(e.into());
                        }
                        error!("Error walking at {}: {e}", path.display());
                    } else {
                        if let ProgramError::Bare(ApplyError::SomeInScope) = e {
                            return Err(e.into());
                        }
                        error!("Aborting walk at {} due to: {e}", path.display());
                        return Err(ProgramError::ProcessingPath(e.to_string()).into());
                    }
                }
            }
        }
    } else {
        let threads = args
            .options
            .threads
            .map(|t| t.get())
            .unwrap_or_else(|| std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1));
        info!(
            "Will walk file tree using {threads} thread(s), processing in arbitrary order, starting from: {root:?}"
        );
        builder.threads(threads);
        let walker = builder.build_parallel();
        let first_error = first_error.clone();
        let abort = Arc::new(AtomicBool::new(false));
        walker.run(|| {
            let first_error = first_error.clone();
            let abort = abort.clone();
            let is_wanted = &is_wanted;
            let handle = &handle;
            Box::new(move |entry| {
                use ignore::WalkState;
                if abort.load(Ordering::SeqCst) {
                    return WalkState::Quit;
                }
                let entry = match entry {
                    Ok(e) => e,
                    Err(e) => {
                        error!("Error walking: {e}");
                        return WalkState::Continue;
                    }
                };
                let path = entry.path();
                let rel = match is_wanted(path) {
                    Some(r) => r,
                    None => return WalkState::Continue,
                };
                match handle(path, &rel) {
                    Ok(_) => WalkState::Continue,
                    Err(e) => {
                        let is_some_in_scope = matches!(e, ProgramError::Bare(ApplyError::SomeInScope));
                        if (mode.search_mode || mode.dry_run) && !is_some_in_scope {
                            error!("Error walking at {}: {e}", path.display());
                            WalkState::Continue
                        } else {
                            if !is_some_in_scope {
                                error!("Aborting walk at {} due to: {e}", path.display());
                            }
                            let mut fe = first_error.lock().unwrap();
                            if fe.is_none() {
                                *fe = Some(if is_some_in_scope {
                                    e
                                } else {
                                    ProgramError::ProcessingPath(e.to_string())
                                });
                            }
                            abort.store(true, Ordering::SeqCst);
                            WalkState::Quit
                        }
                    }
                }
            })
        });
        if let Some(e) = first_error.lock().unwrap().take() {
            return Err(e.into());
        }
    }

    let seen = n_seen.load(Ordering::SeqCst);
    let processed = n_processed.load(Ordering::SeqCst);
    info!("Saw {seen} items");
    info!("Processed {processed} files");

    if seen == 0 && args.options.fail_no_files {
        return Err(ProgramError::NoFilesFound.into());
    }
    if (mode.search_mode || mode.dry_run || pipeline.fail_none) && !any_in_scope.load(Ordering::SeqCst) {
        return Err(ProgramError::Bare(ApplyError::NoneInScope).into());
    }
    trace!("All done");
    Ok(())
}
EOF
echo ok"}

actions.command:
cat > /workspace/src/main.rs <<'EOF'
//! srgn - a code surgeon.

mod actions;
mod cli;
mod langs;
mod output;
mod scopers;
mod unicode_data;
mod view;

use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

use anyhow::Context;
use colored::Colorize;
use log::{debug, error, info, trace, warn};

use crate::actions::Actions;
use crate::cli::{Args, StdinDetection, StdoutDetection};
use crate::langs::LangKind;
use crate::output::{DisplayOptions, Highlight};
use crate::scopers::RegexScoper;
use crate::view::View;

/// Errors from processing a single input.
#[derive(Debug)]
enum ApplyError {
    NoneInScope,
    SomeInScope,
    Action(actions::ActionError),
}

impl std::fmt::Display for ApplyError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ApplyError::NoneInScope => write!(f, "No input was in scope"),
            ApplyError::SomeInScope => write!(f, "Some input was in scope"),
            ApplyError::Action(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for ApplyError {}

#[derive(Debug)]
enum ProgramError {
    /// Error applying to stdin.
    Applying(ApplyError),
    /// Error processing a path during the file walk.
    ProcessingPath(String),
    NoFilesFound,
    Io(std::io::Error),
    /// A bare apply error (used in file mode).
    Bare(ApplyError),
}

impl std::fmt::Display for ProgramError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProgramError::Applying(e) => write!(f, "Error applying: {e}"),
            ProgramError::ProcessingPath(e) => write!(f, "Error processing path: {e}"),
            ProgramError::NoFilesFound => write!(f, "No files found"),
            ProgramError::Io(e) => write!(f, "I/O error: {e}"),
            ProgramError::Bare(e) => write!(f, "{e}"),
        }
    }
}

impl std::error::Error for ProgramError {}

/// A scoper for one language, holding all its queries.
struct LangScoper {
    kind: LangKind,
    queries: Vec<langs::query::Query>,
}

impl LangScoper {
    fn ranges(&self, src: &str) -> Vec<langs::Range> {
        let mut all = Vec::new();
        for q in &self.queries {
            all.extend(q.ranges(self.kind, src));
        }
        langs::normalize_ranges(all)
    }
}

struct Pipeline {
    lang_scopers: Vec<LangScoper>,
    join: bool,
    regex: RegexScoper,
    actions: Actions,
    squeeze: bool,
    fail_any: bool,
    fail_none: bool,
}

impl Pipeline {
    /// Build the view for an input: apply all scopers.
    fn build_view(&self, input: &str) -> View {
        debug!("Building view.");
        let mut view = View::new(input);
        if self.join {
            if !self.lang_scopers.is_empty() {
                view.explode(|text| {
                    let mut all = Vec::new();
                    for s in &self.lang_scopers {
                        all.extend(s.ranges(text));
                    }
                    langs::normalize_ranges(all)
                        .into_iter()
                        .map(|r| (r, None))
                        .collect()
                });
            }
        } else {
            for s in &self.lang_scopers {
                view.explode(|text| s.ranges(text).into_iter().map(|r| (r, None)).collect());
            }
        }
        view.explode(|text| self.regex.ranges(text));
        debug!("Done building view: {view:?}");
        view
    }

    /// Scope and check fail conditions, returning the scoped view (before actions).
    fn scope(&self, input: &str) -> Result<View, ApplyError> {
        let view = self.build_view(input);
        let any = view.has_any_in_scope();
        if self.fail_any && any {
            return Err(ApplyError::SomeInScope);
        }
        if self.fail_none && !any {
            return Err(ApplyError::NoneInScope);
        }
        Ok(view)
    }

    /// Apply squeeze and all actions to the view.
    fn apply(&self, view: &mut View) -> Result<(), ApplyError> {
        if self.squeeze {
            view.squeeze();
        }
        debug!("Applying actions to view.");
        view.map_in_scope(|text, ctx| self.actions.apply(text, ctx))
            .map_err(ApplyError::Action)
    }
}

struct OutputMode {
    tty: bool,
    line_numbers: bool,
    only_matching: bool,
    search_mode: bool,
    dry_run: bool,
}

/// Process a single input, producing the text destined for the output.
fn process(pipeline: &Pipeline, input: &str, label: &str, mode: &OutputMode) -> Result<String, ApplyError> {
    let scoped = pipeline.scope(input)?;
    if mode.dry_run {
        let mut old = scoped.clone();
        let mut new = scoped;
        pipeline.apply(&mut new)?;
        if !mode.tty {
            output::colorize_in_scope_red(&mut old);
        } else if pipeline.squeeze {
            // keep as is
        }
        let opts = DisplayOptions {
            label,
            tty: mode.tty,
            line_numbers: true,
            only_matching: true,
            highlight: Highlight::None,
        };
        debug!("Writing to destination.");
        let out = output::format_dry_run(&old, &new, &opts);
        debug!("Done writing to destination.");
        return Ok(out);
    }
    let mut view = scoped;
    pipeline.apply(&mut view)?;
    let highlight = if mode.tty && mode.search_mode {
        Highlight::Red
    } else {
        Highlight::None
    };
    let opts = DisplayOptions {
        label,
        tty: mode.tty,
        line_numbers: mode.line_numbers,
        only_matching: mode.only_matching,
        highlight,
    };
    debug!("Writing to destination.");
    let out = output::format_view(&view, &opts);
    debug!("Done writing to destination.");
    Ok(out)
}

fn is_stdin_readable() -> bool {
    use std::os::unix::fs::FileTypeExt;
    let stdin = std::io::stdin();
    let fd = std::os::fd::AsRawFd::as_raw_fd(&stdin);
    let mut st: libc::stat = unsafe { std::mem::zeroed() };
    if unsafe { libc::fstat(fd, &mut st) } != 0 {
        return false;
    }
    let mode = st.st_mode & libc::S_IFMT;
    let is_file = mode == libc::S_IFREG;
    let is_fifo = mode == libc::S_IFIFO;
    let is_socket = mode == libc::S_IFSOCK;
    let _ = FileTypeExt::is_fifo;
    let is_readable = is_file || is_fifo || is_socket;
    debug!(
        target: "grep_cli",
        "for heuristic stdin detection on Unix, found that is_file={is_file}, is_fifo={is_fifo} and is_socket={is_socket}, and thus concluded that is_stdin_readable={is_readable}"
    );
    is_readable
}

fn is_stdout_tty() -> bool {
    unsafe { libc::isatty(1) == 1 }
}

fn init_logging(verbosity: u8) {
    use log::LevelFilter;
    let base = std::env::var("RUST_LOG").ok();
    let base_level = match base.as_deref().map(|s| s.trim().to_lowercase()) {
        None => LevelFilter::Error,
        Some(s) => match s.as_str() {
            "off" => LevelFilter::Off,
            "error" => LevelFilter::Error,
            "warn" => LevelFilter::Warn,
            "info" => LevelFilter::Info,
            "debug" => LevelFilter::Debug,
            "trace" => LevelFilter::Trace,
            _ => LevelFilter::Error,
        },
    };
    let levels = [
        LevelFilter::Off,
        LevelFilter::Error,
        LevelFilter::Warn,
        LevelFilter::Info,
        LevelFilter::Debug,
        LevelFilter::Trace,
    ];
    let idx = levels.iter().position(|l| *l == base_level).unwrap_or(1);
    let level = levels[(idx + verbosity as usize).min(levels.len() - 1)];
    let mut builder = env_logger::Builder::new();
    builder
        .filter_level(level)
        .format_timestamp_micros()
        .init();
}

fn main() {
    let code = match run() {
        Ok(()) => 0,
        Err(e) => {
            eprintln!("Error: {e:?}");
            1
        }
    };
    std::process::exit(code);
}

fn build_pipeline(args: &Args) -> anyhow::Result<Pipeline> {
    debug!("Assembling scopers.");
    let mut lang_scopers = Vec::new();
    for ls in args.languages_scopes.all() {
        let mut queries = Vec::new();
        for p in &ls.prepared {
            queries.push(langs::query::Query::Prepared(p.clone()));
        }
        for q in &ls.queries {
            queries.push(langs::query::Query::parse(&q.0).context("Failed parsing tree-sitter query")?);
        }
        for f in &ls.query_files {
            let contents = std::fs::read_to_string(f).map_err(ProgramError::Io)?;
            queries.push(
                langs::query::Query::parse(&contents).context("Failed parsing tree-sitter query")?,
            );
        }
        lang_scopers.push(LangScoper {
            kind: ls.kind,
            queries,
        });
    }
    let regex = if args.options.literal_string {
        RegexScoper::from_literal(&args.scope)
    } else {
        RegexScoper::new(&args.scope).context("Failed building regex")?
    };
    debug!("Done assembling scopers.");

    debug!("Assembling actions.");
    let replacement = match &args.composable_actions.replace {
        Some(r) => Some(
            actions::replace::unescape(r)
                .ok_or_else(|| anyhow::anyhow!("Contains invalid escape sequences: '{r}'"))
                .context("Failed building replacement string")?,
        ),
        None => None,
    };
    let actions = Actions {
        replacement,
        delete: args.standalone_actions.delete,
        upper: args.composable_actions.upper,
        lower: args.composable_actions.lower,
        titlecase: args.composable_actions.titlecase,
        normalize: args.composable_actions.normalize,
        german: if args.composable_actions.german {
            Some(actions::german::German::new(
                args.german_options.german_prefer_original,
                args.german_options.german_naive,
            ))
        } else {
            None
        },
        symbols: if args.composable_actions.symbols {
            Some(actions::symbols::Symbols::new(args.options.invert))
        } else {
            None
        },
    };
    for k in actions.kinds() {
        debug!("Loaded action: {k:?}");
    }
    debug!("Done assembling actions.");

    Ok(Pipeline {
        lang_scopers,
        join: args.options.join_language_scopes,
        regex,
        actions,
        squeeze: args.standalone_actions.squeeze,
        fail_any: args.options.fail_any,
        fail_none: args.options.fail_none,
    })
}

fn run() -> anyhow::Result<()> {
    let cmd = cli::build_command();
    let matches = cmd.get_matches();
    let args = cli::args_from_matches(&matches);

    init_logging(args.options.additional_verbosity);
    info!("Launching app with args: {args:?}");

    if let Some(shell) = args.shell {
        let mut cmd = cli::build_command();
        clap_complete::generate(shell, &mut cmd, cli::BIN_NAME, &mut std::io::stdout());
        return Ok(());
    }

    if args.options.literal_string && !cli::scope_explicitly_given(&matches) {
        let mut cmd = cli::build_command();
        cmd.build();
        let err = cmd.error(
            clap::error::ErrorKind::MissingRequiredArgument,
            "The following required argument was not provided: scope",
        );
        err.exit();
    }

    let mut pipeline = build_pipeline(&args)?;

    debug!("Detecting if stdout is a TTY");
    let tty = match args.options.stdout_detection {
        StdoutDetection::Auto => is_stdout_tty(),
        StdoutDetection::ForceTty => true,
        StdoutDetection::ForcePipe => false,
    };
    info!("Treating stdout as tty: {tty}.");

    let stdin_readable = match args.options.stdin_detection {
        StdinDetection::Auto => {
            debug!("Detecting if stdin is readable");
            is_stdin_readable()
        }
        StdinDetection::ForceReadable => true,
        StdinDetection::ForceUnreadable => false,
    };
    info!("Treating stdin as readable: {stdin_readable}.");

    let has_langs = !args.languages_scopes.is_empty();
    let search_mode = has_langs && pipeline.actions.is_empty();
    let dry_run = args.options.dry_run;

    if search_mode || dry_run {
        info!("Will use search mode.");
        pipeline.fail_none = true;
    } else if pipeline.actions.is_empty() {
        error!("No actions specified, and not in search mode. Will return input unchanged, if any.");
    }

    let mode = OutputMode {
        tty,
        line_numbers: args.options.line_numbers || search_mode || dry_run,
        only_matching: args.options.only_matching || search_mode || dry_run,
        search_mode,
        dry_run,
    };

    let wants_files = args.options.glob.is_some() || has_langs;

    if stdin_readable {
        if wants_files {
            error!("Detected stdin, and request for files: will use stdin and ignore files.");
        }
        info!("Will read from stdin and write to stdout, applying actions.");
        info!("Will use stdin to stdout.");
        run_stdin(&pipeline, &mode)?;
    } else if wants_files {
        info!("Will walk file tree, applying actions.");
        run_files(&pipeline, &args, &mode)?;
    } else {
        info!("Will read from stdin and write to stdout, applying actions.");
        info!("Will use stdin to stdout.");
        run_stdin(&pipeline, &mode)?;
    }

    info!("Done, exiting");
    Ok(())
}

fn run_stdin(pipeline: &Pipeline, mode: &OutputMode) -> anyhow::Result<()> {
    let mut input = String::new();
    std::io::stdin()
        .read_to_string(&mut input)
        .map_err(ProgramError::Io)?;
    let out = process(pipeline, &input, "(stdin)", mode).map_err(ProgramError::Applying)?;
    let stdout = std::io::stdout();
    let mut lock = stdout.lock();
    lock.write_all(out.as_bytes()).map_err(ProgramError::Io)?;
    lock.flush().map_err(ProgramError::Io)?;
    Ok(())
}

/// Whether a file path is of interest for the given languages.
fn language_matches(path: &Path, kinds: &[LangKind]) -> bool {
    let ext = match path.extension().and_then(|e| e.to_str()) {
        Some(e) => e,
        None => return false,
    };
    kinds
        .iter()
        .any(|k| langs::LANG_SPECS[*k as usize].extensions.contains(&ext))
}

struct FileResult {
    output: String,
}

/// Process one file. Returns the output to print (if any).
fn process_file(
    pipeline: &Pipeline,
    abs_path: &Path,
    rel_path: &Path,
    mode: &OutputMode,
) -> Result<Option<FileResult>, ProgramError> {
    let label = rel_path.to_string_lossy().into_owned();
    debug!("Processing path: {label}");
    let bytes = std::fs::read(abs_path).map_err(ProgramError::Io)?;
    let contents = match String::from_utf8(bytes) {
        Ok(s) => s,
        Err(_) => {
            warn!(
                "File contains unreadable data (binary? invalid utf-8?), skipped: {}",
                abs_path.display()
            );
            return Ok(None);
        }
    };

    let scoped = match pipeline.scope(&contents) {
        Ok(v) => v,
        Err(ApplyError::SomeInScope) => {
            info!("Match at {}, exiting early", abs_path.display());
            return Err(ProgramError::Bare(ApplyError::SomeInScope));
        }
        Err(ApplyError::NoneInScope) => {
            // Nothing in scope in this file: not an error on its own.
            return Ok(None);
        }
        Err(e) => return Err(ProgramError::Applying(e)),
    };
    if !scoped.has_any_in_scope() {
        return Ok(None);
    }

    if mode.dry_run {
        let mut old = scoped.clone();
        let mut new = scoped;
        pipeline.apply(&mut new).map_err(ProgramError::Applying)?;
        if !mode.tty {
            output::colorize_in_scope_red(&mut old);
        }
        let opts = DisplayOptions {
            label: &label,
            tty: mode.tty,
            line_numbers: true,
            only_matching: true,
            highlight: Highlight::None,
        };
        let body = output::format_dry_run(&old, &new, &opts);
        let output = if mode.tty {
            format!("{}\n{}\n", label.magenta(), body)
        } else {
            body
        };
        return Ok(Some(FileResult { output }));
    }

    let mut view = scoped;
    pipeline.apply(&mut view).map_err(ProgramError::Applying)?;

    if mode.search_mode {
        let opts = DisplayOptions {
            label: &label,
            tty: mode.tty,
            line_numbers: true,
            only_matching: true,
            highlight: if mode.tty { Highlight::Red } else { Highlight::None },
        };
        debug!("Writing to destination.");
        let body = output::format_view(&view, &opts);
        debug!("Done writing to destination.");
        let output = if mode.tty {
            format!("{}\n{}\n", label.magenta(), body)
        } else {
            body
        };
        return Ok(Some(FileResult { output }));
    }

    // In-place processing.
    let opts = DisplayOptions {
        label: &label,
        tty: mode.tty,
        line_numbers: mode.line_numbers,
        only_matching: mode.only_matching,
        highlight: Highlight::None,
    };
    debug!("Writing to destination.");
    let new_contents = output::format_view(&view, &opts);
    debug!("Done writing to destination.");
    if new_contents != contents {
        debug!("Got new file contents, writing to file: {label}");
        std::fs::write(abs_path, new_contents.as_bytes()).map_err(ProgramError::Io)?;
        debug!("Done processing file: {label}");
        return Ok(Some(FileResult {
            output: format!("{label}\n"),
        }));
    }
    debug!("Done processing file: {label}");
    Ok(None)
}

fn run_files(pipeline: &Pipeline, args: &Args, mode: &OutputMode) -> anyhow::Result<()> {
    let root = std::env::current_dir();
    let kinds: Vec<LangKind> = args.languages_scopes.all().iter().map(|l| l.kind).collect();
    let glob = args.options.glob.clone();

    let root_path: PathBuf = match &root {
        Ok(r) => r.clone(),
        Err(e) => {
            return Err(ProgramError::Io(std::io::Error::new(e.kind(), e.to_string())).into());
        }
    };

    let mut builder = ignore::WalkBuilder::new(&root_path);
    builder
        .hidden(!args.options.hidden)
        .git_ignore(!args.options.gitignored);

    let n_seen = Arc::new(AtomicUsize::new(0));
    let n_processed = Arc::new(AtomicUsize::new(0));
    let any_in_scope = Arc::new(AtomicBool::new(false));
    let first_error: Arc<Mutex<Option<ProgramError>>> = Arc::new(Mutex::new(None));
    let stdout_lock = Arc::new(Mutex::new(()));

    let is_wanted = |path: &Path| -> Option<PathBuf> {
        if !path.is_file() {
            return None;
        }
        let rel = path.strip_prefix(&root_path).unwrap_or(path).to_path_buf();
        if let Some(g) = &glob {
            if !g.matches_path(&rel) {
                return None;
            }
        } else if !language_matches(&rel, &kinds) {
            return None;
        }
        Some(rel)
    };

    let handle = |abs: &Path, rel: &Path| -> Result<bool, ProgramError> {
        n_seen.fetch_add(1, Ordering::SeqCst);
        match process_file(pipeline, abs, rel, mode) {
            Ok(Some(res)) => {
                n_processed.fetch_add(1, Ordering::SeqCst);
                any_in_scope.store(true, Ordering::SeqCst);
                let _g = stdout_lock.lock().unwrap();
                let stdout = std::io::stdout();
                let mut lock = stdout.lock();
                let _ = lock.write_all(res.output.as_bytes());
                let _ = lock.flush();
                Ok(true)
            }
            Ok(None) => Ok(true),
            Err(e) => Err(e),
        }
    };

    if args.options.sorted {
        info!(
            "Will walk file tree sequentially, in sorted order, starting from: {root:?}"
        );
        builder.sort_by_file_path(|a, b| a.cmp(b));
        for entry in builder.build() {
            let entry = match entry {
                Ok(e) => e,
                Err(e) => {
                    error!("Error walking: {e}");
                    continue;
                }
            };
            let path = entry.path();
            let rel = match is_wanted(path) {
                Some(r) => r,
                None => continue,
            };
            match handle(path, &rel) {
                Ok(_) => {}
                Err(e) => {
                    if mode.search_mode || mode.dry_run {
                        if let ProgramError::Bare(ApplyError::SomeInScope) = e {
                            return Err(e.into());
                        }
                        error!("Error walking at {}: {e}", path.display());
                    } else {
                        if let ProgramError::Bare(ApplyError::SomeInScope) = e {
                            return Err(e.into());
                        }
                        error!("Aborting walk at {} due to: {e}", path.display());
                        return Err(ProgramError::ProcessingPath(e.to_string()).into());
                    }
                }
            }
        }
    } else {
        let threads = args
            .options
            .threads
            .map(|t| t.get())
            .unwrap_or_else(|| std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1));
        info!(
            "Will walk file tree using {threads} thread(s), processing in arbitrary order, starting from: {root:?}"
        );
        builder.threads(threads);
        let walker = builder.build_parallel();
        let first_error = first_error.clone();
        let abort = Arc::new(AtomicBool::new(false));
        walker.run(|| {
            let first_error = first_error.clone();
            let abort = abort.clone();
            let is_wanted = &is_wanted;
            let handle = &handle;
            Box::new(move |entry| {
                use ignore::WalkState;
                if abort.load(Ordering::SeqCst) {
                    return WalkState::Quit;
                }
                let entry = match entry {
                    Ok(e) => e,
                    Err(e) => {
                        error!("Error walking: {e}");
                        return WalkState::Continue;
                    }
                };
                let path = entry.path();
                let rel = match is_wanted(path) {
                    Some(r) => r,
                    None => return WalkState::Continue,
                };
                match handle(path, &rel) {
                    Ok(_) => WalkState::Continue,
                    Err(e) => {
                        let is_some_in_scope = matches!(e, ProgramError::Bare(ApplyError::SomeInScope));
                        if (mode.search_mode || mode.dry_run) && !is_some_in_scope {
                            error!("Error walking at {}: {e}", path.display());
                            WalkState::Continue
                        } else {
                            if !is_some_in_scope {
                                error!("Aborting walk at {} due to: {e}", path.display());
                            }
                            let mut fe = first_error.lock().unwrap();
                            if fe.is_none() {
                                *fe = Some(if is_some_in_scope {
                                    e
                                } else {
                                    ProgramError::ProcessingPath(e.to_string())
                                });
                            }
                            abort.store(true, Ordering::SeqCst);
                            WalkState::Quit
                        }
                    }
                }
            })
        });
        if let Some(e) = first_error.lock().unwrap().take() {
            return Err(e.into());
        }
    }

    let seen = n_seen.load(Ordering::SeqCst);
    let processed = n_processed.load(Ordering::SeqCst);
    info!("Saw {seen} items");
    info!("Processed {processed} files");

    if seen == 0 && args.options.fail_no_files {
        return Err(ProgramError::NoFilesFound.into());
    }
    if (mode.search_mode || mode.dry_run || pipeline.fail_none) && !any_in_scope.load(Ordering::SeqCst) {
        return Err(ProgramError::Bare(ApplyError::NoneInScope).into());
    }
    trace!("All done");
    Ok(())
}
