//! A generic syntax tree, loosely modelled after tree-sitter's.

use super::Range;

#[derive(Debug, Clone)]
pub struct Node {
    pub kind: &'static str,
    pub start: usize,
    pub end: usize,
    /// Field name under the parent, if any.
    pub field: Option<&'static str>,
    pub children: Vec<Node>,
    /// Whether this is an anonymous (literal token) node.
    pub anonymous: bool,
}

impl Node {
    pub fn new(kind: &'static str, start: usize, end: usize) -> Self {
        Self {
            kind,
            start,
            end,
            field: None,
            children: Vec::new(),
            anonymous: false,
        }
    }

    pub fn token(kind: &'static str, start: usize, end: usize) -> Self {
        Self {
            kind,
            start,
            end,
            field: None,
            children: Vec::new(),
            anonymous: true,
        }
    }

    pub fn with_field(mut self, field: &'static str) -> Self {
        self.field = Some(field);
        self
    }

    pub fn range(&self) -> Range {
        self.start..self.end
    }

    pub fn push(&mut self, child: Node) {
        if child.start < self.start {
            self.start = child.start;
        }
        if child.end > self.end {
            self.end = child.end;
        }
        self.children.push(child);
    }

    /// Recompute start/end from children (if any).
    pub fn fit(&mut self) {
        if let (Some(first), Some(last)) = (self.children.first(), self.children.last()) {
            self.start = first.start.min(self.start);
            self.end = last.end.max(self.end);
        }
    }

    pub fn child_by_field(&self, field: &str) -> Option<&Node> {
        self.children.iter().find(|c| c.field == Some(field))
    }

    pub fn children_by_field<'a>(&'a self, field: &'a str) -> impl Iterator<Item = &'a Node> + 'a {
        self.children.iter().filter(move |c| c.field == Some(field))
    }

    pub fn has_child_kind(&self, kind: &str) -> bool {
        self.children.iter().any(|c| c.kind == kind)
    }

    pub fn child_of_kind(&self, kind: &str) -> Option<&Node> {
        self.children.iter().find(|c| c.kind == kind)
    }

    pub fn text<'a>(&self, src: &'a str) -> &'a str {
        &src[self.start..self.end]
    }

    /// Depth-first pre-order traversal.
    pub fn walk<'a>(&'a self, f: &mut dyn FnMut(&'a Node, &[&'a Node])) {
        let mut stack: Vec<&'a Node> = Vec::new();
        self.walk_inner(f, &mut stack);
    }

    fn walk_inner<'a>(&'a self, f: &mut dyn FnMut(&'a Node, &[&'a Node]), ancestors: &mut Vec<&'a Node>) {
        f(self, ancestors);
        ancestors.push(self);
        for c in &self.children {
            c.walk_inner(f, ancestors);
        }
        ancestors.pop();
    }

    /// All descendants (including self) of the given kind.
    pub fn descendants_of_kind<'a>(&'a self, kind: &str) -> Vec<&'a Node> {
        let mut out = Vec::new();
        self.walk(&mut |n, _| {
            if n.kind == kind {
                out.push(n);
            }
        });
        out
    }

    /// Debug S-expression (named nodes only).
    pub fn sexp(&self) -> String {
        let mut s = String::new();
        self.sexp_inner(&mut s);
        s
    }

    fn sexp_inner(&self, out: &mut String) {
        if self.anonymous {
            return;
        }
        if let Some(f) = self.field {
            out.push_str(f);
            out.push_str(": ");
        }
        out.push('(');
        out.push_str(self.kind);
        for c in &self.children {
            if c.anonymous {
                continue;
            }
            out.push(' ');
            c.sexp_inner(out);
        }
        out.push(')');
    }
}

/// Collect ranges of all nodes of a kind.
pub fn ranges_of_kind(root: &Node, kind: &str) -> Vec<Range> {
    root.descendants_of_kind(kind)
        .into_iter()
        .map(|n| n.range())
        .collect()
}
