    pub field: Option<&'static str>,
    pub children: Vec<Node>,
    /// Whether this is an anonymous (literal token) node.
    pub anonymous: bool,
}

impl Node {
    pub fn new(kind: &'static str, start: usize, end: usize) -> Self {
        Self {
            kind,
            start,
            end,
            field: None,
            children: Vec::new(),
            anonymous: false,
        }
    }

    pub fn token(kind: &'static str, start: usize, end: usize) -> Self {
        Self {
            kind,
            start,
            end,
            field: None,
            children: Vec::new(),
            anonymous: true,
        }
    }

    pub fn with_field(mut self, field: &'static str) -> Self {
        self.field = Some(field);
        self
    }

    pub fn range(&self) -> Range {
        self.start..self.end
    }

    pub fn push(&mut self, child: Node) {
        if child.start < self.start {
            self.start = child.start;
        }
        if child.end > self.end {
            self.end = child.end;
        }
        self.children.push(child);
    }

    /// Recompute start/end from children (if any).
    pub fn fit(&mut self) {
        if let (Some(first), Some(last)) = (self.children.first(), self.children.last()) {
            self.start = first.start.min(self.start);
            self.end = last.end.max(self.end);
        }
