//! Language support: Python.

use super::tree::Node;
use super::Range;

// ---------------------------------------------------------------------------
// Tokenizer
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Name,
    Number,
    Str(StrInfo),
    Op,
    Newline,
    Indent,
    Dedent,
    Comment,
    Eof,
}

#[derive(Debug, Clone, PartialEq)]
struct StrInfo {
    /// Byte range of the opening delimiter (prefix + quotes).
    start_end: usize,
    /// Byte offset where the closing quotes start.
    content_end: usize,
    /// Quote string (`"`, `'`, `"""`, `'''`).
    quote: &'static str,
    is_f: bool,
    /// Interpolations: (brace start, brace end) absolute offsets (exclusive end).
    interpolations: Vec<(usize, usize)>,
}

#[derive(Debug, Clone)]
struct Token {
    tok: Tok,
    start: usize,
    end: usize,
}

const KEYWORDS: &[&str] = &[
    "False", "None", "True", "and", "as", "assert", "async", "await", "break", "class", "continue",
    "def", "del", "elif", "else", "except", "finally", "for", "from", "global", "if", "import",
    "in", "is", "lambda", "nonlocal", "not", "or", "pass", "raise", "return", "try", "while",
    "with", "yield",
];

fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_'
}

fn is_ident_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_'
}

struct Lexer<'a> {
    src: &'a str,
    bytes: &'a [u8],
    pos: usize,
    tokens: Vec<Token>,
    indents: Vec<usize>,
    depth: usize,
    at_line_start: bool,
}

impl<'a> Lexer<'a> {
    fn new(src: &'a str) -> Self {
        Self {
            src,
            bytes: src.as_bytes(),
            pos: 0,
            tokens: Vec::new(),
            indents: vec![0],
            depth: 0,
            at_line_start: true,
        }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<u8> {
        self.bytes.get(self.pos + off).copied()
    }

    fn push(&mut self, tok: Tok, start: usize, end: usize) {
        self.tokens.push(Token { tok, start, end });
    }

    /// Measure indentation of the line starting at `pos` (spaces=1, tabs to 8).
    fn measure_indent(&self, mut pos: usize) -> (usize, usize) {
        let mut col = 0;
        while pos < self.bytes.len() {
            match self.bytes[pos] {
                b' ' => col += 1,
                b'\t' => col = (col / 8 + 1) * 8,
                b'\x0c' => col = 0,
                _ => break,
            }
            pos += 1;
        }
        (col, pos)
    }

    fn line_is_blank_or_comment(&self, pos: usize) -> (bool, bool) {
        // returns (blank, comment)
        let (_, p) = self.measure_indent(pos);
        match self.bytes.get(p) {
            None => (true, false),
            Some(b'\n') | Some(b'\r') => (true, false),
            Some(b'#') => (false, true),
            _ => (false, false),
        }
    }

    fn skip_to_eol(&self, mut pos: usize) -> usize {
        while pos < self.bytes.len() && self.bytes[pos] != b'\n' {
            pos += 1;
        }
        pos
    }

    /// Handle the start of a logical line: emit comments on blank lines, INDENT/DEDENT.
    fn handle_line_start(&mut self) {
        // Collect comment-only / blank lines until a real line (or EOF).
        let mut comments: Vec<(usize, usize, usize)> = Vec::new(); // (indent, start, end)
        let mut pos = self.pos;
        loop {
            if pos >= self.bytes.len() {
                // EOF: emit comments, then dedents.
                for (_, s, e) in &comments {
                    self.push(Tok::Comment, *s, *e);
                }
                self.pos = pos;
                return;
            }
            let (indent, p) = self.measure_indent(pos);
            let (blank, comment) = self.line_is_blank_or_comment(pos);
            if blank {
                pos = self.skip_to_eol(p);
                if pos < self.bytes.len() {
                    pos += 1;
                }
                continue;
            }
            if comment {
                let e = self.skip_to_eol(p);
                comments.push((indent, p, e));
                pos = e;
                if pos < self.bytes.len() {
                    pos += 1;
                }
                continue;
            }
            // Real line at `p` with `indent`.
            let current = *self.indents.last().unwrap();
            if indent > current {
                for (_, s, e) in &comments {
                    self.push(Tok::Comment, *s, *e);
                }
                self.indents.push(indent);
                self.push(Tok::Indent, p, p);
            } else if indent < current {
                let first_comment_indent = comments.first().map(|c| c.0);
                let comments_inside = match first_comment_indent {
                    Some(ci) => ci >= current,
                    None => false,
                };
                if comments_inside {
                    for (_, s, e) in &comments {
                        self.push(Tok::Comment, *s, *e);
                    }
                }
                while self.indents.len() > 1 && indent < *self.indents.last().unwrap() {
                    self.indents.pop();
                    self.push(Tok::Dedent, p, p);
                }
                if !comments_inside {
                    for (_, s, e) in &comments {
                        self.push(Tok::Comment, *s, *e);
                    }
                }
            } else {
                for (_, s, e) in &comments {
                    self.push(Tok::Comment, *s, *e);
                }
            }
            self.pos = p;
            return;
        }
    }

    fn lex(mut self) -> Vec<Token> {
        loop {
            if self.at_line_start && self.depth == 0 {
                self.at_line_start = false;
                self.handle_line_start();
                if self.pos >= self.bytes.len() {
                    break;
                }
            }
            let c = match self.peek() {
                Some(c) => c,
                None => break,
            };
            match c {
                b'\n' => {
                    if self.depth == 0 {
                        self.push(Tok::Newline, self.pos, self.pos + 1);
                        self.at_line_start = true;
                    }
                    self.pos += 1;
                }
                b' ' | b'\t' | b'\r' | b'\x0c' => {
                    self.pos += 1;
                }
                b'\\' => {
                    // Line continuation.
                    if self.peek_at(1) == Some(b'\n') {
                        self.pos += 2;
                    } else if self.peek_at(1) == Some(b'\r') && self.peek_at(2) == Some(b'\n') {
                        self.pos += 3;
                    } else {
                        self.push(Tok::Op, self.pos, self.pos + 1);
                        self.pos += 1;
                    }
                }
                b'#' => {
                    let start = self.pos;
                    let end = self.skip_to_eol(self.pos);
                    self.push(Tok::Comment, start, end);
                    self.pos = end;
                }
                b'"' | b'\'' => {
                    self.lex_string(self.pos, self.pos);
                }
                b'0'..=b'9' => {
                    let start = self.pos;
                    self.pos += 1;
                    while let Some(c) = self.peek() {
                        if c.is_ascii_alphanumeric() || c == b'_' || c == b'.' {
                            self.pos += 1;
                        } else if (c == b'+' || c == b'-')
                            && matches!(self.bytes.get(self.pos - 1), Some(b'e') | Some(b'E'))
                        {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    self.push(Tok::Number, start, self.pos);
                }
                b'.' if matches!(self.peek_at(1), Some(b'0'..=b'9')) => {
                    let start = self.pos;
                    self.pos += 1;
                    while let Some(c) = self.peek() {
                        if c.is_ascii_alphanumeric() || c == b'_' {
                            self.pos += 1;
                        } else {
                            break;
                        }
                    }
                    self.push(Tok::Number, start, self.pos);
                }
                _ if c < 0x80 && (c.is_ascii_alphabetic() || c == b'_') || c >= 0x80 => {
                    let start = self.pos;
                    let rest = &self.src[self.pos..];
                    let ch = rest.chars().next().unwrap();
                    if !is_ident_start(ch) {
                        // Unknown non-ASCII char: skip.
                        self.pos += ch.len_utf8();
                        continue;
                    }
                    let mut end = self.pos;
                    for ch in rest.chars() {
                        if is_ident_char(ch) {
                            end += ch.len_utf8();
                        } else {
                            break;
                        }
                    }
                    // String prefix?
                    let word = &self.src[start..end];
                    let lower = word.to_ascii_lowercase();
                    if matches!(
                        lower.as_str(),
                        "r" | "b" | "f" | "u" | "rb" | "br" | "fr" | "rf" | "t" | "rt" | "tr"
                    ) && matches!(self.bytes.get(end), Some(b'"') | Some(b'\''))
                    {
                        self.lex_string(start, end);
                        continue;
                    }
                    self.pos = end;
                    self.push(Tok::Name, start, end);
                }
                b'(' | b'[' | b'{' => {
                    self.depth += 1;
                    self.push(Tok::Op, self.pos, self.pos + 1);
                    self.pos += 1;
                }
                b')' | b']' | b'}' => {
                    self.depth = self.depth.saturating_sub(1);
                    self.push(Tok::Op, self.pos, self.pos + 1);
                    self.pos += 1;
                }
                _ => {
                    // Operators: longest match of known multi-char operators.
                    let start = self.pos;
                    let rest = &self.bytes[self.pos..];
                    let ops3: [&[u8]; 5] = [b"**=", b"//=", b">>=", b"<<=", b"..."];
                    let ops2: [&[u8]; 17] = [
                        b"**", b"//", b">>", b"<<", b"<=", b">=", b"==", b"!=", b"->", b"+=",
                        b"-=", b"*=", b"/=", b"%=", b"&=", b"|=", b"^=",
                    ];
                    let mut len = 1;
                    for op in ops3.iter() {
                        if rest.starts_with(op) {
                            len = 3;
                            break;
                        }
                    }
                    if len == 1 {
                        for op in ops2.iter() {
                            if rest.starts_with(op) {
                                len = 2;
                                break;
                            }
                        }
                    }
                    if len == 1 && rest.starts_with(b":=") {
                        len = 2;
                    }
                    if len == 1 && rest.starts_with(b"@=") {
                        len = 2;
                    }
                    self.push(Tok::Op, start, start + len);
                    self.pos = start + len;
                }
            }
        }
        // Final newline / dedents.
        let end = self.bytes.len();
        if let Some(last) = self.tokens.last() {
            if last.tok != Tok::Newline && last.tok != Tok::Dedent {
                self.push(Tok::Newline, end, end);
            }
        }
        while self.indents.len() > 1 {
            self.indents.pop();
            self.push(Tok::Dedent, end, end);
        }
        self.push(Tok::Eof, end, end);
        self.tokens
    }

    /// Lex a string starting at `start` (prefix start), quotes beginning at `quote_pos`.
    fn lex_string(&mut self, start: usize, quote_pos: usize) {
        let prefix = self.src[start..quote_pos].to_ascii_lowercase();
        let is_raw = prefix.contains('r');
        let is_f = prefix.contains('f') || prefix.contains('t');
        let q = self.bytes[quote_pos];
        let triple = self.bytes.get(quote_pos + 1) == Some(&q) && self.bytes.get(quote_pos + 2) == Some(&q);
        let quote: &'static str = match (q, triple) {
            (b'"', true) => "\"\"\"",
            (b'\'', true) => "'''",
            (b'"', false) => "\"",
            _ => "'",
        };
        let qlen = quote.len();
        let mut pos = quote_pos + qlen;
        let content_start = pos;
        let mut interpolations = Vec::new();
        let mut content_end;
        loop {
            if pos >= self.bytes.len() {
                content_end = pos;
                break;
            }
            let c = self.bytes[pos];
            if c == b'\\' && !is_raw {
                pos += 2;
                continue;
            }
            if c == b'\\' && is_raw {
                // In raw strings a backslash still escapes the quote char lexically.
                pos += 2;
                continue;
            }
            if !triple && c == b'\n' {
                // Unterminated single-line string.
                content_end = pos;
                self.push(
                    Tok::Str(StrInfo {
                        start_end: content_start,
                        content_end,
                        quote,
                        is_f,
                        interpolations,
                    }),
                    start,
                    pos,
                );
                self.pos = pos;
                return;
            }
            if c == q && (!triple || (self.bytes.get(pos + 1) == Some(&q) && self.bytes.get(pos + 2) == Some(&q))) {
                content_end = pos;
                pos += qlen;
                break;
            }
            if is_f && c == b'{' {
                if self.bytes.get(pos + 1) == Some(&b'{') {
                    pos += 2;
                    continue;
                }
                // Interpolation: find matching close brace, skipping nested strings.
                let istart = pos;
                let mut depth = 0usize;
                let mut p = pos;
                while p < self.bytes.len() {
                    let ch = self.bytes[p];
                    match ch {
                        b'{' | b'(' | b'[' => depth += 1,
                        b'}' | b')' | b']' => {
                            depth -= 1;
                            if depth == 0 {
                                break;
                            }
                        }
                        b'"' | b'\'' => {
                            // skip nested string
                            let nq = ch;
                            p += 1;
                            while p < self.bytes.len() && self.bytes[p] != nq && self.bytes[p] != b'\n' {
                                if self.bytes[p] == b'\\' {
                                    p += 1;
                                }
                                p += 1;
                            }
                        }
                        b'\n' if !triple => break,
                        _ => {}
                    }
                    p += 1;
                }
                let iend = (p + 1).min(self.bytes.len());
                interpolations.push((istart, iend));
                pos = iend;
                continue;
            }
            if is_f && c == b'}' && self.bytes.get(pos + 1) == Some(&b'}') {
                pos += 2;
                continue;
            }
            pos += 1;
        }
        let _ = content_start;
        self.push(
            Tok::Str(StrInfo {
                start_end: content_start,
                content_end,
                quote,
                is_f,
                interpolations,
            }),
            start,
            pos.min(self.bytes.len()),
        );
        self.pos = pos.min(self.bytes.len());
    }
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

struct Parser<'a> {
    src: &'a str,
    toks: Vec<Token>,
    i: usize,
}

const COMPOUND_KEYWORDS: &[&str] = &[
    "def", "class", "if", "elif", "else", "for", "while", "with", "try", "except", "finally",
    "async", "match", "case",
];

impl<'a> Parser<'a> {
    fn peek(&self) -> &Token {
        &self.toks[self.i.min(self.toks.len() - 1)]
    }

    fn peek_n(&self, n: usize) -> &Token {
        &self.toks[(self.i + n).min(self.toks.len() - 1)]
    }

    fn text(&self, t: &Token) -> &'a str {
        &self.src[t.start..t.end]
    }

    fn at_eof(&self) -> bool {
        self.peek().tok == Tok::Eof
    }

    fn is_op(&self, s: &str) -> bool {
        let t = self.peek();
        t.tok == Tok::Op && self.text(t) == s
    }

    fn is_name(&self, s: &str) -> bool {
        let t = self.peek();
        t.tok == Tok::Name && self.text(t) == s
    }

    fn advance(&mut self) -> Token {
        let t = self.peek().clone();
        if self.i < self.toks.len() - 1 {
            self.i += 1;
        }
        t
    }

    /// Consume comment tokens, pushing them to `parent`.
    fn eat_comments(&mut self, parent: &mut Node) {
        while self.peek().tok == Tok::Comment {
            let t = self.advance();
            parent.push(Node::new("comment", t.start, t.end));
        }
    }

    fn parse_module(&mut self) -> Node {
        let mut module = Node::new("module", 0, self.src.len());
        self.parse_statements(&mut module, false);
        module
    }

    /// Parse statements until Dedent/Eof (`in_block`: stop at Dedent).
    fn parse_statements(&mut self, parent: &mut Node, in_block: bool) {
        loop {
            match self.peek().tok {
                Tok::Eof => break,
                Tok::Dedent => {
                    if in_block {
                        break;
                    }
                    self.advance();
                }
                Tok::Comment => {
                    let t = self.advance();
                    parent.push(Node::new("comment", t.start, t.end));
                }
                Tok::Newline => {
                    self.advance();
                }
                Tok::Indent => {
                    // Unexpected indent: parse as nested block of statements.
                    self.advance();
                    self.parse_statements(parent, true);
                    if self.peek().tok == Tok::Dedent {
                        self.advance();
                    }
                }
                _ => {
                    if let Some(stmt) = self.parse_statement() {
                        parent.push(stmt);
                    }
                }
            }
        }
    }

    fn parse_statement(&mut self) -> Option<Node> {
        let t = self.peek().clone();
        if t.tok == Tok::Name {
            let word = self.text(&t);
            match word {
                "def" => return Some(self.parse_function(t.start, false)),
                "async" => {
                    let next = self.peek_n(1).clone();
                    let nw = self.text(&next);
                    if next.tok == Tok::Name && nw == "def" {
                        self.advance();
                        return Some(self.parse_function(t.start, true));
                    }
                    if next.tok == Tok::Name && (nw == "for" || nw == "with") {
                        self.advance();
                        let kind = if nw == "for" { "for_statement" } else { "with_statement" };
                        return Some(self.parse_compound(kind, t.start));
                    }
                }
                "class" => return Some(self.parse_class(t.start)),
                "if" => return Some(self.parse_if(t.start)),
                "for" => return Some(self.parse_compound("for_statement", t.start)),
                "while" => return Some(self.parse_compound("while_statement", t.start)),
                "with" => return Some(self.parse_compound("with_statement", t.start)),
                "try" => return Some(self.parse_try(t.start)),
                "match" => {
                    // Soft keyword: `match x:` followed by newline+indent.
                    if self.looks_like_match() {
                        return Some(self.parse_compound("match_statement", t.start));
                    }
                }
                _ => {}
            }
        }
        if t.tok == Tok::Op && self.text(&t) == "@" {
            return Some(self.parse_decorated(t.start));
        }
        self.parse_simple_statements()
    }

    fn looks_like_match(&self) -> bool {
        // Scan to end of line: must end with ':' and the next token must be Newline then Indent.
        let mut j = self.i + 1;
        let mut depth = 0i32;
        let mut saw_colon_last = false;
        while j < self.toks.len() {
            let t = &self.toks[j];
            match t.tok {
                Tok::Newline | Tok::Eof => break,
                Tok::Op => {
                    let s = self.text(t);
                    match s {
                        "(" | "[" | "{" => depth += 1,
                        ")" | "]" | "}" => depth -= 1,
                        _ => {}
                    }
                    saw_colon_last = s == ":" && depth == 0;
                }
                _ => saw_colon_last = false,
            }
            j += 1;
        }
        if !saw_colon_last || j + 1 >= self.toks.len() {
            return false;
        }
        // The token right after ':' must be the newline (no inline body for match).
        self.toks[j].tok == Tok::Newline && self.toks[j + 1].tok == Tok::Indent && self.i + 1 < j
    }

    /// Parse `: body` where body is an inline simple statement list or an indented block.
    /// Returns the block node.
    fn parse_block(&mut self) -> Node {
        // Expect ':' (skip tokens until ':' at depth 0 or newline).
        let mut block = Node::new("block", self.peek().start, self.peek().start);
        if self.is_op(":") {
            self.advance();
        }
        if self.peek().tok == Tok::Newline {
            self.advance();
            // Comments between newline and indent belong... attach to block if indent follows.
            let mut pending = Vec::new();
            while self.peek().tok == Tok::Comment {
                let t = self.advance();
                pending.push(Node::new("comment", t.start, t.end));
            }
            if self.peek().tok == Tok::Indent {
                self.advance();
                block.start = self.peek().start;
                block.end = block.start;
                for c in pending {
                    block.push(c);
                }
                self.parse_statements(&mut block, true);
                if self.peek().tok == Tok::Dedent {
                    self.advance();
                }
            } else {
                // No indented block (error recovery).
                for c in pending {
                    block.push(c);
                }
            }
        } else {
            // Inline body.
            if let Some(stmt) = self.parse_simple_statements() {
                block.start = stmt.start;
                block.end = stmt.end;
                block.push(stmt);
            }
        }
        block.field = Some("body");
        block
    }

    fn parse_function(&mut self, start: usize, is_async: bool) -> Node {
        let mut node = Node::new("function_definition", start, start);
        if is_async {
            node.push(Node::token("async", start, start + 5));
        }
        let def = self.advance(); // def
        node.push(Node::token("def", def.start, def.end));
        if self.peek().tok == Tok::Name {
            let n = self.advance();
            node.push(Node::new("identifier", n.start, n.end).with_field("name"));
        }
        if self.is_op("(") {
            let params = self.parse_parameters();
            node.push(params.with_field("parameters"));
        }
        if self.is_op("->") {
            self.advance();
            let ty = self.parse_type_until(&[":"]);
            node.push(ty.with_field("return_type"));
        }
        let body = self.parse_block();
        node.push(body);
        node
    }

    fn parse_class(&mut self, start: usize) -> Node {
        let mut node = Node::new("class_definition", start, start);
        let kw = self.advance();
        node.push(Node::token("class", kw.start, kw.end));
        if self.peek().tok == Tok::Name {
            let n = self.advance();
            node.push(Node::new("identifier", n.start, n.end).with_field("name"));
        }
        if self.is_op("(") {
            let mut args = Node::new("argument_list", self.peek().start, self.peek().start);
            self.parse_bracketed(&mut args);
            node.push(args.with_field("superclasses"));
        }
        let body = self.parse_block();
        node.push(body);
        node
    }

    fn parse_decorated(&mut self, start: usize) -> Node {
        let mut node = Node::new("decorated_definition", start, start);
        while self.is_op("@") {
            let at = self.advance();
            let mut dec = Node::new("decorator", at.start, at.end);
            let expr = self.parse_expression(&["\n"]);
            for c in expr {
                dec.push(c);
            }
            // consume newline
            while self.peek().tok == Tok::Newline || self.peek().tok == Tok::Comment {
                if self.peek().tok == Tok::Comment {
                    let t = self.advance();
                    node.push(dec);
                    dec = Node::new("comment", t.start, t.end);
                    node.push(dec);
                    dec = Node::new("decorator", t.end, t.end);
                    // The decorator node was pushed; create a dummy to avoid double push.
                    // (This path is rare.)
                    continue;
                }
                self.advance();
            }
            if dec.kind == "decorator" && dec.end > dec.start {
                node.push(dec);
            }
        }
        let t = self.peek().clone();
        if t.tok == Tok::Name {
            match self.text(&t) {
                "def" => {
                    let f = self.parse_function(t.start, false);
                    node.push(f.with_field("definition"));
                }
                "async" => {
                    self.advance();
                    let f = self.parse_function(t.start, true);
                    node.push(f.with_field("definition"));
                }
                "class" => {
                    let c = self.parse_class(t.start);
                    node.push(c.with_field("definition"));
                }
                _ => {}
            }
        }
        node
    }

    fn parse_if(&mut self, start: usize) -> Node {
        let mut node = Node::new("if_statement", start, start);
        let kw = self.advance();
        node.push(Node::token("if", kw.start, kw.end));
        let cond = self.parse_expression(&[":"]);
        for c in cond {
            node.push(c);
        }
        let body = self.parse_block();
        node.push(body);
        loop {
            // Comments may precede elif/else at the same indentation.
            let save = self.i;
            let mut comments = Vec::new();
            while self.peek().tok == Tok::Comment || self.peek().tok == Tok::Newline {
                let t = self.advance();
                if t.tok == Tok::Comment {
                    comments.push(Node::new("comment", t.start, t.end));
                }
            }
            if self.is_name("elif") {
                for c in comments {
                    node.push(c);
                }
                let kw = self.advance();
                let mut clause = Node::new("elif_clause", kw.start, kw.end);
                let cond = self.parse_expression(&[":"]);
                for c in cond {
                    clause.push(c);
                }
                let body = self.parse_block();
                clause.push(body);
                node.push(clause);
            } else if self.is_name("else") {
                for c in comments {
                    node.push(c);
                }
                let kw = self.advance();
                let mut clause = Node::new("else_clause", kw.start, kw.end);
                let body = self.parse_block();
                clause.push(body);
                node.push(clause);
                break;
            } else {
                self.i = save;
                break;
            }
        }
        node
    }

    fn parse_try(&mut self, start: usize) -> Node {
        let mut node = Node::new("try_statement", start, start);
        let kw = self.advance();
        node.push(Node::token("try", kw.start, kw.end));
        let body = self.parse_block();
        node.push(body);
        loop {
            let save = self.i;
            let mut comments = Vec::new();
            while self.peek().tok == Tok::Comment || self.peek().tok == Tok::Newline {
                let t = self.advance();
                if t.tok == Tok::Comment {
                    comments.push(Node::new("comment", t.start, t.end));
                }
            }
            let (kind, is_clause) = if self.is_name("except") {
                ("except_clause", true)
            } else if self.is_name("else") {
                ("else_clause", true)
            } else if self.is_name("finally") {
                ("finally_clause", true)
            } else {
                ("", false)
            };
            if !is_clause {
                self.i = save;
                break;
            }
            for c in comments {
                node.push(c);
            }
            let kw = self.advance();
            let mut clause = Node::new(kind, kw.start, kw.end);
            if kind == "except_clause" {
                let expr = self.parse_expression(&[":"]);
                for c in expr {
                    clause.push(c);
                }
            }
            let body = self.parse_block();
            clause.push(body);
            node.push(clause);
        }
        node
    }

    /// Generic compound statement: keyword, header expression(s), block, optional else.
    fn parse_compound(&mut self, kind: &'static str, start: usize) -> Node {
        let mut node = Node::new(kind, start, start);
        let kw = self.advance();
        node.push(Node::token("kw", kw.start, kw.end));
        let header = self.parse_expression(&[":"]);
        for c in header {
            node.push(c);
        }
        let body = self.parse_block();
        node.push(body);
        if kind == "for_statement" || kind == "while_statement" {
            let save = self.i;
            let mut comments = Vec::new();
            while self.peek().tok == Tok::Comment || self.peek().tok == Tok::Newline {
                let t = self.advance();
                if t.tok == Tok::Comment {
                    comments.push(Node::new("comment", t.start, t.end));
                }
            }
            if self.is_name("else") {
                for c in comments {
                    node.push(c);
                }
                let kw = self.advance();
                let mut clause = Node::new("else_clause", kw.start, kw.end);
                let body = self.parse_block();
                clause.push(body);
                node.push(clause);
            } else {
                self.i = save;
            }
        }
        node
    }

    /// Parse a parameter list `( ... )`.
    fn parse_parameters(&mut self) -> Node {
        let open = self.advance(); // (
        let mut params = Node::new("parameters", open.start, open.end);
        loop {
            while self.peek().tok == Tok::Comment || self.peek().tok == Tok::Newline {
                self.advance();
            }
            if self.is_op(")") {
                let t = self.advance();
                params.end = t.end;
                break;
            }
            if self.at_eof() || self.peek().tok == Tok::Dedent {
                break;
            }
            // One parameter: [*|**] name [: type] [= default]
            let pstart = self.peek().start;
            let mut param = Node::new("identifier", pstart, pstart);
            let mut kind = "identifier";
            if self.is_op("*") || self.is_op("**") || self.is_op("/") {
                let t = self.advance();
                if self.text(&t) == "*" && (self.is_op(",") || self.is_op(")")) {
                    param = Node::new("list_splat_pattern", t.start, t.end);
                    params.push(param);
                    if self.is_op(",") {
                        self.advance();
                    }
                    continue;
                }
                if self.text(&t) == "/" {
                    params.push(Node::token("/", t.start, t.end));
                    if self.is_op(",") {
                        self.advance();
                    }
                    continue;
                }
                kind = if self.text(&t) == "*" {
                    "list_splat_pattern"
                } else {
                    "dictionary_splat_pattern"
                };
                param = Node::new(kind, t.start, t.end);
            }
            let mut name: Option<Node> = None;
            if self.peek().tok == Tok::Name {
                let n = self.advance();
                name = Some(Node::new("identifier", n.start, n.end));
            }
            let mut ty: Option<Node> = None;
            if self.is_op(":") {
                self.advance();
                ty = Some(self.parse_type_until(&["=", ",", ")"]));
            }
            let mut default: Vec<Node> = Vec::new();
            if self.is_op("=") {
                self.advance();
                default = self.parse_expression(&[",", ")"]);
            }
            let node = if kind != "identifier" {
                if let Some(n) = name {
                    param.push(n);
                }
                param
            } else {
                match (name, ty, default.is_empty()) {
                    (Some(n), None, true) => n,
                    (Some(n), Some(t), true) => {
                        let mut p = Node::new("typed_parameter", n.start, t.end);
                        p.push(n);
                        p.push(t.with_field("type"));
                        p
                    }
                    (Some(n), None, false) => {
                        let mut p = Node::new("default_parameter", n.start, n.end);
                        p.push(n.with_field("name"));
                        for d in default {
                            p.push(d.with_field("value"));
                        }
                        p
                    }
                    (Some(n), Some(t), false) => {
                        let mut p = Node::new("typed_default_parameter", n.start, n.end);
                        p.push(n.with_field("name"));
                        p.push(t.with_field("type"));
                        for d in default {
                            p.push(d.with_field("value"));
                        }
                        p
                    }
                    (None, _, _) => {
                        // Error recovery: skip a token.
                        if !self.is_op(",") && !self.is_op(")") {
                            self.advance();
                        }
                        if self.is_op(",") {
                            self.advance();
                        }
                        continue;
                    }
                }
            };
            params.push(node);
            if self.is_op(",") {
                self.advance();
            }
        }
        params
    }

    /// Parse a type annotation expression, wrapped in a `type` node.
    fn parse_type_until(&mut self, terminators: &[&str]) -> Node {
        let start = self.peek().start;
        let exprs = self.parse_expression(terminators);
        let mut ty = Node::new("type", start, start);
        for e in exprs {
            ty.push(e);
        }
        if ty.children.is_empty() {
            ty.end = self.peek().start.max(start);
        }
        ty
    }

    /// Parse simple statement(s) on one logical line (separated by `;`).
    fn parse_simple_statements(&mut self) -> Option<Node> {
        let mut stmts: Vec<Node> = Vec::new();
        loop {
            if matches!(self.peek().tok, Tok::Newline | Tok::Eof | Tok::Dedent | Tok::Indent) {
                break;
            }
            if self.peek().tok == Tok::Comment {
                break;
            }
            if let Some(s) = self.parse_simple_statement() {
                stmts.push(s);
            }
            if self.is_op(";") {
                self.advance();
                continue;
            }
            break;
        }
        // Consume the newline (comments at end of line are pushed as siblings via wrapper).
        if stmts.is_empty() {
            // Skip garbage token to make progress.
            if !matches!(self.peek().tok, Tok::Newline | Tok::Eof | Tok::Dedent | Tok::Indent | Tok::Comment) {
                self.advance();
            }
            return None;
        }
        if stmts.len() == 1 {
            return stmts.pop();
        }
        // Multiple statements: return a wrapper; callers push children individually via flattening.
        let mut wrapper = Node::new("_statements", stmts[0].start, stmts[stmts.len() - 1].end);
        for s in stmts {
            wrapper.push(s);
        }
        Some(wrapper)
    }

    fn parse_simple_statement(&mut self) -> Option<Node> {
        let t = self.peek().clone();
        let start = t.start;
        if t.tok == Tok::Name {
            let word = self.text(&t);
            match word {
                "import" => return Some(self.parse_import(start)),
                "from" => return Some(self.parse_from_import(start)),
                "return" | "raise" | "del" | "assert" | "yield" | "await" => {
                    let kind: &'static str = match word {
                        "return" => "return_statement",
                        "raise" => "raise_statement",
                        "del" => "delete_statement",
                        "assert" => "assert_statement",
                        _ => "expression_statement",
                    };
                    let kw = self.advance();
                    let mut node = Node::new(kind, kw.start, kw.end);
                    let exprs = self.parse_expression(&[";"]);
                    for e in exprs {
                        node.push(e);
                    }
                    return Some(node);
                }
                "pass" | "break" | "continue" => {
                    let kw = self.advance();
                    let kind: &'static str = match word {
                        "pass" => "pass_statement",
                        "break" => "break_statement",
                        _ => "continue_statement",
                    };
                    return Some(Node::new(kind, kw.start, kw.end));
                }
                "global" | "nonlocal" => {
                    let kw = self.advance();
                    let kind: &'static str = if word == "global" {
                        "global_statement"
                    } else {
                        "nonlocal_statement"
                    };
                    let mut node = Node::new(kind, kw.start, kw.end);
                    while self.peek().tok == Tok::Name {
                        let n = self.advance();
                        node.push(Node::new("identifier", n.start, n.end));
                        if self.is_op(",") {
                            self.advance();
                        } else {
                            break;
                        }
                    }
                    return Some(node);
                }
                _ => {}
            }
        }
        // Expression statement (possibly assignment).
        let exprs = self.parse_expression(&[";"]);
        if exprs.is_empty() {
            return None;
        }
        let mut node = Node::new("expression_statement", start, start);
        for e in exprs {
            node.push(e);
        }
        Some(node)
    }

    fn parse_import(&mut self, start: usize) -> Node {
        let kw = self.advance();
        let mut node = Node::new("import_statement", start, kw.end);
        loop {
            if self.peek().tok != Tok::Name {
                break;
            }
            let dn = self.parse_dotted_name();
            if self.is_name("as") {
                self.advance();
                let mut aliased = Node::new("aliased_import", dn.start, dn.end);
                aliased.push(dn.with_field("name"));
                if self.peek().tok == Tok::Name {
                    let a = self.advance();
                    aliased.push(Node::new("identifier", a.start, a.end).with_field("alias"));
                }
                node.push(aliased.with_field("name"));
            } else {
                node.push(dn.with_field("name"));
            }
            if self.is_op(",") {
                self.advance();
            } else {
                break;
            }
        }
        node
    }

    fn parse_dotted_name(&mut self) -> Node {
        let first = self.advance();
        let mut dn = Node::new("dotted_name", first.start, first.end);
        dn.push(Node::new("identifier", first.start, first.end));
        while self.is_op(".") && self.peek_n(1).tok == Tok::Name {
            self.advance();
            let n = self.advance();
            dn.push(Node::new("identifier", n.start, n.end));
        }
        dn
    }

    fn parse_from_import(&mut self, start: usize) -> Node {
        let kw = self.advance();
        let mut node = Node::new("import_from_statement", start, kw.end);
        // Module name: relative import (dots) and/or dotted name.
        let mstart = self.peek().start;
        let mut dots_end = mstart;
        let mut has_dots = false;
        while self.is_op(".") || self.is_op("...") {
            let t = self.advance();
            dots_end = t.end;
            has_dots = true;
        }
        let dotted = if self.peek().tok == Tok::Name && !self.is_name("import") {
            Some(self.parse_dotted_name())
        } else {
            None
        };
        if has_dots {
            let mut rel = Node::new("relative_import", mstart, dots_end);
            rel.push(Node::new("import_prefix", mstart, dots_end));
            if let Some(d) = dotted {
                rel.push(d);
            }
            node.push(rel.with_field("module_name"));
        } else if let Some(d) = dotted {
            node.push(d.with_field("module_name"));
        }
        if self.is_name("import") {
            let t = self.advance();
            node.end = node.end.max(t.end);
        }
        let paren = self.is_op("(");
        if paren {
            self.advance();
        }
        loop {
            while self.peek().tok == Tok::Comment || (paren && self.peek().tok == Tok::Newline) {
                self.advance();
            }
            if self.is_op("*") {
                let t = self.advance();
                node.push(Node::new("wildcard_import", t.start, t.end));
                break;
            }
            if self.peek().tok != Tok::Name {
                break;
            }
            let dn = self.parse_dotted_name();
            if self.is_name("as") {
                self.advance();
                let mut aliased = Node::new("aliased_import", dn.start, dn.end);
                aliased.push(dn.with_field("name"));
                if self.peek().tok == Tok::Name {
                    let a = self.advance();
                    aliased.push(Node::new("identifier", a.start, a.end).with_field("alias"));
                }
                node.push(aliased.with_field("name"));
            } else {
                node.push(dn.with_field("name"));
            }
            if self.is_op(",") {
                self.advance();
            } else {
                break;
            }
        }
        if paren && self.is_op(")") {
            let t = self.advance();
            node.end = node.end.max(t.end);
        }
        node
    }

    /// Parse a bracketed group starting at the current `(`/`[`/`{` token; pushes the
    /// contents (as expression nodes) into `parent` and sets parent's end.
    fn parse_bracketed(&mut self, parent: &mut Node) {
        let open = self.advance();
        let close = match self.text(&open) {
            "(" => ")",
            "[" => "]",
            _ => "}",
        };
        parent.start = parent.start.min(open.start);
        parent.end = open.end;
        loop {
            while self.peek().tok == Tok::Comment || self.peek().tok == Tok::Newline {
                self.advance();
            }
            if self.is_op(close) {
                let t = self.advance();
                parent.end = t.end;
                break;
            }
            if self.at_eof() || self.peek().tok == Tok::Dedent {
                break;
            }
            let before = self.i;
            let exprs = self.parse_expression(&[",", close]);
            for e in exprs {
                parent.push(e);
            }
            if self.is_op(",") {
                let t = self.advance();
                parent.end = t.end;
            } else if self.i == before {
                // No progress: skip a token.
                let t = self.advance();
                parent.end = t.end;
            }
        }
    }

    /// Parse an expression (or assignment chain) until one of the terminators (at depth 0)
    /// or end of logical line. Returns the top-level nodes.
    fn parse_expression(&mut self, terminators: &[&str]) -> Vec<Node> {
        // Parse a flat sequence of primary items, then restructure assignments.
        let mut items: Vec<Node> = Vec::new();
        let start = self.peek().start;
        let mut end = start;
        // Track assignment operators at this level.
        let mut assign_positions: Vec<(usize, &'static str, usize, usize)> = Vec::new(); // (index in items, kind, op start, op end)
        loop {
            let t = self.peek().clone();
            match t.tok {
                Tok::Newline | Tok::Eof | Tok::Dedent | Tok::Indent => break,
                Tok::Comment => break,
                _ => {}
            }
            if t.tok == Tok::Op {
                let s = self.text(&t);
                if terminators.contains(&s) || s == ")" || s == "]" || s == "}" || s == ";" {
                    break;
                }
                if terminators.contains(&"\n") && s == "\n" {
                    break;
                }
                match s {
                    "(" | "[" | "{" => {
                        // Grouping / list / dict / call handled in primary.
                        let kind: &'static str = match s {
                            "(" => "parenthesized_expression",
                            "[" => "list",
                            _ => "dictionary",
                        };
                        let mut g = Node::new(kind, t.start, t.end);
                        self.parse_bracketed(&mut g);
                        end = g.end;
                        items.push(g);
                        continue;
                    }
                    "=" => {
                        assign_positions.push((items.len(), "assignment", t.start, t.end));
                        self.advance();
                        items.push(Node::token("=", t.start, t.end));
                        end = t.end;
                        continue;
                    }
                    ":" => {
                        // Annotation (only if ':' is not a terminator): `x: int = 1`.
                        if terminators.contains(&":") {
                            break;
                        }
                        assign_positions.push((items.len(), "annotation", t.start, t.end));
                        self.advance();
                        items.push(Node::token(":", t.start, t.end));
                        end = t.end;
                        continue;
                    }
                    "+=" | "-=" | "*=" | "/=" | "//=" | "%=" | "**=" | ">>=" | "<<=" | "&="
                    | "|=" | "^=" | "@=" => {
                        assign_positions.push((items.len(), "augmented_assignment", t.start, t.end));
                        self.advance();
                        items.push(Node::token("op=", t.start, t.end));
                        end = t.end;
                        continue;
                    }
                    _ => {
                        self.advance();
                        items.push(Node::token("op", t.start, t.end));
                        end = t.end;
                        continue;
                    }
                }
            }
            if t.tok == Tok::Name {
                let w = self.text(&t);
                if w == "lambda" {
                    let lam = self.parse_lambda(terminators);
                    end = lam.end;
                    items.push(lam);
                    continue;
                }
                if (w == "for" || w == "if" || w == "else" || w == "async")
                    && terminators.contains(&",")
                    && !terminators.contains(&":")
                {
                    // Comprehension clauses inside brackets: keep going as plain tokens.
                    // (We still want identifiers inside.)
                }
                if KEYWORDS.contains(&w) || (w == "match" && false) {
                    self.advance();
                    items.push(Node::token("keyword", t.start, t.end));
                    end = t.end;
                    continue;
                }
                // Identifier, possibly followed by attribute access / call / subscript.
                let prim = self.parse_primary();
                end = prim.end;
                items.push(prim);
                continue;
            }
            if let Tok::Str(_) = t.tok {
                let s = self.parse_string_token();
                end = s.end;
                items.push(s);
                continue;
            }
            if t.tok == Tok::Number {
                self.advance();
                items.push(Node::new("integer", t.start, t.end));
                end = t.end;
                continue;
            }
            // Unknown: skip.
            self.advance();
        }
        let _ = end;
        // Restructure assignments: split items at '=' (right-assoc) and at ':' annotation.
        self.build_assignments(items, assign_positions)
    }

    fn build_assignments(
        &self,
        items: Vec<Node>,
        assigns: Vec<(usize, &'static str, usize, usize)>,
    ) -> Vec<Node> {
        if assigns.is_empty() {
            return items;
        }
        // Group items into segments separated by assignment/annotation tokens.
        let mut segments: Vec<Vec<Node>> = vec![Vec::new()];
        let mut ops: Vec<&'static str> = Vec::new();
        for item in items {
            if item.anonymous && (item.kind == "=" || item.kind == ":" || item.kind == "op=") {
                ops.push(if item.kind == "=" {
                    "assignment"
                } else if item.kind == ":" {
                    "annotation"
                } else {
                    "augmented_assignment"
                });
                segments.push(Vec::new());
            } else {
                segments.last_mut().unwrap().push(item);
            }
        }
        // Build right-to-left.
        let seg_to_node = |seg: Vec<Node>| -> Option<Node> {
            if seg.is_empty() {
                return None;
            }
            if seg.len() == 1 {
                return seg.into_iter().next();
            }
            let mut n = Node::new("expression", seg[0].start, seg[seg.len() - 1].end);
            // Comma-separated at top level → pattern_list / expression_list
            let has_comma = seg.iter().any(|x| x.anonymous && x.kind == "op");
            if has_comma {
                n.kind = "expression_list";
            }
            for s in seg {
                n.push(s);
            }
            Some(n)
        };
        let mut segs: Vec<Option<Node>> = segments.into_iter().map(seg_to_node).collect();
        // Handle annotation: `left : type [= value]`.
        let mut i = 0;
        let mut result: Option<Node> = None;
        // Process from right to left.
        let n = ops.len();
        let mut right: Option<Node> = segs.pop().flatten();
        let mut idx = n;
        while idx > 0 {
            idx -= 1;
            let op = ops[idx];
            let left = segs.pop().flatten();
            let mut node = Node::new(
                if op == "augmented_assignment" {
                    "augmented_assignment"
                } else {
                    "assignment"
                },
                0,
                0,
            );
            let mut set = false;
            if let Some(l) = left {
                node.start = l.start;
                node.end = l.end;
                set = true;
                node.push(l.with_field("left"));
            }
            if op == "annotation" {
                // The right side is the type (and possibly `= value` already folded in).
                if let Some(r) = right.take() {
                    if r.kind == "assignment" && r.child_by_field("left").is_some() {
                        // r is `type = value` parsed as assignment; split it.
                        let mut r = r;
                        let mut ty_node: Option<Node> = None;
                        let mut val_node: Option<Node> = None;
                        for c in r.children.drain(..) {
                            if c.field == Some("left") {
                                let mut ty = Node::new("type", c.start, c.end);
                                let mut c2 = c;
                                c2.field = None;
                                ty.push(c2);
                                ty_node = Some(ty);
                            } else if c.field == Some("right") {
                                val_node = Some(c);
                            }
                        }
                        if let Some(ty) = ty_node {
                            if !set {
                                node.start = ty.start;
                                node.end = ty.end;
                                set = true;
                            }
                            node.push(ty.with_field("type"));
                        }
                        if let Some(v) = val_node {
                            node.push(v);
                        }
                    } else {
                        let mut ty = Node::new("type", r.start, r.end);
                        ty.push(r);
                        if !set {
                            node.start = ty.start;
                            node.end = ty.end;
                            set = true;
                        }
                        node.push(ty.with_field("type"));
                    }
                }
            } else if let Some(r) = right.take() {
                if !set {
                    node.start = r.start;
                    node.end = r.end;
                }
                node.push(r.with_field("right"));
            }
            right = Some(node);
            i += 1;
        }
        let _ = i;
        if let Some(r) = right {
            result = Some(r);
        }
        match result {
            Some(r) => vec![r],
            None => Vec::new(),
        }
    }

    fn parse_lambda(&mut self, terminators: &[&str]) -> Node {
        let kw = self.advance();
        let mut node = Node::new("lambda", kw.start, kw.end);
        // Parameters until ':'
        let pstart = self.peek().start;
        let mut params = Node::new("lambda_parameters", pstart, pstart);
        let mut any = false;
        while !self.is_op(":") && !matches!(self.peek().tok, Tok::Newline | Tok::Eof | Tok::Dedent) {
            let t = self.peek().clone();
            if t.tok == Tok::Name {
                self.advance();
                params.push(Node::new("identifier", t.start, t.end));
                any = true;
            } else if t.tok == Tok::Op && self.text(&t) == "=" {
                self.advance();
                let d = self.parse_expression(&[",", ":"]);
                for x in d {
                    params.push(x);
                }
            } else if t.tok == Tok::Op && (self.text(&t) == ")" || self.text(&t) == "]" || self.text(&t) == "}") {
                break;
            } else {
                self.advance();
            }
        }
        if any {
            node.push(params.with_field("parameters"));
        }
        if self.is_op(":") {
            self.advance();
            let mut body_terms: Vec<&str> = terminators.to_vec();
            if !body_terms.contains(&",") {
                body_terms.push(",");
            }
            let body = self.parse_expression(&body_terms);
            let mut body_node: Option<Node> = None;
            if body.len() == 1 {
                body_node = body.into_iter().next();
            } else if !body.is_empty() {
                let mut e = Node::new("expression", body[0].start, body[body.len() - 1].end);
                for b in body {
                    e.push(b);
                }
                body_node = Some(e);
            }
            if let Some(b) = body_node {
                node.push(b.with_field("body"));
            }
        }
        node
    }

    /// Parse a primary: identifier with trailing `.attr`, `(call)`, `[subscript]`.
    fn parse_primary(&mut self) -> Node {
        let t = self.advance();
        let mut node = Node::new("identifier", t.start, t.end);
        loop {
            if self.is_op(".") && self.peek_n(1).tok == Tok::Name {
                self.advance();
                let n = self.advance();
                let mut attr = Node::new("attribute", node.start, n.end);
                attr.push(node.with_field("object"));
                attr.push(Node::new("identifier", n.start, n.end).with_field("attribute"));
                node = attr;
                continue;
            }
            if self.is_op("(") {
                let mut call = Node::new("call", node.start, node.end);
                call.push(node.with_field("function"));
                let mut args = Node::new("argument_list", self.peek().start, self.peek().start);
                self.parse_call_arguments(&mut args);
                call.push(args.with_field("arguments"));
                node = call;
                continue;
            }
            if self.is_op("[") {
                let mut sub = Node::new("subscript", node.start, node.end);
                sub.push(node.with_field("value"));
                let mut idx = Node::new("_subscript", self.peek().start, self.peek().start);
                self.parse_bracketed(&mut idx);
                sub.end = idx.end;
                for c in idx.children {
                    sub.push(c.with_field("subscript"));
                }
                node = sub;
                continue;
            }
            break;
        }
        node
    }

    /// Parse call arguments `( ... )` handling keyword arguments.
    fn parse_call_arguments(&mut self, parent: &mut Node) {
        let open = self.advance();
        parent.start = open.start;
        parent.end = open.end;
        loop {
            while self.peek().tok == Tok::Comment || self.peek().tok == Tok::Newline {
                self.advance();
            }
            if self.is_op(")") {
                let t = self.advance();
                parent.end = t.end;
                break;
            }
            if self.at_eof() || self.peek().tok == Tok::Dedent {
                break;
            }
            let before = self.i;
            // keyword argument?
            let t = self.peek().clone();
            let t1 = self.peek_n(1).clone();
            if t.tok == Tok::Name && t1.tok == Tok::Op && self.text(&t1) == "=" && !KEYWORDS.contains(&self.text(&t)) {
                self.advance();
                self.advance();
                let mut kw = Node::new("keyword_argument", t.start, t1.end);
                kw.push(Node::new("identifier", t.start, t.end).with_field("name"));
                let vals = self.parse_expression(&[",", ")"]);
                for v in vals {
                    kw.push(v.with_field("value"));
                }
                parent.push(kw);
            } else {
                let exprs = self.parse_expression(&[",", ")"]);
                for e in exprs {
                    parent.push(e);
                }
            }
            if self.is_op(",") {
                let t = self.advance();
                parent.end = t.end;
            } else if self.i == before {
                let t = self.advance();
                parent.end = t.end;
            }
        }
    }

    /// Parse a string token into a `string` node with start/content/end children and
    /// interpolations.
    fn parse_string_token(&mut self) -> Node {
        let t = self.advance();
        let info = match &t.tok {
            Tok::Str(i) => i.clone(),
            _ => unreachable!(),
        };
        let mut node = Node::new("string", t.start, t.end);
        node.push(Node::new("string_start", t.start, info.start_end));
        let mut pos = info.start_end;
        let mut content_segments: Vec<(usize, usize)> = Vec::new();
        for (is, ie) in &info.interpolations {
            if *is > pos {
                content_segments.push((pos, *is));
            }
            pos = *ie;
        }
        if info.content_end > pos {
            content_segments.push((pos, info.content_end));
        }
        // Build children in order.
        let mut kids: Vec<Node> = Vec::new();
        for (s, e) in &content_segments {
            kids.push(Node::new("string_content", *s, *e));
        }
        for (is, ie) in &info.interpolations {
            let mut interp = Node::new("interpolation", *is, *ie);
            // Parse the expression inside.
            let inner_start = is + 1;
            let inner_end = ie.saturating_sub(1).max(inner_start);
            let inner = &self.src[inner_start..inner_end];
            let sub = parse_fragment(inner, inner_start);
            for c in sub {
                interp.push(c);
            }
            interp.end = *ie;
            interp.start = *is;
            kids.push(interp);
        }
        kids.sort_by_key(|k| k.start);
        for k in kids {
            node.push(k);
        }
        if info.content_end <= t.end {
            node.push(Node::new("string_end", info.content_end, t.end));
        }
        node.start = t.start;
        node.end = t.end;
        node
    }
}

/// Parse an expression fragment (e.g. inside an f-string interpolation), with absolute
/// offsets shifted by `offset`.
fn parse_fragment(src: &str, offset: usize) -> Vec<Node> {
    // Strip format spec / conversion: `expr!r:fmt` → take up to '!' or ':' at depth 0.
    let bytes = src.as_bytes();
    let mut depth = 0i32;
    let mut end = bytes.len();
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'(' | b'[' | b'{' => depth += 1,
            b')' | b']' | b'}' => depth -= 1,
            b'!' if depth == 0 && bytes.get(i + 1) != Some(&b'=') => {
                end = i;
                break;
            }
            b':' if depth == 0 => {
                end = i;
                break;
            }
            b'\'' | b'"' => {
                let q = bytes[i];
                i += 1;
                while i < bytes.len() && bytes[i] != q {
                    i += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
    let frag = &src[..end];
    let toks = Lexer::new(frag).lex();
    let mut p = Parser { src: frag, toks, i: 0 };
    let exprs = p.parse_expression(&[]);
    exprs.into_iter().map(|n| shift(n, offset)).collect()
}

fn shift(mut n: Node, offset: usize) -> Node {
    n.start += offset;
    n.end += offset;
    n.children = n.children.into_iter().map(|c| shift(c, offset)).collect();
    n
}

/// Flatten `_statements` wrapper nodes into their parents.
fn flatten(node: &mut Node) {
    let mut new_children = Vec::with_capacity(node.children.len());
    for mut c in node.children.drain(..) {
        flatten(&mut c);
        if c.kind == "_statements" {
            for cc in c.children {
                new_children.push(cc);
            }
        } else {
            new_children.push(c);
        }
    }
    node.children = new_children;
}

pub fn parse(src: &str) -> Node {
    let toks = Lexer::new(src).lex();
    let mut p = Parser { src, toks, i: 0 };
    let mut module = p.parse_module();
    flatten(&mut module);
    module
}

// ---------------------------------------------------------------------------
// Prepared queries
// ---------------------------------------------------------------------------

fn is_docstring_stmt(n: &Node, src: &str) -> Option<Range> {
    if n.kind != "expression_statement" || n.children.len() != 1 {
        return None;
    }
    let s = &n.children[0];
    if s.kind != "string" {
        return None;
    }
    let start = s.child_of_kind("string_start")?;
    if start.text(src) != "\"\"\"" {
        return None;
    }
    let content = s.child_of_kind("string_content")?;
    Some(content.range())
}

fn decorator_name(dec: &Node, src: &str) -> Option<String> {
    // decorator → expression: identifier | attribute | call
    let expr = dec.children.iter().find(|c| !c.anonymous)?;
    let name_node = match expr.kind {
        "identifier" => expr,
        "attribute" => expr.child_by_field("attribute")?,
        "call" => {
            let f = expr.child_by_field("function")?;
            match f.kind {
                "identifier" => f,
                "attribute" => f.child_by_field("attribute")?,
                _ => return None,
            }
        }
        _ => return None,
    };
    Some(name_node.text(src).to_owned())
}

pub fn ranges(name: &str, src: &str) -> Vec<Range> {
    let tree = parse(src);
    log::debug!("S expression of parsed source code is: {:?}", tree.sexp());
    let mut out = Vec::new();
    match name {
        "comments" => {
            out = super::tree::ranges_of_kind(&tree, "comment");
        }
        "strings" => {
            out = super::tree::ranges_of_kind(&tree, "string_content");
        }
        "imports" => {
            tree.walk(&mut |n, _| {
                if n.kind == "import_statement" {
                    for c in &n.children {
                        match c.kind {
                            "dotted_name" => out.push(c.range()),
                            "aliased_import" => {
                                if let Some(d) = c.child_by_field("name") {
                                    out.push(d.range());
                                }
                            }
                            _ => {}
                        }
                    }
                } else if n.kind == "import_from_statement" {
                    if let Some(m) = n.child_by_field("module_name") {
                        out.push(m.range());
                    }
                }
            });
        }
        "doc-strings" => {
            tree.walk(&mut |n, _| {
                if let Some(r) = is_docstring_stmt(n, src) {
                    out.push(r);
                }
            });
        }
        "function-names" => {
            tree.walk(&mut |n, _| {
                if n.kind == "function_definition" {
                    if let Some(id) = n.child_by_field("name") {
                        out.push(id.range());
                    }
                }
            });
        }
        "function-calls" => {
            tree.walk(&mut |n, _| {
                if n.kind == "call" {
                    if let Some(f) = n.child_by_field("function") {
                        if f.kind == "identifier" {
                            out.push(f.range());
                        }
                    }
                }
            });
        }
        "class" => out = super::tree::ranges_of_kind(&tree, "class_definition"),
        "def" => out = super::tree::ranges_of_kind(&tree, "function_definition"),
        "async-def" => {
            tree.walk(&mut |n, _| {
                if n.kind == "function_definition" && n.has_child_kind("async") {
                    out.push(n.range());
                }
            });
        }
        "methods" => {
            tree.walk(&mut |n, _| {
                if n.kind == "class_definition" {
                    if let Some(body) = n.child_by_field("body") {
                        for c in &body.children {
                            if c.kind == "function_definition" || c.kind == "decorated_definition" {
                                out.push(c.range());
                            }
                        }
                    }
                }
            });
        }
        "class-methods" | "static-methods" => {
            let want = if name == "class-methods" {
                "classmethod"
            } else {
                "staticmethod"
            };
            tree.walk(&mut |n, _| {
                if n.kind == "decorated_definition" {
                    let has = n
                        .children
                        .iter()
                        .filter(|c| c.kind == "decorator")
                        .any(|d| decorator_name(d, src).as_deref() == Some(want));
                    if has {
                        if let Some(def) = n.child_by_field("definition") {
                            if def.kind == "function_definition" {
                                out.push(def.range());
                            }
                        }
                    }
                }
            });
        }
        "with" => out = super::tree::ranges_of_kind(&tree, "with_statement"),
        "try" => out = super::tree::ranges_of_kind(&tree, "try_statement"),
        "lambda" => out = super::tree::ranges_of_kind(&tree, "lambda"),
        "globals" => {
            for stmt in &tree.children {
                if stmt.kind == "expression_statement" {
                    for e in &stmt.children {
                        if e.kind == "assignment" {
                            if let Some(l) = e.child_by_field("left") {
                                if l.kind == "identifier" {
                                    out.push(l.range());
                                }
                            }
                        }
                    }
                }
            }
        }
        "variable-identifiers" => {
            tree.walk(&mut |n, _| {
                if n.kind == "assignment" {
                    if let Some(l) = n.child_by_field("left") {
                        if l.kind == "identifier" {
                            out.push(l.range());
                        }
                    }
                }
            });
        }
        "types" => out = super::tree::ranges_of_kind(&tree, "type"),
        "identifiers" => out = super::tree::ranges_of_kind(&tree, "identifier"),
        _ => {}
    }
    out
}
