//! Shared lexing helpers for C-like languages.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Ident,
    Number,
    /// A string literal (all kinds); `content` gives the byte range of its contents.
    Str,
    /// A character literal.
    Char,
    LineComment,
    BlockComment,
    /// Lifetime / label (`'a`), Rust only.
    Lifetime,
    Punct,
    /// Preprocessor directive line (C/C#).
