#[derive(Debug, Clone)]
pub struct Token {
    pub kind: Kind,
    pub start: usize,
    pub end: usize,
    /// For strings: the content range(s), excluding delimiters (and escape sequences if
    /// requested by the language).
    pub content: Vec<(usize, usize)>,
    /// For strings: prefix text (e.g. `r#`, `b`, `@`, `$`, `f`).
    pub prefix: String,
}

impl Token {
    pub fn text<'a>(&self, src: &'a str) -> &'a str {
        &src[self.start..self.end]
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Flavor {
    Rust,
    Go,
    C,
    CSharp,
    TypeScript,
    Hcl,
}

pub struct Lexer<'a> {
    pub src: &'a str,
    bytes: &'a [u8],
    pos: usize,
    flavor: Flavor,
    pub tokens: Vec<Token>,
}

fn is_ident_start(c: char) -> bool {
    c.is_alphabetic() || c == '_' || c == '$'
}

fn is_ident_char(c: char) -> bool {
    c.is_alphanumeric() || c == '_' || c == '$'
}

const PUNCT3: &[&str] = &[
    "<<=", ">>=", "...", "..=", "===", "!==", "**=", "??=", "&&=", "||=", ">>>", "<=>",
];
const PUNCT2: &[&str] = &[
    "::", "->", "=>", "==", "!=", "<=", ">=", "&&", "||", "+=", "-=", "*=", "/=", "%=", "&=",
    "|=", "^=", "<<", ">>", "..", "++", "--", "**", "?.", "??", ":=", "<-", "#[", "#!",
];

impl<'a> Lexer<'a> {
    pub fn new(src: &'a str, flavor: Flavor) -> Self {
        Self {
            src,
            bytes: src.as_bytes(),
            pos: 0,
            flavor,
            tokens: Vec::new(),
        }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn peek_at(&self, n: usize) -> Option<u8> {
        self.bytes.get(self.pos + n).copied()
    }

    fn push(&mut self, kind: Kind, start: usize, end: usize) {
        self.tokens.push(Token {
            kind,
            start,
            end,
            content: Vec::new(),
            prefix: String::new(),
        });
    }

    fn push_str(&mut self, start: usize, end: usize, content: Vec<(usize, usize)>, prefix: String) {
        self.tokens.push(Token {
            kind: Kind::Str,
            start,
            end,
            content,
            prefix,
        });
    }

    /// Regular quoted string with backslash escapes. Returns end position.
    /// `split_escapes`: whether content ranges exclude escape sequences.
    fn quoted(&mut self, start: usize, quote_pos: usize, q: u8, split_escapes: bool, allow_newline: bool, prefix: String) {
        let mut pos = quote_pos + 1;
        let content_start = pos;
        let mut content: Vec<(usize, usize)> = Vec::new();
        let mut seg_start = content_start;
        let is_template = q == b'`' && self.flavor == Flavor::TypeScript;
        let is_hcl_interp = self.flavor == Flavor::Hcl;
        loop {
            if pos >= self.bytes.len() {
                break;
            }
            let c = self.bytes[pos];
            if c == b'\\' && pos + 1 < self.bytes.len() {
                if split_escapes {
                    if pos > seg_start {
                        content.push((seg_start, pos));
                    }
                    // Escape sequence length.
                    let n = self.bytes[pos + 1];
                    let mut len = 2;
                    match n {
                        b'x' => len = 4,
                        b'u' => {
                            if self.bytes.get(pos + 2) == Some(&b'{') {
                                let mut k = pos + 2;
                                while k < self.bytes.len() && self.bytes[k] != b'}' {
                                    k += 1;
                                }
                                len = k + 1 - pos;
                            } else {
                                len = 6;
                            }
                        }
                        b'\n' => {
                            // Line continuation: skip following whitespace too.
                            let mut k = pos + 2;
                            while k < self.bytes.len() && matches!(self.bytes[k], b' ' | b'\t' | b'\n' | b'\r') {
                                k += 1;
                            }
                            len = k - pos;
                        }
                        _ => {}
                    }
                    pos = (pos + len).min(self.bytes.len());
                    seg_start = pos;
                } else {
                    pos += 2;
                }
                continue;
            }
            if (is_template || is_hcl_interp) && c == b'$' && self.bytes.get(pos + 1) == Some(&b'{') {
                // Interpolation: content split around `${...}`.
                if pos > seg_start {
                    content.push((seg_start, pos));
                }
                let mut depth = 0;
                let mut k = pos + 1;
                while k < self.bytes.len() {
                    match self.bytes[k] {
                        b'{' => depth += 1,
                        b'}' => {
                            depth -= 1;
                            if depth == 0 {
                                break;
                            }
                        }
                        b'"' | b'\'' | b'`' if is_template => {
                            let nq = self.bytes[k];
                            k += 1;
                            while k < self.bytes.len() && self.bytes[k] != nq {
                                if self.bytes[k] == b'\\' {
                                    k += 1;
                                }
                                k += 1;
                            }
                        }
                        _ => {}
                    }
                    k += 1;
                }
                pos = (k + 1).min(self.bytes.len());
                seg_start = pos;
                continue;
            }
            if c == q {
                if pos > seg_start {
                    content.push((seg_start, pos));
                }
                pos += 1;
                self.push_str(start, pos, content, prefix);
                self.pos = pos;
                return;
            }
            if c == b'\n' && !allow_newline {
                // Unterminated.
                if pos > seg_start {
                    content.push((seg_start, pos));
                }
                self.push_str(start, pos, content, prefix);
                self.pos = pos;
                return;
            }
            pos += 1;
        }
        if pos > seg_start {
            content.push((seg_start, pos));
        }
        self.push_str(start, pos, content, prefix);
        self.pos = pos;
    }

    /// Raw string (no escapes) delimited by `open`/`close` sequences.
    fn raw(&mut self, start: usize, content_start: usize, close: &[u8], prefix: String) {
        let mut pos = content_start;
        while pos < self.bytes.len() {
            if self.bytes[pos..].starts_with(close) {
                let content = if pos > content_start {
                    vec![(content_start, pos)]
                } else {
                    vec![]
                };
                let end = pos + close.len();
                self.push_str(start, end, content, prefix);
                self.pos = end;
                return;
            }
            pos += 1;
        }
        let content = if pos > content_start {
            vec![(content_start, pos)]
        } else {
            vec![]
        };
        self.push_str(start, pos, content, prefix);
        self.pos = pos;
    }

    pub fn lex(mut self) -> Vec<Token> {
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            let start = self.pos;
            match c {
                b' ' | b'\t' | b'\n' | b'\r' | b'\x0c' => {
                    self.pos += 1;
                }
                b'/' if self.peek_at(1) == Some(b'/') => {
                    let mut end = self.pos;
                    while end < self.bytes.len() && self.bytes[end] != b'\n' {
                        end += 1;
                    }
                    self.push(Kind::LineComment, start, end);
                    self.pos = end;
                }
                b'/' if self.peek_at(1) == Some(b'*') => {
                    let mut end = self.pos + 2;
                    let mut depth = 1;
                    while end < self.bytes.len() {
                        if self.flavor == Flavor::Rust && self.bytes[end..].starts_with(b"/*") {
                            depth += 1;
                            end += 2;
                            continue;
                        }
                        if self.bytes[end..].starts_with(b"*/") {
                            depth -= 1;
                            end += 2;
                            if depth == 0 {
                                break;
                            }
                            continue;
                        }
                        end += 1;
                    }
                    let end = end.min(self.bytes.len());
                    self.push(Kind::BlockComment, start, end);
                    self.pos = end;
                }
                b'#' if self.flavor == Flavor::Hcl || (self.flavor == Flavor::Rust && false) => {
                    let mut end = self.pos;
                    while end < self.bytes.len() && self.bytes[end] != b'\n' {
                        end += 1;
                    }
                    self.push(Kind::LineComment, start, end);
                    self.pos = end;
                }
                b'#' if matches!(self.flavor, Flavor::C | Flavor::CSharp) => {
                    // Preprocessor directive: to end of line (with continuations). For C we
                    // tokenize the directive content as well, so emit a Directive marker and
                    // continue lexing the rest of the line normally.
                    self.push(Kind::Directive, start, start + 1);
                    self.pos += 1;
                }
                b'"' => {
                    let split = self.flavor == Flavor::Rust;
                    self.quoted(start, start, b'"', split, self.flavor == Flavor::Rust || self.flavor == Flavor::Hcl, String::new());
                }
                b'`' if self.flavor == Flavor::Go => {
                    self.raw(start, start + 1, b"`", String::new());
                }
                b'`' if self.flavor == Flavor::TypeScript => {
                    self.quoted(start, start, b'`', false, true, String::new());
                }
                b'\'' => {
                    if self.flavor == Flavor::Rust {
                        // Lifetime or char literal.
                        let rest = &self.src[self.pos + 1..];
                        let mut chars = rest.chars();
                        match chars.next() {
                            Some(ch) if ch == '\\' => {
                                // char with escape
                                let mut end = self.pos + 2;
                                while end < self.bytes.len() && self.bytes[end] != b'\'' && self.bytes[end] != b'\n' {
                                    end += 1;
                                }
                                let end = (end + 1).min(self.bytes.len());
                                self.push(Kind::Char, start, end);
                                self.pos = end;
                            }
                            Some(ch) => {
                                let after = self.pos + 1 + ch.len_utf8();
                                if self.bytes.get(after) == Some(&b'\'') {
                                    self.push(Kind::Char, start, after + 1);
                                    self.pos = after + 1;
                                } else {
                                    // Lifetime / label.
                                    let mut end = self.pos + 1;
                                    for ch in rest.chars() {
                                        if is_ident_char(ch) {
                                            end += ch.len_utf8();
                                        } else {
                                            break;
                                        }
                                    }
                                    if end == self.pos + 1 {
                                        end += 1;
                                    }
                                    self.push(Kind::Lifetime, start, end);
                                    self.pos = end;
                                }
                            }
                            None => {
                                self.push(Kind::Other, start, start + 1);
                                self.pos += 1;
                            }
                        }
                    } else if matches!(self.flavor, Flavor::TypeScript) {
                        self.quoted(start, start, b'\'', false, false, String::new());
                    } else {
                        // Char literal (C, C#, Go) — treat as Char token.
                        let mut end = self.pos + 1;
                        while end < self.bytes.len() && self.bytes[end] != b'\'' && self.bytes[end] != b'\n' {
                            if self.bytes[end] == b'\\' {
                                end += 1;
                            }
                            end += 1;
                        }
                        let end = (end + 1).min(self.bytes.len());
                        self.push(Kind::Char, start, end);
                        self.pos = end;
                    }
                }
                b'0'..=b'9' => {
                    let mut end = self.pos + 1;
                    while end < self.bytes.len() {
                        let b = self.bytes[end];
                        if b.is_ascii_alphanumeric() || b == b'_' || b == b'.' && self.bytes.get(end + 1).map_or(false, |n| n.is_ascii_digit()) {
                            end += 1;
                        } else if (b == b'+' || b == b'-') && matches!(self.bytes[end - 1], b'e' | b'E') && !self.src[start..end].starts_with("0x") {
                            end += 1;
                        } else {
                            break;
                        }
                    }
                    self.push(Kind::Number, start, end);
                    self.pos = end;
                }
                _ if c < 0x80 && (c.is_ascii_alphabetic() || c == b'_' || (c == b'$' && self.flavor == Flavor::TypeScript)) || c >= 0x80 => {
                    let rest = &self.src[self.pos..];
                    let ch = rest.chars().next().unwrap();
                    if !is_ident_start(ch) {
                        self.push(Kind::Other, start, start + ch.len_utf8());
                        self.pos += ch.len_utf8();
                        continue;
                    }
                    let mut end = self.pos;
                    for ch in rest.chars() {
                        if is_ident_char(ch) {
                            end += ch.len_utf8();
                        } else {
                            break;
                        }
                    }
                    let word = &self.src[start..end];
                    // Language specific string prefixes.
                    match self.flavor {
                        Flavor::Rust => {
                            let next = self.bytes.get(end).copied();
                            if (word == "r" || word == "br" || word == "cr") && (next == Some(b'"') || next == Some(b'#')) {
                                // Raw string: r#*"..."#*
                                let mut hashes = 0;
                                let mut p = end;
                                while self.bytes.get(p) == Some(&b'#') {
                                    hashes += 1;
                                    p += 1;
                                }
                                if self.bytes.get(p) == Some(&b'"') {
                                    let mut close = vec![b'"'];
                                    close.extend(std::iter::repeat(b'#').take(hashes));
                                    let prefix = self.src[start..p + 1].to_owned();
                                    self.raw(start, p + 1, &close, prefix);
                                    continue;
                                }
                            }
                            if (word == "b" || word == "c") && next == Some(b'"') {
                                self.quoted(start, end, b'"', true, true, word.to_owned());
                                continue;
                            }
                            if word == "b" && next == Some(b'\'') {
                                let mut e2 = end + 1;
                                while e2 < self.bytes.len() && self.bytes[e2] != b'\'' && self.bytes[e2] != b'\n' {
                                    if self.bytes[e2] == b'\\' {
                                        e2 += 1;
                                    }
                                    e2 += 1;
                                }
                                let e2 = (e2 + 1).min(self.bytes.len());
                                self.push(Kind::Char, start, e2);
                                self.pos = e2;
                                continue;
                            }
                            if word == "r" && next == Some(b'#') {
                                // raw identifier r#ident
                                let mut e2 = end + 1;
                                for ch in self.src[e2..].chars() {
                                    if is_ident_char(ch) {
                                        e2 += ch.len_utf8();
                                    } else {
                                        break;
                                    }
                                }
                                self.push(Kind::Ident, start, e2);
                                self.pos = e2;
                                continue;
                            }
                        }
                        Flavor::CSharp => {
                            let next = self.bytes.get(end).copied();
                            if next == Some(b'"') && word.chars().all(|c| c == '$' || c == '@') {
                                // handled below via '$'/'@' punct path; not reached since '$' isn't ident start in C#
                            }
                            let _ = next;
                        }
                        _ => {}
                    }
                    self.push(Kind::Ident, start, end);
                    self.pos = end;
                }
                b'@' | b'$' if self.flavor == Flavor::CSharp => {
                    // Verbatim / interpolated strings: @"...", $"...", $@"...", @$"..."
                    let mut p = self.pos;
                    let mut verbatim = false;
                    let mut interp = false;
                    while let Some(b) = self.bytes.get(p) {
                        match b {
                            b'@' => verbatim = true,
                            b'$' => interp = true,
                            _ => break,
                        }
                        p += 1;
                    }
                    if self.bytes.get(p) == Some(&b'"') {
                        let prefix = self.src[start..p].to_owned();
                        if self.bytes.get(p + 1) == Some(&b'"') && self.bytes.get(p + 2) == Some(&b'"') {
                            // Raw string literal """..."""
                            self.raw(start, p + 3, b"\"\"\"", prefix);
                        } else if verbatim {
                            // Verbatim: "" escapes the quote, no backslash escapes.
                            let mut pos = p + 1;
                            let cstart = pos;
                            while pos < self.bytes.len() {
                                if self.bytes[pos] == b'"' {
                                    if self.bytes.get(pos + 1) == Some(&b'"') {
                                        pos += 2;
                                        continue;
                                    }
                                    break;
                                }
                                pos += 1;
                            }
                            let content = if interp {
                                split_interpolations(self.bytes, cstart, pos)
                            } else if pos > cstart {
                                vec![(cstart, pos)]
                            } else {
                                vec![]
                            };
                            let end = (pos + 1).min(self.bytes.len());
                            self.push_str(start, end, content, prefix);
                            self.pos = end;
                        } else {
                            self.quoted(start, p, b'"', false, false, prefix.clone());
                            if interp {
                                if let Some(last) = self.tokens.last_mut() {
                                    let (cs, ce) = (last.start + prefix.len() + 1, last.end.saturating_sub(1).max(last.start + prefix.len() + 1));
                                    last.content = split_interpolations(self.bytes, cs, ce);
                                }
                            }
                        }
                        let _ = interp;
                    } else if c == b'@' {
                        // @identifier (verbatim identifier) or attribute-less @
                        let rest = &self.src[self.pos + 1..];
                        let mut end = self.pos + 1;
                        for ch in rest.chars() {
                            if is_ident_char(ch) {
                                end += ch.len_utf8();
                            } else {
                                break;
                            }
                        }
                        if end > self.pos + 1 {
                            self.push(Kind::Ident, start, end);
                        } else {
                            self.push(Kind::Punct, start, end);
                        }
                        self.pos = end;
                    } else {
                        self.push(Kind::Punct, start, start + 1);
                        self.pos += 1;
                    }
                }
                _ => {
                    // Punctuation (longest match).
                    let rest = &self.src[self.pos..];
                    let mut len = 1;
                    for p in PUNCT3 {
                        if rest.starts_with(p) {
                            len = 3;
                            break;
                        }
                    }
                    if len == 1 {
                        for p in PUNCT2 {
                            if rest.starts_with(p) {
                                len = 2;
                                break;
                            }
                        }
                    }
                    // `#[` only meaningful in Rust; `#!` likewise.
                    if len == 2 && (rest.starts_with("#[") || rest.starts_with("#!")) && self.flavor != Flavor::Rust {
                        len = 1;
                    }
                    if len == 2 && rest.starts_with("<-") && self.flavor != Flavor::Go {
                        len = 1;
                    }
                    if len == 2 && rest.starts_with("::") && matches!(self.flavor, Flavor::Go | Flavor::Hcl) {
                        len = 1;
                    }
                    if len == 2 && rest.starts_with("?.") && self.flavor != Flavor::TypeScript && self.flavor != Flavor::CSharp {
                        len = 1;
                    }
                    self.push(Kind::Punct, start, start + len);
                    self.pos = start + len;
                }
            }
        }
        self.tokens
    }
}

/// Split string content around `{...}` interpolation holes (C# interpolated strings),
/// treating `{{`/`}}` as escapes.
fn split_interpolations(bytes: &[u8], start: usize, end: usize) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    let mut seg = start;
    let mut i = start;
    while i < end {
        if bytes[i] == b'{' {
            if bytes.get(i + 1) == Some(&b'{') {
                i += 2;
                continue;
            }
            if i > seg {
                out.push((seg, i));
            }
            let mut depth = 0;
            let mut k = i;
            while k < end {
                match bytes[k] {
                    b'{' => depth += 1,
                    b'}' => {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    _ => {}
                }
                k += 1;
            }
            i = (k + 1).min(end);
            seg = i;
            continue;
        }
        if bytes[i] == b'}' && bytes.get(i + 1) == Some(&b'}') {
            i += 2;
            continue;
        }
        i += 1;
    }
    if end > seg {
        out.push((seg, end));
    }
    out
}

/// Find the index of the token closing the bracket opened at `open_idx`.
pub fn matching_close(tokens: &[Token], src: &str, open_idx: usize) -> Option<usize> {
    let open = tokens[open_idx].text(src);
    let close = match open {
        "(" => ")",
        "[" => "]",
        "{" => "}",
        "<" => ">",
        "#[" | "#![" => "]",
        _ => return None,
    };
    let mut depth = 0i32;
    for (i, t) in tokens.iter().enumerate().skip(open_idx) {
        if t.kind != Kind::Punct {
            continue;
        }
        let s = t.text(src);
        let s = if s == "#[" || s == "#!" { "[" } else { s };
        if s == open || (open.starts_with('#') && s == "[") {
            depth += 1;
        } else if s == close {
            depth -= 1;
            if depth == 0 {
                return Some(i);
            }
        }
    }
    None
}
