const KEYWORDS: &[&str] = &[
    "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum",
    "extern", "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod", "move",
    "mut", "pub", "ref", "return", "self", "static", "struct", "super", "trait", "true", "type",
    "unsafe", "use", "where", "while", "yield", "union", "macro_rules", "default", "raw",
];

const PRIMITIVES: &[&str] = &[
    "u8", "u16", "u32", "u64", "u128", "usize", "i8", "i16", "i32", "i64", "i128", "isize",
    "f32", "f64", "bool", "char", "str",
];

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    roles: Vec<Role>,
    items: Vec<Item>,
    closures: Vec<Range>,
    unsafe_blocks: Vec<Range>,
    uses: Vec<Range>,
    attrs: Vec<Range>,
    /// Attribute texts pending for the next item.
    pending_attrs: Vec<String>,
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Mode {
    Items,
    Stmts,
    Expr,
}

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }

    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }

    fn is_kw(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && self.text(i) == s
    }

    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && !KEYWORDS.contains(&self.text(i))
    }

    fn set(&mut self, i: usize, r: Role) {
        if i < self.roles.len() && self.roles[i] == Role::Unknown {
            self.roles[i] = r;
        }
    }

    fn force(&mut self, i: usize, r: Role) {
        if i < self.roles.len() {
            self.roles[i] = r;
        }
    }

    /// Skip comment tokens starting at i.
    fn skip_comments(&self, mut i: usize) -> usize {
        while i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment) {
            i += 1;
        }
        i
    }

    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }

    /// Consume a type starting at `i`; returns index after the type. Marks roles.
    fn consume_type(&mut self, mut i: usize, limit: usize) -> usize {
        let i0 = i;
        let mut n = 0;
        while i < limit && n < 10000 {
            n += 1;
            let tok = &self.toks[i];
            match tok.kind {
                Kind::Punct => {
                    let s = self.text(i);
                    match s {
                        "&" | "&&" | "*" | "!" => {
                            i += 1;
                            continue;
                        }
                        "(" | "[" => {
                            let c = self.close_of(i);
                            let c = c.min(limit.saturating_sub(1)).max(i);
                            self.scan_type_list(i + 1, c);
                            i = c + 1;
                            // `fn(A) -> B` / `Fn(A) -> B` return types
                            if self.is_punct(i, "->") {
                                i = self.consume_type(i + 1, limit);
                            }
                            return i;
                        }
                        "<" => {
                            let c = self.close_angle(i, limit);
                            self.scan_type_list(i + 1, c);
                            i = c + 1;
                            if self.is_punct(i, "::") {
                                i += 1;
                                continue;
                            }
                            return i;
                        }
                        "::" => {
                            i += 1;
                            continue;
                        }
                        "'" => {
                            i += 1;
                            continue;
                        }
                        _ => return i,
                    }
                }
                Kind::Lifetime => {
                    self.mark_lifetime(i);
                    i += 1;
                    continue;
                }
                Kind::Ident => {
                    let s = self.text(i);
                    match s {
                        "mut" | "const" | "dyn" | "impl" | "unsafe" | "extern" | "for" | "async" => {
                            i += 1;
                            if s == "extern" && i < limit && self.toks[i].kind == Kind::Str {
                                i += 1;
                            }
                            if s == "for" && self.is_punct(i, "<") {
                                let c = self.close_angle(i, limit);
                                self.scan_type_list(i + 1, c);
                                i = c + 1;
                            }
                            continue;
                        }
                        "fn" | "Fn" | "FnMut" | "FnOnce" if s == "fn" => {
                            i += 1;
                            continue;
                        }
                        "self" | "crate" | "super" => {
                            i += 1;
                            if self.is_punct(i, "::") {
                                i += 1;
                            }
                            continue;
                        }
                        _ => {}
                    }
                    if PRIMITIVES.contains(&s) {
                        self.set(i, Role::Skip);
                    } else if self.is_punct(i + 1, "::") && !self.is_punct(i + 2, "<") {
                        self.set(i, Role::Ident);
                    } else {
                        self.set(i, Role::TypeIdent);
                    }
                    i += 1;
                    if self.is_punct(i, "::") {
                        i += 1;
                        if self.is_punct(i, "<") {
                            let c = self.close_angle(i, limit);
                            self.scan_type_list(i + 1, c);
                            i = c + 1;
                            if self.is_punct(i, "::") {
                                i += 1;
                            }
                        }
                        continue;
                    }
                    if self.is_punct(i, "<") {
                        let c = self.close_angle(i, limit);
                        self.scan_type_list(i + 1, c);
                        i = c + 1;
                        if self.is_punct(i, "::") {
                            i += 1;
                            continue;
                        }
                    }
                    // Trait object bounds: `dyn A + B`, `impl A + B`
                    if self.is_punct(i, "+") {
                        i += 1;
                        continue;
                    }
                    return i;
                }
                Kind::LineComment | Kind::BlockComment => {
                    i += 1;
                }
                _ => return i,
            }
        }
        i.max(i0)
    }

    /// Find the matching `>` for `<` at i (handles `>>`).
    fn close_angle(&self, open: usize, limit: usize) -> usize {
        let mut depth = 0i32;
        let mut i = open;
        while i < limit {
            if self.toks[i].kind == Kind::Punct {
                match self.text(i) {
                    "<" => depth += 1,
                    ">" => {
                        depth -= 1;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    ">>" => {
                        depth -= 2;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    "(" | "[" | "{" => {
                        i = self.close_of(i);
                    }
                    ";" => return i,
                    _ => {}
                }
            }
            i += 1;
        }
        limit.saturating_sub(1).max(open)
    }

    /// Scan a comma separated list of types / bounds / generic params in [start, end).
    fn scan_type_list(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            let tok_kind = self.toks[i].kind;
            if tok_kind == Kind::Punct {
                let s = self.text(i);
                if s == "," || s == ":" || s == "+" || s == "=" || s == "?" || s == ";" {
                    i += 1;
                    continue;
                }
            }
            if tok_kind == Kind::Lifetime {
                self.mark_lifetime(i);
                i += 1;
                continue;
            }
            if tok_kind == Kind::Number || tok_kind == Kind::Str || tok_kind == Kind::Char {
                i += 1;
                continue;
            }
            if self.is_kw(i, "const") {
                // const generic: `const N: usize`
                i += 1;
                if self.is_ident(i) {
                    self.set(i, Role::Ident);
                    i += 1;
                }
                continue;
            }
            if self.is_punct(i, "{") {
                // const expression block
                let c = self.close_of(i);
                self.scan(i + 1, c, Mode::Expr);
                i = c + 1;
                continue;
            }
            let next = self.consume_type(i, end);
            if next == i {
                i += 1;
            } else {
                i = next;
            }
        }
    }

    fn mark_lifetime(&mut self, i: usize) {
        let _ = i;
    }

    /// Parse `#[...]` / `#![...]` at i (token `#`). Returns index after.
    fn parse_attribute(&mut self, i: usize) -> usize {
        let mut j = i + 1;
        if self.is_punct(j, "!") {
            j += 1;
        }
        if self.is_punct(j, "[") {
            let c = self.close_of(j);
            let inner_start = self.toks[j].end;
            let inner_end = self.toks[c].start;
            self.attrs.push(inner_start..inner_end);
            let text = self.src[inner_start..inner_end].to_owned();
            self.pending_attrs.push(text);
            self.scan(j + 1, c, Mode::Expr);
            return c + 1;
        }
        i + 1
    }

    /// Try to parse an item starting at i (statement start). Returns Some(index after item).
    fn try_item(&mut self, i: usize, limit: usize, parent: Parent) -> Option<usize> {
        let start_tok = i;
        let mut j = i;
        let mut vis = String::new();
        let mut quals: Vec<String> = Vec::new();
        // Visibility.
        if self.is_kw(j, "pub") {
            j += 1;
            if self.is_punct(j, "(") {
                let c = self.close_of(j);
                vis = self.src[self.toks[start_tok].start..self.toks[c].end].to_owned();
                // `pub(in path)`
                for k in j + 1..c {
                    if self.is_ident(k) {
                        self.set(k, Role::Ident);
                    }
                }
                j = c + 1;
            } else {
                vis = "pub".to_owned();
            }
        }
        // Qualifiers.
        loop {
            if j >= limit {
                return None;
            }
            let s = self.text(j);
            if self.toks[j].kind == Kind::Ident && matches!(s, "const" | "async" | "unsafe" | "extern" | "default") {
                // `const X: T = ...` / `const fn` / `unsafe { }` / `unsafe impl` / `extern "C" fn` / `extern crate` / `extern { }`
                let next = j + 1;
                if s == "const" && !self.is_kw(next, "fn") && !self.is_kw(next, "unsafe") && !self.is_kw(next, "async") && !self.is_kw(next, "extern") {
                    break;
                }
                if s == "unsafe" && self.is_punct(next, "{") {
                    return None;
                }
                if s == "extern" && self.toks[next].kind == Kind::Str && self.is_punct(next + 1, "{") {
                    // extern block
                    let c = self.close_of(next + 1);
                    self.scan(next + 2, c, Mode::Items);
                    return Some(c + 1);
                }
                if s == "extern" && self.is_punct(next, "{") {
                    let c = self.close_of(next);
                    self.scan(next + 1, c, Mode::Items);
                    return Some(c + 1);
                }
                if s == "extern" && self.is_kw(next, "crate") {
                    let mut k = next + 1;
                    if self.is_ident(k) {
                        self.set(k, Role::Ident);
                        k += 1;
                    }
                    if self.is_kw(k, "as") {
                        k += 1;
                        if self.is_ident(k) {
                            self.set(k, Role::Ident);
                            k += 1;
                        }
                    }
                    if self.is_punct(k, ";") {
                        k += 1;
                    }
                    return Some(k);
                }
                quals.push(s.to_owned());
                j += 1;
                if s == "extern" && j < limit && self.toks[j].kind == Kind::Str {
                    j += 1;
                }
                continue;
            }
            break;
        }
        if j >= limit {
            return None;
        }
        let kw = self.text(j);
        if self.toks[j].kind != Kind::Ident {
            return None;
        }
        let attrs = std::mem::take(&mut self.pending_attrs);
        let item_start = self.toks[start_tok].start;
        let mut item = Item {
            kind: ItemKind::Other,
            start: item_start,
            end: item_start,
            name: None,
            vis: vis.clone(),
            quals: quals.clone(),
            attrs,
            parent,
            has_for: false,
            variants: Vec::new(),
        };
        let end_idx: usize;
        match kw {
            "fn" => {
                item.kind = ItemKind::Fn;
                let mut k = j + 1;
                if self.is_ident(k) {
                    self.set(k, Role::Ident);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                }
                k = self.parse_generics(k, limit);
                if self.is_punct(k, "(") {
                    let c = self.close_of(k);
                    self.scan_params(k + 1, c);
                    k = c + 1;
                }
                if self.is_punct(k, "->") {
                    k = self.consume_type(k + 1, limit);
                }
                k = self.parse_where(k, limit);
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan(k + 1, c, Mode::Stmts);
                    // nested items get parent Fn
                    end_idx = c;
                } else {
                    // signature
                    item.kind = ItemKind::FnSignature;
                    while k < limit && !self.is_punct(k, ";") {
                        k += 1;
                    }
                    end_idx = k.min(limit - 1);
                }
            }
            "struct" | "union" => {
                item.kind = if kw == "struct" { ItemKind::Struct } else { ItemKind::Union };
                let mut k = j + 1;
                if self.is_ident(k) {
                    self.set(k, Role::TypeIdent);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                }
                k = self.parse_generics(k, limit);
                k = self.parse_where(k, limit);
                if self.is_punct(k, "(") {
                    let c = self.close_of(k);
                    self.scan_tuple_fields(k + 1, c);
                    k = c + 1;
                    k = self.parse_where(k, limit);
                }
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan_struct_fields(k + 1, c);
                    end_idx = c;
                } else {
                    while k < limit && !self.is_punct(k, ";") {
                        k += 1;
                    }
                    end_idx = k.min(limit - 1);
                }
            }
            "enum" => {
                item.kind = ItemKind::Enum;
                let mut k = j + 1;
                if self.is_ident(k) {
                    self.set(k, Role::TypeIdent);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                }
                k = self.parse_generics(k, limit);
                k = self.parse_where(k, limit);
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    item.variants = self.scan_enum_variants(k + 1, c);
                    end_idx = c;
                } else {
                    end_idx = k.min(limit - 1);
                }
            }
            "trait" => {
                item.kind = ItemKind::Trait;
                let mut k = j + 1;
                if self.is_ident(k) {
                    self.set(k, Role::TypeIdent);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                }
                k = self.parse_generics(k, limit);
                if self.is_punct(k, ":") {
                    k += 1;
                    let brace = self.find_brace(k, limit);
                    self.scan_type_list(k, brace);
                    k = brace;
                }
                k = self.parse_where(k, limit);
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan_items(k + 1, c, Parent::Trait);
                    end_idx = c;
                } else {
                    end_idx = k.min(limit - 1);
                }
            }
            "impl" => {
                item.kind = ItemKind::Impl;
                let mut k = j + 1;
                k = self.parse_generics(k, limit);
                if self.is_punct(k, "!") {
                    k += 1;
                }
                k = self.consume_type(k, limit);
                if self.is_kw(k, "for") {
                    item.has_for = true;
                    k = self.consume_type(k + 1, limit);
                }
                k = self.parse_where(k, limit);
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan_items(k + 1, c, Parent::Impl);
                    end_idx = c;
                } else {
                    end_idx = k.min(limit - 1);
                }
            }
            "mod" => {
                item.kind = ItemKind::Mod;
                let mut k = j + 1;
                if self.is_ident(k) {
                    self.set(k, Role::Ident);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                }
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan_items(k + 1, c, Parent::Module);
                    end_idx = c;
                } else {
                    // `mod foo;` — not a mod block.
                    item.kind = ItemKind::Other;
                    end_idx = k.min(limit - 1);
                }
            }
            "use" => {
                item.kind = ItemKind::Use;
                let mut k = j + 1;
                let path_start = k;
                while k < limit && !self.is_punct(k, ";") {
                    if self.is_ident(k) {
                        self.set(k, Role::Ident);
                    }
                    k += 1;
                }
                if k > path_start && k <= limit {
                    let s = self.toks[path_start].start;
                    let e = self.toks[k - 1].end;
                    if e > s {
                        self.uses.push(s..e);
                    }
                }
                end_idx = k.min(limit - 1);
            }
            "type" => {
                item.kind = ItemKind::TypeAlias;
                let mut k = j + 1;
                if self.is_ident(k) {
                    self.set(k, Role::TypeIdent);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                }
                k = self.parse_generics(k, limit);
                if self.is_punct(k, ":") {
                    k += 1;
                    let semi = self.find_semi(k, limit);
                    let eq = self.find_eq(k, semi);
                    self.scan_type_list(k, eq);
                    k = eq;
                }
                k = self.parse_where(k, limit);
                if self.is_punct(k, "=") {
                    k = self.consume_type(k + 1, limit);
                }
                while k < limit && !self.is_punct(k, ";") {
                    k += 1;
                }
                end_idx = k.min(limit - 1);
            }
            "const" | "static" => {
                item.kind = if kw == "const" { ItemKind::Const } else { ItemKind::Static };
                let mut k = j + 1;
                if self.is_kw(k, "mut") {
                    k += 1;
                }
                if self.is_ident(k) {
                    self.set(k, Role::Ident);
                    item.name = Some(self.text(k).to_owned());
                    k += 1;
                } else if self.is_punct(k, "_") {
                    k += 1;
                }
                if self.is_punct(k, ":") {
                    k = self.consume_type(k + 1, limit);
                }
                if self.is_punct(k, "=") {
                    let semi = self.find_semi(k, limit);
                    self.scan(k + 1, semi, Mode::Expr);
                    k = semi;
                }
                end_idx = k.min(limit - 1);
            }
            "macro_rules" => {
                let mut k = j + 1;
                if self.is_punct(k, "!") {
                    k += 1;
                }
                if self.is_ident(k) {
                    self.set(k, Role::Ident);
                    k += 1;
                }
                if k < limit && matches!(self.text(k), "{" | "(" | "[") {
                    let c = self.close_of(k);
                    self.scan(k + 1, c, Mode::Expr);
                    end_idx = c;
                } else {
                    return None;
                }
                let _ = &mut item;
                return Some(end_idx + 1);
            }
            _ => {
                // Not an item; restore pending attrs.
                self.pending_attrs = item.attrs;
                return None;
            }
        }
        item.end = self.toks[end_idx.min(self.toks.len() - 1)].end;
        self.items.push(item);
        Some(end_idx + 1)
    }

    fn find_brace(&self, mut k: usize, limit: usize) -> usize {
        let mut depth = 0i32;
        while k < limit {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "<" => depth += 1,
                    ">" => depth -= 1,
                    ">>" => depth -= 2,
                    "{" if depth <= 0 => return k,
                    ";" if depth <= 0 => return k,
                    "(" | "[" => k = self.close_of(k),
                    _ => {}
                }
            }
            k += 1;
        }
        limit
    }

    fn find_semi(&self, mut k: usize, limit: usize) -> usize {
        while k < limit {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    ";" => return k,
                    "(" | "[" | "{" => k = self.close_of(k),
                    _ => {}
                }
            }
            k += 1;
        }
        limit
    }

    fn find_eq(&self, mut k: usize, limit: usize) -> usize {
        while k < limit {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "=" => return k,
                    "(" | "[" | "{" => k = self.close_of(k),
                    "<" => k = self.close_angle(k, limit),
                    _ => {}
                }
            }
            k += 1;
        }
        limit
    }

    /// Parse generic parameters `<...>` at k, if present.
    fn parse_generics(&mut self, k: usize, limit: usize) -> usize {
        if self.is_punct(k, "<") {
            let c = self.close_angle(k, limit);
            self.scan_type_list(k + 1, c);
            return c + 1;
        }
        k
    }

    fn parse_where(&mut self, k: usize, limit: usize) -> usize {
        if self.is_kw(k, "where") {
            let end = self.find_brace(k + 1, limit);
            self.scan_type_list(k + 1, end);
            return end;
        }
        k
    }

    /// Function parameters in [start, end).
    fn scan_params(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            // Attributes on params.
            if self.is_punct(i, "#") {
                i = self.parse_attribute(i);
                self.pending_attrs.clear();
                continue;
            }
            if self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            // Pattern until ':' at depth 0 (or ',' / end for self params).
            let pstart = i;
            let mut k = i;
            let mut found_colon = None;
            while k < end {
                if self.is_punct(k, ",") {
                    break;
                }
                if self.is_punct(k, ":") {
                    found_colon = Some(k);
                    break;
                }
                if self.is_punct(k, "(") || self.is_punct(k, "[") || self.is_punct(k, "{") {
                    k = self.close_of(k);
                }
                k += 1;
            }
            // Mark pattern identifiers.
            let pend = found_colon.unwrap_or(k.min(end));
            self.scan_pattern(pstart, pend);
            if let Some(c) = found_colon {
                let next = self.consume_type(c + 1, end);
                i = next.max(c + 1);
                // skip to comma
                while i < end && !self.is_punct(i, ",") {
                    i += 1;
                }
            } else {
                i = k;
            }
        }
    }

    /// Mark identifiers in a pattern (let/params/match arms).
    fn scan_pattern(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            let tok_kind = self.toks[i].kind;
            if tok_kind == Kind::Ident {
                let s = self.text(i);
                if KEYWORDS.contains(&s) {
                    i += 1;
                    continue;
                }
                // Struct pattern `Path::Name { fields }` or tuple-struct `Name(..)`
                if self.is_punct(i + 1, "::") {
                    // Path segment: last segment before `{` is a type identifier.
                    let mut k = i;
                    while self.is_ident(k) && self.is_punct(k + 1, "::") {
                        self.set(k, Role::Ident);
                        k += 2;
                    }
                    if self.is_ident(k) {
                        if self.is_punct(k + 1, "{") {
                            self.set(k, Role::TypeIdent);
                            let c = self.close_of(k + 1);
                            self.scan_struct_pattern_fields(k + 2, c);
                            i = c + 1;
                            continue;
                        }
                        self.set(k, Role::Ident);
                        i = k + 1;
                        continue;
                    }
                    i = k;
                    continue;
                }
                if self.is_punct(i + 1, "{") && s.chars().next().map_or(false, |c| c.is_uppercase()) {
                    self.set(i, Role::TypeIdent);
                    let c = self.close_of(i + 1);
                    self.scan_struct_pattern_fields(i + 2, c);
                    i = c + 1;
                    continue;
                }
                self.set(i, Role::Ident);
                i += 1;
                continue;
            }
            if tok_kind == Kind::Punct && matches!(self.text(i), "(" | "[") {
                let c = self.close_of(i);
                self.scan_pattern(i + 1, c);
                i = c + 1;
                continue;
            }
            if tok_kind == Kind::Punct && self.text(i) == "@" {
                i += 1;
                continue;
            }
            i += 1;
        }
    }

    fn scan_struct_pattern_fields(&mut self, start: usize, end: usize) {
        let mut i = start;
        let mut at_field = true;
        while i < end {
            if self.is_punct(i, ",") {
                at_field = true;
                i += 1;
                continue;
            }
            if at_field && self.is_ident(i) {
                if self.is_punct(i + 1, ":") {
                    self.set(i, Role::Field);
                    i += 2;
                    // value pattern until ','
                    let mut k = i;
                    while k < end && !self.is_punct(k, ",") {
                        if matches!(self.text(k), "(" | "[" | "{") {
                            k = self.close_of(k);
                        }
                        k += 1;
                    }
                    self.scan_pattern(i, k.min(end));
                    i = k;
                    at_field = false;
                    continue;
                }
                self.set(i, Role::Ident);
                i += 1;
                at_field = false;
                continue;
            }
            if self.is_kw(i, "ref") || self.is_kw(i, "mut") {
                i += 1;
                continue;
            }
            i += 1;
        }
    }

    fn scan_struct_fields(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_punct(i, "#") {
                i = self.parse_attribute(i);
                self.pending_attrs.clear();
                continue;
            }
            if self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            if matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment) {
                i += 1;
                continue;
            }
            // visibility
            if self.is_kw(i, "pub") {
                i += 1;
                if self.is_punct(i, "(") {
                    let c = self.close_of(i);
                    i = c + 1;
                }
                continue;
            }
            if self.is_ident(i) && self.is_punct(i + 1, ":") {
                self.set(i, Role::Field);
                let next = self.consume_type(i + 2, end);
                i = next.max(i + 2);
                continue;
            }
            i += 1;
        }
    }

    fn scan_tuple_fields(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_punct(i, "#") {
                i = self.parse_attribute(i);
                self.pending_attrs.clear();
                continue;
            }
            if self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            if self.is_kw(i, "pub") {
                i += 1;
                if self.is_punct(i, "(") {
                    i = self.close_of(i) + 1;
                }
                continue;
            }
            let next = self.consume_type(i, end);
            i = if next > i { next } else { i + 1 };
        }
    }

    /// Enum variants in [start, end); returns variant ranges.
    fn scan_enum_variants(&mut self, start: usize, end: usize) -> Vec<Range> {
        let mut out = Vec::new();
        let mut i = start;
        while i < end {
            if self.is_punct(i, "#") {
                i = self.parse_attribute(i);
                self.pending_attrs.clear();
                continue;
            }
            if self.is_punct(i, ",") || matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment) {
                i += 1;
                continue;
            }
            if self.is_kw(i, "pub") {
                i += 1;
                continue;
            }
            if self.is_ident(i) {
                let vstart = self.toks[i].start;
                let mut vend = self.toks[i].end;
                self.set(i, Role::Ident);
                let mut k = i + 1;
                if self.is_punct(k, "(") {
                    let c = self.close_of(k);
                    self.scan_tuple_fields(k + 1, c);
                    vend = self.toks[c].end;
                    k = c + 1;
                } else if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan_struct_fields(k + 1, c);
                    vend = self.toks[c].end;
                    k = c + 1;
                }
                if self.is_punct(k, "=") {
                    let mut m = k + 1;
                    while m < end && !self.is_punct(m, ",") {
                        if matches!(self.text(m), "(" | "[" | "{") {
                            m = self.close_of(m);
                        }
                        m += 1;
                    }
                    self.scan(k + 1, m.min(end), Mode::Expr);
                    if m > k + 1 {
                        vend = self.toks[(m - 1).min(end - 1)].end;
                    }
                    k = m;
                }
                out.push(vstart..vend);
                i = k;
                continue;
            }
            i += 1;
        }
        out
    }

    fn scan_items(&mut self, start: usize, end: usize, parent: Parent) {
        let saved = std::mem::take(&mut self.pending_attrs);
        let mut i = start;
        while i < end {
            if matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment) {
                i += 1;
                continue;
            }
            if self.is_punct(i, "#") {
                i = self.parse_attribute(i);
                continue;
            }
            if self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            match self.try_item(i, end, parent) {
                Some(next) => {
                    i = next.max(i + 1);
                    self.pending_attrs.clear();
                }
                None => {
                    // Unknown: skip a statement.
                    self.pending_attrs.clear();
                    let next = self.scan_statement(i, end);
                    i = next.max(i + 1);
                }
            }
        }
        self.pending_attrs = saved;
    }

    /// Scan one statement/expression in Stmts mode from i; returns index after.
    fn scan_statement(&mut self, start: usize, end: usize) -> usize {
        let mut i = start;
        let mut cond = false;
        let mut n = 0;
        while i < end && n < 1_000_000 {
            n += 1;
            let tok_kind = self.toks[i].kind;
            match tok_kind {
                Kind::Punct => {
                    let s = self.text(i);
                    match s {
                        ";" => return i + 1,
                        "{" => {
                            let c = self.close_of(i);
                            self.scan(i + 1, c, Mode::Stmts);
                            i = c + 1;
                            if cond {
                                cond = false;
                                // if/match block done; `else` may follow
                                if self.is_kw(i, "else") {
                                    continue;
                                }
                                return i;
                            }
                            // A block ends an expression statement unless an operator follows.
                            if i < end && (self.is_kw(i, "else") || self.is_punct(i, ".") || self.is_punct(i, "?")) {
                                continue;
                            }
                            return i;
                        }
                        "(" | "[" => {
                            let c = self.close_of(i);
                            self.scan(i + 1, c, Mode::Expr);
                            i = c + 1;
                        }
                        "|" | "||" => {
                            i = self.scan_closure(i, end);
                        }
                        "#" => {
                            i = self.parse_attribute(i);
                            self.pending_attrs.clear();
                        }
                        "." => {
                            i += 1;
                            if self.is_ident(i) {
                                self.set(i, Role::Field);
                                i += 1;
                                // method turbofish
                                if self.is_punct(i, "::") && self.is_punct(i + 1, "<") {
                                    let c = self.close_angle(i + 1, end);
                                    self.scan_type_list(i + 2, c);
                                    i = c + 1;
                                }
                            }
                        }
                        _ => i += 1,
                    }
                }
                Kind::Ident => {
                    let s = self.text(i);
                    match s {
                        "let" => {
                            i += 1;
                            let mut k = i;
                            let mut colon = None;
                            while k < end {
                                if self.is_punct(k, "=") || self.is_punct(k, ";") {
                                    break;
                                }
                                if self.is_punct(k, ":") {
                                    colon = Some(k);
                                    break;
                                }
                                if self.is_kw(k, "else") {
                                    break;
                                }
                                if matches!(self.text(k), "(" | "[" | "{") {
                                    k = self.close_of(k);
                                }
                                k += 1;
                            }
                            self.scan_pattern(i, k.min(end));
                            i = k;
                            if let Some(c) = colon {
                                i = self.consume_type(c + 1, end).max(c + 1);
                            }
                        }
                        "as" => {
                            i = self.consume_type(i + 1, end).max(i + 1);
                        }
                        "if" | "while" | "match" => {
                            cond = true;
                            i += 1;
                        }
                        "for" => {
                            // for pat in expr {
                            i += 1;
                            let mut k = i;
                            while k < end && !self.is_kw(k, "in") && !self.is_punct(k, "{") {
                                if matches!(self.text(k), "(" | "[") {
                                    k = self.close_of(k);
                                }
                                k += 1;
                            }
                            self.scan_pattern(i, k.min(end));
                            i = k + 1;
                            cond = true;
                        }
                        "unsafe" if self.is_punct(i + 1, "{") => {
                            let c = self.close_of(i + 1);
                            self.unsafe_blocks.push(self.toks[i].start..self.toks[c].end);
                            self.scan(i + 2, c, Mode::Stmts);
                            i = c + 1;
                            return i;
                        }
                        "fn" | "struct" | "enum" | "union" | "trait" | "impl" | "mod" | "use" | "type" | "const" | "static" | "pub" | "macro_rules" | "extern" => {
                            if let Some(next) = self.try_item(i, end, Parent::Fn) {
                                return next;
                            }
                            i += 1;
                        }
                        "async" | "move" => {
                            i += 1;
                        }
                        _ => {
                            i = self.scan_ident_expr(i, end, cond);
                        }
                    }
                }
                Kind::Lifetime => {
                    self.mark_lifetime(i);
                    i += 1;
                }
                _ => i += 1,
            }
        }
        i
    }

    /// Handle an identifier in expression position; returns index after.
    fn scan_ident_expr(&mut self, i: usize, end: usize, cond: bool) -> usize {
        let s = self.text(i);
        if KEYWORDS.contains(&s) {
            return i + 1;
        }
        // Macro invocation
        if self.is_punct(i + 1, "!") && i + 2 < end && matches!(self.text(i + 2), "(" | "[" | "{") {
            self.set(i, Role::Ident);
            let c = self.close_of(i + 2);
            self.scan(i + 3, c, Mode::Expr);
            return c + 1;
        }
        // Path: segments separated by `::`
        let mut k = i;
        loop {
            if !self.is_ident(k) {
                break;
            }
            if self.is_punct(k + 1, "::") {
                if self.is_punct(k + 2, "<") {
                    // turbofish
                    let c = self.close_angle(k + 2, end);
                    if self.is_punct(c + 1, "::") || self.is_punct(c + 1, "{") {
                        self.set(k, Role::TypeIdent);
                    } else {
                        self.set(k, Role::Ident);
                    }
                    self.scan_type_list(k + 3, c);
                    k = c + 1;
                    if self.is_punct(k, "::") {
                        k += 1;
                        continue;
                    }
                    break;
                }
                self.set(k, Role::Ident);
                k += 2;
                continue;
            }
            // Last segment.
            let first_upper = s_first_upper(self.text(k));
            if self.is_punct(k + 1, "{") && first_upper && !cond {
                self.set(k, Role::TypeIdent);
                let c = self.close_of(k + 1);
                self.scan_struct_expr_fields(k + 2, c);
                return c + 1;
            }
            self.set(k, Role::Ident);
            k += 1;
            break;
        }
        if self.is_punct(k, "{") && k > i + 1 && !cond {
            // `Path::Name {` handled above; `<...> {`
        }
        k.max(i + 1)
    }

    fn scan_struct_expr_fields(&mut self, start: usize, end: usize) {
        let mut i = start;
        let mut at_field = true;
        while i < end {
            if self.is_punct(i, ",") {
                at_field = true;
                i += 1;
                continue;
            }
            if self.is_punct(i, "..") {
                // base expression
                i += 1;
                let k = end;
                self.scan(i, k, Mode::Expr);
                return;
            }
            if at_field && self.is_ident(i) {
                if self.is_punct(i + 1, ":") {
                    self.set(i, Role::Field);
                    i += 2;
                    // value until ','
                    let mut k = i;
                    while k < end && !self.is_punct(k, ",") {
                        if matches!(self.text(k), "(" | "[" | "{") {
                            k = self.close_of(k);
                        }
                        k += 1;
                    }
                    self.scan(i, k.min(end), Mode::Expr);
                    i = k;
                    at_field = false;
                    continue;
                }
                self.set(i, Role::Ident);
                i += 1;
                at_field = false;
                continue;
            }
            if self.is_punct(i, "#") {
                i = self.parse_attribute(i);
                self.pending_attrs.clear();
                continue;
            }
            i += 1;
        }
    }

    /// Scan a closure starting at `|` or `||` at i; returns index after.
    fn scan_closure(&mut self, i: usize, end: usize) -> usize {
        // Determine closure start (include preceding `move` / `async`).
        let mut cstart_tok = i;
        if cstart_tok > 0 && (self.is_kw(cstart_tok - 1, "move") || self.is_kw(cstart_tok - 1, "async")) {
            cstart_tok -= 1;
            if cstart_tok > 0 && self.is_kw(cstart_tok - 1, "async") {
                cstart_tok -= 1;
            }
        }
        let mut k;
        if self.is_punct(i, "||") {
            k = i + 1;
        } else {
            // find closing `|`
            k = i + 1;
            let pstart = k;
            while k < end && !self.is_punct(k, "|") {
                if matches!(self.text(k), "(" | "[" | "{") {
                    k = self.close_of(k);
                }
                k += 1;
            }
            self.scan_params(pstart, k.min(end));
            k += 1;
        }
        // Return type
        if self.is_punct(k, "->") {
            k = self.consume_type(k + 1, end);
        }
        // Body
        let body_end;
        if self.is_punct(k, "{") {
            let c = self.close_of(k);
            self.scan(k + 1, c, Mode::Stmts);
            body_end = c;
            k = c + 1;
        } else {
            // expression until , ; ) ] } at depth 0
            let mut m = k;
            while m < end {
                if self.toks[m].kind == Kind::Punct {
                    let s = self.text(m);
                    if matches!(s, "," | ";" | ")" | "]" | "}") {
                        break;
                    }
                    if matches!(s, "(" | "[" | "{") {
                        let c = self.close_of(m);
                        self.scan(m + 1, c, Mode::Expr);
                        m = c + 1;
                        continue;
                    }
                    if s == "|" || s == "||" {
                        m = self.scan_closure(m, end);
                        continue;
                    }
                    if s == "." {
                        m += 1;
                        if self.is_ident(m) {
                            self.set(m, Role::Field);
                            m += 1;
                        }
                        continue;
                    }
                    m += 1;
                    continue;
                }
                if self.toks[m].kind == Kind::Ident {
                    let s = self.text(m);
                    if s == "as" {
                        m = self.consume_type(m + 1, end).max(m + 1);
                        continue;
                    }
                    m = self.scan_ident_expr(m, end, false);
                    continue;
                }
                m += 1;
            }
            body_end = m.saturating_sub(1).max(k);
            k = m;
        }
        let s = self.toks[cstart_tok].start;
        let e = self.toks[body_end.min(self.toks.len() - 1)].end;
        if e > s {
            self.closures.push(s..e);
        }
        k
    }

    /// Scan a token range in the given mode.
    fn scan(&mut self, start: usize, end: usize, mode: Mode) {
        match mode {
            Mode::Items => self.scan_items(start, end, Parent::Module),
            Mode::Stmts => {
                let mut i = start;
                while i < end {
                    if matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment) {
                        i += 1;
                        continue;
                    }
                    let next = self.scan_statement(i, end);
                    i = next.max(i + 1);
                }
            }
            Mode::Expr => {
                let mut i = start;
                while i < end {
                    let tok_kind = self.toks[i].kind;
                    match tok_kind {
                        Kind::Punct => {
                            let s = self.text(i);
                            match s {
                                "(" | "[" => {
                                    let c = self.close_of(i);
                                    self.scan(i + 1, c, Mode::Expr);
                                    i = c + 1;
                                }
                                "{" => {
                                    let c = self.close_of(i);
                                    self.scan(i + 1, c, Mode::Stmts);
                                    i = c + 1;
                                }
                                "|" | "||" => {
                                    i = self.scan_closure(i, end);
                                }
                                "." => {
                                    i += 1;
                                    if self.is_ident(i) {
                                        self.set(i, Role::Field);
                                        i += 1;
                                        if self.is_punct(i, "::") && self.is_punct(i + 1, "<") {
                                            let c = self.close_angle(i + 1, end);
                                            self.scan_type_list(i + 2, c);
                                            i = c + 1;
                                        }
                                    }
                                }
                                "#" => {
                                    i = self.parse_attribute(i);
                                    self.pending_attrs.clear();
                                }
                                _ => i += 1,
                            }
                        }
                        Kind::Ident => {
                            let s = self.text(i);
                            match s {
                                "as" => {
                                    i = self.consume_type(i + 1, end).max(i + 1);
                                }
                                "unsafe" if self.is_punct(i + 1, "{") => {
                                    let c = self.close_of(i + 1);
                                    self.unsafe_blocks.push(self.toks[i].start..self.toks[c].end);
                                    self.scan(i + 2, c, Mode::Stmts);
                                    i = c + 1;
                                }
                                "if" | "while" | "match" | "for" | "loop" | "let" => {
                                    // control flow inside expression: scan as statement
                                    i = self.scan_statement(i, end).max(i + 1);
                                }
                                _ => {
                                    i = self.scan_ident_expr(i, end, false);
                                }
                            }
                        }
                        _ => i += 1,
                    }
                }
            }
        }
    }
}

fn s_first_upper(s: &str) -> bool {
    s.chars().next().map_or(false, |c| c.is_uppercase())
}

struct Analysis {
    ctx_items: Vec<Item>,
    closures: Vec<Range>,
    unsafe_blocks: Vec<Range>,
    uses: Vec<Range>,
    attrs: Vec<Range>,
    comments: Vec<Range>,
    doc_comments: Vec<Range>,
    strings: Vec<Range>,
    identifiers: Vec<Range>,
    type_identifiers: Vec<Range>,
}

fn analyze(src: &str) -> Analysis {
    let toks = Lexer::new(src, Flavor::Rust).lex();
    let n = toks.len();
    let mut ctx = Ctx {
        src,
        toks,
        roles: vec![Role::Unknown; n],
        items: Vec::new(),
        closures: Vec::new(),
        unsafe_blocks: Vec::new(),
        uses: Vec::new(),
        attrs: Vec::new(),
        pending_attrs: Vec::new(),
    };
    if n > 0 {
        ctx.scan_items(0, n, Parent::Module);
    }
    let mut comments = Vec::new();
    let mut doc_comments = Vec::new();
    let mut strings = Vec::new();
    let mut identifiers = Vec::new();
    let mut type_identifiers = Vec::new();
    for (i, t) in ctx.toks.iter().enumerate() {
        match t.kind {
            Kind::LineComment => {
                let text = t.text(src);
                if text.starts_with("///") && !text.starts_with("////") {
                    doc_comments.push(t.start..t.end);
                } else {
                    comments.push(t.start..t.end);
                }
            }
            Kind::BlockComment => comments.push(t.start..t.end),
            Kind::Str => {
                for (s, e) in &t.content {
                    strings.push(*s..*e);
                }
            }
            Kind::Ident => {
                let text = t.text(src);
                if KEYWORDS.contains(&text) {
                    continue;
                }
                match ctx.roles[i] {
                    Role::TypeIdent => type_identifiers.push(t.start..t.end),
                    Role::Field | Role::Skip => {}
                    Role::Ident | Role::Unknown => {
                        if !PRIMITIVES.contains(&text) || ctx.roles[i] == Role::Ident {
                            identifiers.push(t.start..t.end);
                        } else {
                            identifiers.push(t.start..t.end);
                        }
                    }
                }
            }
            Kind::Lifetime => {
                // The identifier part of a label/lifetime.
                if t.end > t.start + 1 {
                    let name = &src[t.start + 1..t.end];
                    if name != "static" && name != "_" {
                        identifiers.push(t.start + 1..t.end);
                    }
                }
            }
            _ => {}
        }
    }
    Analysis {
        ctx_items: ctx.items,
        closures: ctx.closures,
        unsafe_blocks: ctx.unsafe_blocks,
        uses: ctx.uses,
        attrs: ctx.attrs,
        comments,
        doc_comments,
        strings,
        identifiers,
        type_identifiers,
    }
}

fn name_matches(item: &Item, pattern: Option<&regex::Regex>) -> bool {
    match pattern {
        None => true,
        Some(re) => item.name.as_deref().map_or(false, |n| re.is_match(n)),
    }
}

pub fn ranges(name: &str, pattern: Option<&regex::Regex>, src: &str) -> Vec<Range> {
    let a = analyze(src);
    let items = &a.ctx_items;
    let structs = |f: &dyn Fn(&Item) -> bool| -> Vec<Range> {
        items
            .iter()
            .filter(|it| it.kind == ItemKind::Struct && f(it))
            .map(|it| it.start..it.end)
            .collect()
    };
    let enums = |f: &dyn Fn(&Item) -> bool| -> Vec<Range> {
        items
            .iter()
            .filter(|it| it.kind == ItemKind::Enum && f(it))
            .map(|it| it.start..it.end)
            .collect()
    };
    let fns = |f: &dyn Fn(&Item) -> bool| -> Vec<Range> {
        items
            .iter()
            .filter(|it| it.kind == ItemKind::Fn && f(it))
            .map(|it| it.start..it.end)
            .collect()
    };
    match name {
        "comments" => a.comments,
        "doc-comments" => a.doc_comments,
        "uses" => a.uses,
        "strings" => a.strings,
        "attribute" => a.attrs,
        "struct" => structs(&|it| name_matches(it, pattern)),
        "priv-struct" => structs(&|it| it.vis.is_empty()),
        "pub-struct" => structs(&|it| it.vis == "pub"),
        "pub-crate-struct" => structs(&|it| it.vis == "pub(crate)"),
        "pub-self-struct" => structs(&|it| it.vis == "pub(self)"),
        "pub-super-struct" => structs(&|it| it.vis == "pub(super)"),
        "enum" => enums(&|it| name_matches(it, pattern)),
        "priv-enum" => enums(&|it| it.vis.is_empty()),
        "pub-enum" => enums(&|it| it.vis == "pub"),
        "pub-crate-enum" => enums(&|it| it.vis == "pub(crate)"),
        "pub-self-enum" => enums(&|it| it.vis == "pub(self)"),
        "pub-super-enum" => enums(&|it| it.vis == "pub(super)"),
        "enum-variant" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Enum)
            .flat_map(|it| it.variants.clone())
            .collect(),
        "fn" => fns(&|it| name_matches(it, pattern)),
        "impl-fn" => fns(&|it| it.parent == Parent::Impl),
        "priv-fn" => fns(&|it| it.vis.is_empty()),
        "pub-fn" => fns(&|it| it.vis == "pub"),
        "pub-crate-fn" => fns(&|it| it.vis == "pub(crate)"),
        "pub-self-fn" => fns(&|it| it.vis == "pub(self)"),
        "pub-super-fn" => fns(&|it| it.vis == "pub(super)"),
        "const-fn" => fns(&|it| it.quals.iter().any(|q| q == "const")),
        "async-fn" => fns(&|it| it.quals.iter().any(|q| q == "async")),
        "unsafe-fn" => fns(&|it| it.quals.iter().any(|q| q == "unsafe")),
        "extern-fn" => fns(&|it| it.quals.iter().any(|q| q == "extern")),
        "test-fn" => fns(&|it| it.attrs.iter().any(|at| at.contains("test"))),
        "trait" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Trait && name_matches(it, pattern))
            .map(|it| it.start..it.end)
            .collect(),
        "impl" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Impl)
            .map(|it| it.start..it.end)
            .collect(),
        "impl-type" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Impl && !it.has_for)
            .map(|it| it.start..it.end)
            .collect(),
        "impl-trait" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Impl && it.has_for)
            .map(|it| it.start..it.end)
            .collect(),
        "mod" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Mod && name_matches(it, pattern))
            .map(|it| it.start..it.end)
            .collect(),
        "mod-tests" => items
            .iter()
            .filter(|it| it.kind == ItemKind::Mod && it.name.as_deref() == Some("tests"))
            .map(|it| it.start..it.end)
            .collect(),
        "type-def" => items
            .iter()
            .filter(|it| matches!(it.kind, ItemKind::Struct | ItemKind::Enum | ItemKind::Union))
            .map(|it| it.start..it.end)
            .collect(),
        "identifier" => a.identifiers,
        "type-identifier" => a.type_identifiers,
        "closure" => a.closures,
        "unsafe" => {
            let mut out = a.unsafe_blocks.clone();
            for it in items {
                if it.quals.iter().any(|q| q == "unsafe") && matches!(it.kind, ItemKind::Fn | ItemKind::Impl | ItemKind::Trait) {
                    out.push(it.start..it.end);
                }
            }
            out
        }
        _ => Vec::new(),
    }
}
