//! Language support: Go.

use super::lexer::{matching_close, Flavor, Kind, Lexer, Token};
use super::Range;

struct Out {
    strings: Vec<Range>,
    imports: Vec<Range>,
    type_defs: Vec<Range>,
    type_aliases: Vec<Range>,
    structs: Vec<(Range, String)>,
    interfaces: Vec<(Range, String)>,
    consts: Vec<Range>,
    vars: Vec<Range>,
    funcs: Vec<(Range, String, bool)>, // (range, name, is_method)
    type_params: Vec<Range>,
    defers: Vec<Range>,
    selects: Vec<Range>,
    gos: Vec<Range>,
    switches: Vec<Range>,
    labeled: Vec<Range>,
    gotos: Vec<Range>,
    struct_tags: Vec<Range>,
    expressions: Vec<Range>,
    /// String tokens that must not count as strings (imports, struct tags).
    excluded_strings: Vec<usize>,
}

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    out: Out,
}

const STMT_END_KEYWORDS: &[&str] = &["break", "continue", "fallthrough", "return"];

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }

    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }

    fn is_kw(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && self.text(i) == s
    }

    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident
    }

    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }

    fn is_comment(&self, i: usize) -> bool {
        i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment)
    }

    /// Line number helper: whether there is a newline between tokens i-1 and i.
    fn newline_before(&self, i: usize) -> bool {
        if i == 0 || i >= self.toks.len() {
            return true;
        }
        self.src[self.toks[i - 1].end..self.toks[i].start].contains('\n')
    }

    fn range(&self, start: usize, end_inclusive: usize) -> Range {
        let e = end_inclusive.min(self.toks.len() - 1);
        self.toks[start].start..self.toks[e].end
    }

    /// Find the end (exclusive token index) of the statement starting at i within [i, limit).
    /// Applies Go's automatic semicolon rule at bracket depth 0.
    fn statement_end(&self, i: usize, limit: usize) -> usize {
        let mut k = i;
        while k < limit {
            if self.is_comment(k) {
                // A comment ending a line acts like the newline.
                if k + 1 < limit && self.newline_before(k + 1) && k > i && self.ends_statement(k - 1) {
                    return k;
                }
                k += 1;
                continue;
            }
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    ";" => return k,
                    "(" | "[" | "{" => {
                        k = self.close_of(k);
                    }
                    _ => {}
                }
            }
            // Automatic semicolon: newline after this token and token ends a statement.
            if k + 1 < limit && self.newline_before(k + 1) && self.ends_statement(k) {
                return k + 1;
            }
            k += 1;
        }
        limit
    }

    fn ends_statement(&self, k: usize) -> bool {
        let t = &self.toks[k];
        match t.kind {
            Kind::Ident => {
                let s = t.text(self.src);
                !matches!(s, "func" | "if" | "for" | "switch" | "select" | "else" | "go" | "defer" | "case" | "default" | "var" | "const" | "type" | "import" | "package" | "range" | "chan" | "map" | "struct" | "interface" | "goto")
                    || STMT_END_KEYWORDS.contains(&s)
            }
            Kind::Number | Kind::Str | Kind::Char => true,
            Kind::Punct => matches!(t.text(self.src), ")" | "]" | "}" | "++" | "--"),
            _ => false,
        }
    }

    // ----- top level -----

    fn scan_top(&mut self) {
        let n = self.toks.len();
        let mut i = 0;
        while i < n {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            if self.is_kw(i, "package") {
                i = self.statement_end(i, n).max(i + 1);
                continue;
            }
            if self.is_kw(i, "import") {
                i = self.scan_import(i);
                continue;
            }
            if self.is_kw(i, "type") {
                i = self.scan_type_decl(i, n);
                continue;
            }
            if self.is_kw(i, "const") || self.is_kw(i, "var") {
                i = self.scan_const_var(i, n);
                continue;
            }
            if self.is_kw(i, "func") {
                i = self.scan_func_decl(i, n);
                continue;
            }
            i = self.statement_end(i, n).max(i + 1);
        }
    }

    fn scan_import(&mut self, i: usize) -> usize {
        let mut k = i + 1;
        if self.is_punct(k, "(") {
            let c = self.close_of(k);
            let mut m = k + 1;
            while m < c {
                if self.toks[m].kind == Kind::Str {
                    self.out.imports.push(self.toks[m].start..self.toks[m].end);
                    self.out.excluded_strings.push(m);
                }
                m += 1;
            }
            return c + 1;
        }
        while k < self.toks.len() && !self.newline_before(k) || k == i + 1 {
            if k >= self.toks.len() {
                break;
            }
            if self.toks[k].kind == Kind::Str {
                self.out.imports.push(self.toks[k].start..self.toks[k].end);
                self.out.excluded_strings.push(k);
                return k + 1;
            }
            k += 1;
        }
        k.max(i + 1)
    }

    /// `type X ...` or `type ( ... )`
    fn scan_type_decl(&mut self, i: usize, limit: usize) -> usize {
        let k = i + 1;
        if self.is_punct(k, "(") {
            let c = self.close_of(k);
            let mut m = k + 1;
            while m < c {
                if self.is_comment(m) || self.is_punct(m, ";") {
                    m += 1;
                    continue;
                }
                let (end, _) = self.scan_type_spec(m, c, None);
                m = end.max(m + 1);
            }
            self.out.type_defs.push(self.range(i, c));
            return c + 1;
        }
        let (end, _) = self.scan_type_spec(k, limit, Some(i));
        end.max(i + 1)
    }

    /// Type spec `Name[TypeParams] [=] Type`; returns (end exclusive, name).
    /// `decl_start`: token index of `type` keyword for a single declaration.
    fn scan_type_spec(&mut self, i: usize, limit: usize, decl_start: Option<usize>) -> (usize, String) {
        if !self.is_ident(i) {
            return (i + 1, String::new());
        }
        let name = self.text(i).to_owned();
        let mut k = i + 1;
        if self.is_punct(k, "[") {
            // Type parameters (or array type for alias? `type A [3]int` has no name before '[').
            let c = self.close_of(k);
            // Heuristic: type params if content starts with ident followed by ident/constraint.
            if self.is_ident(k + 1) && !(self.is_punct(k + 2, "]")) {
                self.scan_type_params(k + 1, c);
                k = c + 1;
            }
        }
        let is_alias = self.is_punct(k, "=");
        if is_alias {
            k += 1;
        }
        let type_start = k;
        let end = self.consume_type(k, limit);
        let spec_range = self.toks[i].start..self.toks[end.saturating_sub(1).max(i)].end;
        let decl_range = match decl_start {
            Some(d) => self.toks[d].start..spec_range.end,
            None => spec_range.clone(),
        };
        if decl_start.is_some() {
            self.out.type_defs.push(decl_range.clone());
        }
        if is_alias {
            self.out.type_aliases.push(spec_range.clone());
        } else if self.is_kw(type_start, "struct") {
            self.out.structs.push((decl_range.clone(), name.clone()));
        } else if self.is_kw(type_start, "interface") {
            self.out.interfaces.push((decl_range.clone(), name.clone()));
        }
        (end, name)
    }

    fn scan_type_params(&mut self, start: usize, end: usize) {
        // Comma separated: `K comparable, V any` or `K, V any`
        let mut i = start;
        let mut group_start = i;
        while i < end {
            if self.is_punct(i, ",") {
                // A declaration ends at a comma only if a constraint was given in this group.
                // Determine: group has ident ident or ident type.
                let decl_has_constraint = (group_start + 1 < i) && !self.is_punct(group_start + 1, ",");
                if decl_has_constraint {
                    self.out.type_params.push(self.range(group_start, i - 1));
                    group_start = i + 1;
                }
                i += 1;
                continue;
            }
            if self.is_punct(i, "(") || self.is_punct(i, "[") || self.is_punct(i, "{") {
                i = self.close_of(i);
            }
            i += 1;
        }
        if group_start < end {
            self.out.type_params.push(self.range(group_start, end - 1));
        }
    }

    /// Consume a type starting at i; returns end (exclusive).
    fn consume_type(&mut self, mut i: usize, limit: usize) -> usize {
        let mut guard = 0;
        while i < limit && guard < 100000 {
            guard += 1;
            if self.toks[i].kind == Kind::Punct {
                match self.text(i) {
                    "*" | "[" => {
                        if self.text(i) == "[" {
                            let c = self.close_of(i);
                            i = c + 1;
                        } else {
                            i += 1;
                        }
                        continue;
                    }
                    "(" => {
                        let c = self.close_of(i);
                        return c + 1;
                    }
                    "<-" => {
                        i += 1;
                        continue;
                    }
                    _ => return i,
                }
            }
            if self.toks[i].kind == Kind::Ident {
                match self.text(i) {
                    "struct" => {
                        if self.is_punct(i + 1, "{") {
                            let c = self.close_of(i + 1);
                            self.scan_struct_body(i + 2, c);
                            return c + 1;
                        }
                        return i + 1;
                    }
                    "interface" => {
                        if self.is_punct(i + 1, "{") {
                            let c = self.close_of(i + 1);
                            return c + 1;
                        }
                        return i + 1;
                    }
                    "map" => {
                        i += 1;
                        if self.is_punct(i, "[") {
                            let c = self.close_of(i);
                            i = c + 1;
                        }
                        continue;
                    }
                    "chan" => {
                        i += 1;
                        if self.is_punct(i, "<-") {
                            i += 1;
                        }
                        continue;
                    }
                    "func" => {
                        i += 1;
                        if self.is_punct(i, "(") {
                            i = self.close_of(i) + 1;
                        }
                        // result
                        if self.is_punct(i, "(") {
                            i = self.close_of(i) + 1;
                            return i;
                        }
                        if i < limit && (self.toks[i].kind == Kind::Ident || self.is_punct(i, "*") || self.is_punct(i, "[")) && !self.newline_before(i) {
                            return self.consume_type(i, limit);
                        }
                        return i;
                    }
                    _ => {
                        // qualified name a.B, generic instantiation T[int]
                        i += 1;
                        while self.is_punct(i, ".") && self.is_ident(i + 1) {
                            i += 2;
                        }
                        if self.is_punct(i, "[") && !self.newline_before(i) {
                            let c = self.close_of(i);
                            i = c + 1;
                        }
                        return i;
                    }
                }
            }
            return i;
        }
        i
    }

    fn scan_struct_body(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            // Field line: names, type, optional tag — ends at newline/;
            let fe = self.statement_end(i, end);
            // Tag is a trailing string token.
            let mut last = fe;
            while last > i && self.is_comment(last - 1) {
                last -= 1;
            }
            if last > i && self.toks[last - 1].kind == Kind::Str {
                let t = &self.toks[last - 1];
                self.out.struct_tags.push(t.start..t.end);
                self.out.excluded_strings.push(last - 1);
            }
            i = fe.max(i + 1);
        }
    }

    fn scan_const_var(&mut self, i: usize, limit: usize) -> usize {
        let is_const = self.is_kw(i, "const");
        let k = i + 1;
        if self.is_punct(k, "(") {
            let c = self.close_of(k);
            let mut m = k + 1;
            while m < c {
                if self.is_comment(m) || self.is_punct(m, ";") {
                    m += 1;
                    continue;
                }
                let e = self.statement_end(m, c);
                let e = e.max(m + 1);
                self.scan_spec(m, e, is_const);
                m = e;
            }
            return c + 1;
        }
        let e = self.statement_end(k, limit).max(k + 1);
        self.scan_spec(k, e, is_const);
        e
    }

    /// A const/var spec in [start, end): `names [Type] [= exprs]`.
    fn scan_spec(&mut self, start: usize, end: usize, is_const: bool) {
        let mut e = end;
        while e > start && (self.is_comment(e - 1) || self.is_punct(e - 1, ";")) {
            e -= 1;
        }
        if e <= start {
            return;
        }
        let r = self.range(start, e - 1);
        if is_const {
            self.out.consts.push(r);
        } else {
            self.out.vars.push(r);
        }
        // Expressions after '='.
        let mut k = start;
        while k < e && !self.is_punct(k, "=") {
            if matches!(self.text(k), "(" | "[" | "{") {
                k = self.close_of(k);
            }
            k += 1;
        }
        if k < e {
            self.scan_expr_list(k + 1, e);
        }
    }

    fn scan_func_decl(&mut self, i: usize, limit: usize) -> usize {
        let mut k = i + 1;
        let mut is_method = false;
        if self.is_punct(k, "(") {
            // receiver
            is_method = true;
            k = self.close_of(k) + 1;
        }
        let mut name = String::new();
        if self.is_ident(k) {
            name = self.text(k).to_owned();
            k += 1;
        }
        if self.is_punct(k, "[") {
            let c = self.close_of(k);
            self.scan_type_params(k + 1, c);
            k = c + 1;
        }
        if self.is_punct(k, "(") {
            k = self.close_of(k) + 1;
        }
        // result
        if self.is_punct(k, "(") {
            k = self.close_of(k) + 1;
        } else if k < limit && !self.is_punct(k, "{") && !self.newline_before(k) {
            k = self.consume_type(k, limit).max(k);
        }
        let end;
        if self.is_punct(k, "{") {
            let c = self.close_of(k);
            self.scan_block(k + 1, c);
            end = c;
        } else {
            end = k.saturating_sub(1).max(i);
        }
        self.out.funcs.push((self.range(i, end), name, is_method));
        end + 1
    }

    // ----- statements -----

    fn scan_block(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            let next = self.scan_statement(i, end);
            i = next.max(i + 1);
        }
    }

    /// Scan one statement at i within [i, limit); returns index after it.
    fn scan_statement(&mut self, i: usize, limit: usize) -> usize {
        let t = &self.toks[i];
        if t.kind == Kind::Ident {
            let s = self.text(i);
            match s {
                "var" | "const" => return self.scan_const_var(i, limit),
                "type" => return self.scan_type_decl(i, limit),
                "defer" | "go" => {
                    let e = self.statement_end(i + 1, limit).max(i + 1);
                    let r = self.range(i, e - 1);
                    if s == "defer" {
                        self.out.defers.push(r);
                    } else {
                        self.out.gos.push(r);
                    }
                    self.scan_expr_list(i + 1, e);
                    return e;
                }
                "return" => {
                    let e = self.statement_end(i, limit).max(i + 1);
                    self.scan_expr_list(i + 1, e);
                    return e;
                }
                "goto" => {
                    let e = self.statement_end(i, limit).max(i + 1);
                    self.out.gotos.push(self.range(i, e - 1));
                    return e;
                }
                "break" | "continue" | "fallthrough" => {
                    return self.statement_end(i, limit).max(i + 1);
                }
                "if" => return self.scan_if(i, limit),
                "for" => return self.scan_for(i, limit),
                "switch" => return self.scan_switch(i, limit),
                "select" => {
                    let mut k = i + 1;
                    if self.is_punct(k, "{") {
                        let c = self.close_of(k);
                        self.out.selects.push(self.range(i, c));
                        self.scan_case_block(k + 1, c);
                        k = c + 1;
                    }
                    return k;
                }
                "func" if self.is_punct(i + 1, "(") || self.is_ident(i + 1) => {
                    // func literal expression statement or nested decl
                }
                _ => {
                    // Labeled statement: ident ':' at statement start
                    if self.is_punct(i + 1, ":") && !self.is_punct(i + 1, ":=") {
                        let mut k = i + 2;
                        while k < limit && (self.is_comment(k) || self.is_punct(k, ";")) {
                            k += 1;
                        }
                        let e = if k < limit { self.scan_statement(k, limit) } else { k };
                        let end_tok = e.saturating_sub(1).max(i + 1);
                        self.out.labeled.push(self.range(i, end_tok));
                        return e.max(i + 2);
                    }
                }
            }
        }
        if self.is_punct(i, "{") {
            let c = self.close_of(i);
            self.scan_block(i + 1, c);
            return c + 1;
        }
        // Simple statement.
        let e = self.statement_end(i, limit).max(i + 1);
        self.scan_simple(i, e);
        e
    }

    /// Simple statement in [start, end): assignment / expression / send / inc-dec.
    fn scan_simple(&mut self, start: usize, end: usize) {
        let mut e = end;
        while e > start && (self.is_comment(e - 1) || self.is_punct(e - 1, ";")) {
            e -= 1;
        }
        if e <= start {
            return;
        }
        // Split on assignment operators at depth 0.
        let mut k = start;
        let mut segments: Vec<(usize, usize)> = Vec::new();
        let mut seg_start = start;
        while k < e {
            if self.toks[k].kind == Kind::Punct {
                let s = self.text(k);
                match s {
                    "(" | "[" | "{" => {
                        k = self.close_of(k);
                    }
                    "=" | ":=" | "+=" | "-=" | "*=" | "/=" | "%=" | "&=" | "|=" | "^=" | "<<=" | ">>=" | "&^=" | "<-" if k > seg_start || s == "<-" => {
                        if s == "<-" {
                            // send statement only if there is a left operand
                            if k == seg_start {
                                k += 1;
                                continue;
                            }
                        }
                        segments.push((seg_start, k));
                        seg_start = k + 1;
                    }
                    "++" | "--" => {
                        segments.push((seg_start, k));
                        seg_start = k + 1;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
        if seg_start < e {
            segments.push((seg_start, e));
        }
        for (s, en) in segments {
            self.scan_expr_list(s, en);
        }
    }

    /// Comma separated expressions in [start, end); records each as an expression.
    fn scan_expr_list(&mut self, start: usize, end: usize) {
        let mut e = end;
        while e > start && (self.is_comment(e - 1) || self.is_punct(e - 1, ";")) {
            e -= 1;
        }
        let mut k = start;
        let mut item_start = start;
        while k < e {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "(" | "[" | "{" => {
                        let c = self.close_of(k);
                        // func literal bodies contain statements; scan them for nested
                        // statements (their expressions are inside the outer expression).
                        if self.text(k) == "{" && k > 0 && self.is_func_literal_body(k) {
                            self.scan_block(k + 1, c);
                        }
                        k = c + 1;
                        continue;
                    }
                    "," => {
                        self.push_expr(item_start, k);
                        item_start = k + 1;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
        self.push_expr(item_start, e);
    }

    fn is_func_literal_body(&self, brace: usize) -> bool {
        // `func (...) [result] {` — search back for `func` at this depth.
        let mut k = brace;
        let mut n = 0;
        while k > 0 && n < 50 {
            k -= 1;
            n += 1;
            if self.is_kw(k, "func") {
                return true;
            }
            if self.is_punct(k, ")") {
                // skip param list
                let mut depth = 0;
                while k > 0 {
                    if self.is_punct(k, ")") {
                        depth += 1;
                    } else if self.is_punct(k, "(") {
                        depth -= 1;
                        if depth == 0 {
                            break;
                        }
                    }
                    k -= 1;
                }
                continue;
            }
            if self.toks[k].kind == Kind::Punct && !matches!(self.text(k), "*" | "." | "[" | "]") {
                return false;
            }
        }
        false
    }

    fn push_expr(&mut self, start: usize, end: usize) {
        let mut s = start;
        let mut e = end;
        while s < e && (self.is_comment(s) || self.is_punct(s, ";")) {
            s += 1;
        }
        while e > s && (self.is_comment(e - 1) || self.is_punct(e - 1, ";")) {
            e -= 1;
        }
        if s < e {
            // A lone `...` after an expression is part of it; a trailing type in a
            // declaration is not an expression — callers avoid passing those.
            self.out.expressions.push(self.range(s, e - 1));
            // Nested statements inside func literals are handled in scan_expr_list.
        }
    }

    fn find_block_brace(&self, start: usize, limit: usize) -> usize {
        // Find the `{` that opens the statement block (depth 0, not a composite literal).
        let mut k = start;
        while k < limit {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "(" | "[" => {
                        k = self.close_of(k);
                    }
                    "{" => {
                        // Composite literal `T{` directly after an identifier/`]`/`.`? In
                        // headers tree-sitter requires parens; assume block.
                        return k;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
        limit
    }

    /// Header statements split by ';' in [start, end): each is a simple statement or expression.
    fn scan_header(&mut self, start: usize, end: usize) {
        let mut k = start;
        let mut seg = start;
        while k < end {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "(" | "[" | "{" => k = self.close_of(k),
                    ";" => {
                        self.scan_header_part(seg, k);
                        seg = k + 1;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
        self.scan_header_part(seg, end);
    }

    fn scan_header_part(&mut self, start: usize, end: usize) {
        if start >= end {
            return;
        }
        // range clause
        let mut k = start;
        while k < end {
            if self.is_kw(k, "range") {
                if k > start {
                    // left side: expression list before ':=' or '='
                    let mut m = start;
                    while m < k && !self.is_punct(m, ":=") && !self.is_punct(m, "=") {
                        m += 1;
                    }
                    self.scan_expr_list(start, m);
                }
                self.scan_expr_list(k + 1, end);
                return;
            }
            if matches!(self.text(k), "(" | "[" | "{") {
                k = self.close_of(k);
            }
            k += 1;
        }
        // type switch `x := v.(type)` → `x`, `v`
        let mut m = start;
        while m < end {
            if self.is_punct(m, ".") && self.is_punct(m + 1, "(") && self.is_kw(m + 2, "type") {
                // left part
                let mut a = start;
                while a < end && !self.is_punct(a, ":=") {
                    a += 1;
                }
                if a < end {
                    self.scan_expr_list(start, a);
                    self.scan_expr_list(a + 1, m);
                } else {
                    self.scan_expr_list(start, m);
                }
                return;
            }
            if matches!(self.text(m), "(" | "[" | "{") {
                m = self.close_of(m);
            }
            m += 1;
        }
        self.scan_simple(start, end);
    }

    fn scan_if(&mut self, i: usize, limit: usize) -> usize {
        let brace = self.find_block_brace(i + 1, limit);
        if brace >= limit {
            return i + 1;
        }
        self.scan_header(i + 1, brace);
        let c = self.close_of(brace);
        self.scan_block(brace + 1, c);
        let mut k = c + 1;
        if self.is_kw(k, "else") {
            k += 1;
            if self.is_kw(k, "if") {
                return self.scan_if(k, limit);
            }
            if self.is_punct(k, "{") {
                let c2 = self.close_of(k);
                self.scan_block(k + 1, c2);
                return c2 + 1;
            }
        }
        k
    }

    fn scan_for(&mut self, i: usize, limit: usize) -> usize {
        let brace = self.find_block_brace(i + 1, limit);
        if brace >= limit {
            return i + 1;
        }
        self.scan_header(i + 1, brace);
        let c = self.close_of(brace);
        self.scan_block(brace + 1, c);
        c + 1
    }

    fn scan_switch(&mut self, i: usize, limit: usize) -> usize {
        let brace = self.find_block_brace(i + 1, limit);
        if brace >= limit {
            return i + 1;
        }
        // Type switch?
        let mut is_type_switch = false;
        let mut m = i + 1;
        while m < brace {
            if self.is_punct(m, ".") && self.is_punct(m + 1, "(") && self.is_kw(m + 2, "type") {
                is_type_switch = true;
                break;
            }
            if matches!(self.text(m), "(" | "[") {
                m = self.close_of(m);
            }
            m += 1;
        }
        self.scan_header(i + 1, brace);
        let c = self.close_of(brace);
        if !is_type_switch {
            self.out.switches.push(self.range(i, c));
        }
        self.scan_case_block(brace + 1, c);
        c + 1
    }

    /// Body of switch/select: `case ...:` / `default:` clauses with statements.
    fn scan_case_block(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            if self.is_kw(i, "case") {
                // expressions until ':' at depth 0
                let mut k = i + 1;
                while k < end && !self.is_punct(k, ":") {
                    if matches!(self.text(k), "(" | "[" | "{") {
                        k = self.close_of(k);
                    }
                    k += 1;
                }
                // Could be a send/receive statement in select: `case v := <-ch:` / `case ch <- v:`
                let mut is_stmt = false;
                for m in i + 1..k {
                    if self.is_punct(m, ":=") || self.is_punct(m, "=") || self.is_punct(m, "<-") && m > i + 1 {
                        is_stmt = true;
                        break;
                    }
                }
                if is_stmt {
                    self.scan_simple(i + 1, k);
                } else {
                    self.scan_expr_list(i + 1, k);
                }
                i = k + 1;
                continue;
            }
            if self.is_kw(i, "default") {
                i += 1;
                if self.is_punct(i, ":") {
                    i += 1;
                }
                continue;
            }
            let next = self.scan_statement(i, end);
            i = next.max(i + 1);
        }
    }
}

pub fn ranges(name: &str, pattern: Option<&regex::Regex>, src: &str) -> Vec<Range> {
    let toks = Lexer::new(src, Flavor::Go).lex();
    if toks.is_empty() {
        return Vec::new();
    }
    let mut ctx = Ctx {
        src,
        toks,
        out: Out {
            strings: Vec::new(),
            imports: Vec::new(),
            type_defs: Vec::new(),
            type_aliases: Vec::new(),
            structs: Vec::new(),
            interfaces: Vec::new(),
            consts: Vec::new(),
            vars: Vec::new(),
            funcs: Vec::new(),
            type_params: Vec::new(),
            defers: Vec::new(),
            selects: Vec::new(),
            gos: Vec::new(),
            switches: Vec::new(),
            labeled: Vec::new(),
            gotos: Vec::new(),
            struct_tags: Vec::new(),
            expressions: Vec::new(),
            excluded_strings: Vec::new(),
        },
    };
    ctx.scan_top();
    let matches_name = |n: &str| pattern.map_or(true, |re| re.is_match(n));
    match name {
        "comments" => ctx
            .toks
            .iter()
            .filter(|t| matches!(t.kind, Kind::LineComment | Kind::BlockComment))
            .map(|t| t.start..t.end)
            .collect(),
        "strings" => {
            let excluded = &ctx.out.excluded_strings;
            let mut out = Vec::new();
            for (i, t) in ctx.toks.iter().enumerate() {
                if t.kind == Kind::Str && !excluded.contains(&i) {
                    for (s, e) in &t.content {
                        out.push(*s..*e);
                    }
                }
            }
            out
        }
        "imports" => ctx.out.imports,
        "expression" => ctx.out.expressions,
        "type-def" => ctx.out.type_defs,
        "type-alias" => ctx.out.type_aliases,
        "struct" => ctx
            .out
            .structs
            .into_iter()
            .filter(|(_, n)| matches_name(n))
            .map(|(r, _)| r)
            .collect(),
        "interface" => ctx
            .out
            .interfaces
            .into_iter()
            .filter(|(_, n)| matches_name(n))
            .map(|(r, _)| r)
            .collect(),
        "const" => ctx.out.consts,
        "var" => ctx.out.vars,
        "func" => ctx
            .out
            .funcs
            .into_iter()
            .filter(|(_, n, _)| matches_name(n))
            .map(|(r, _, _)| r)
            .collect(),
        "method" => ctx
            .out
            .funcs
            .into_iter()
            .filter(|(_, _, m)| *m)
            .map(|(r, _, _)| r)
            .collect(),
        "free-func" => ctx
            .out
            .funcs
            .into_iter()
            .filter(|(_, _, m)| !*m)
            .map(|(r, _, _)| r)
            .collect(),
        "init-func" => ctx
            .out
            .funcs
            .into_iter()
            .filter(|(_, n, m)| !*m && n == "init")
            .map(|(r, _, _)| r)
            .collect(),
        "type-params" => ctx.out.type_params,
        "defer" => ctx.out.defers,
        "select" => ctx.out.selects,
        "go" => ctx.out.gos,
        "switch" => ctx.out.switches,
        "labeled" => ctx.out.labeled,
        "goto" => ctx.out.gotos,
        "struct-tags" => ctx.out.struct_tags,
        _ => Vec::new(),
    }
}
