//! Language support: TypeScript.

use super::lexer::{matching_close, Flavor, Kind, Lexer, Token};
use super::Range;

#[derive(Default)]
struct Out {
    imports: Vec<Range>,
    functions: Vec<(Range, bool)>, // (range, is_async)
    methods: Vec<(Range, bool)>,   // (range, is_constructor)
    classes: Vec<Range>,
    enums: Vec<Range>,
    interfaces: Vec<Range>,
    tries: Vec<Range>,
    var_decls: Vec<Range>,
    lets: Vec<Range>,
    consts: Vec<Range>,
    vars: Vec<Range>,
    type_params: Vec<Range>,
    type_aliases: Vec<Range>,
    namespaces: Vec<Range>,
    exports: Vec<Range>,
}

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    out: Out,
}

const MODIFIERS: &[&str] = &[
    "public", "private", "protected", "static", "readonly", "abstract", "override", "declare",
    "async", "get", "set", "accessor",
];

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }
    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }
    fn is_kw(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && self.text(i) == s
    }
    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident
    }
    fn is_comment(&self, i: usize) -> bool {
        i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment)
    }
    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }
    fn newline_before(&self, i: usize) -> bool {
        if i == 0 || i >= self.toks.len() {
            return true;
        }
        self.src[self.toks[i - 1].end..self.toks[i].start].contains('\n')
    }
    fn range(&self, start: usize, end_inclusive: usize) -> Range {
        let e = end_inclusive.min(self.toks.len() - 1);
        self.toks[start].start..self.toks[e].end
    }

    /// Find matching `>` for `<` at i, limited to [i, limit].
    fn close_angle(&self, open: usize, limit: usize) -> usize {
        let mut depth = 0i32;
        let mut i = open;
        let limit = (limit + 1).min(self.toks.len());
        while i < limit {
            if self.toks[i].kind == Kind::Punct {
                match self.text(i) {
                    "<" => depth += 1,
                    ">" => {
                        depth -= 1;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    ">>" => {
                        depth -= 2;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    ">>>" => {
                        depth -= 3;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    "(" | "[" | "{" => i = self.close_of(i),
                    ";" => return i,
                    _ => {}
                }
            }
            i += 1;
        }
        limit.saturating_sub(1).max(open)
    }

    /// Statement end (exclusive) starting at i, honoring `;` and a simple ASI rule.
    fn statement_end(&self, i: usize, limit: usize) -> usize {
        let mut k = i;
        while k < limit {
            if self.is_comment(k) {
                k += 1;
                continue;
            }
            if self.toks[k].kind == Kind::Punct {
