cat > /workspace/src/langs/typescript.rs <<'EOF'
//! Language support: TypeScript.

use super::lexer::{matching_close, Flavor, Kind, Lexer, Token};
use super::Range;

#[derive(Default)]
struct Out {
    imports: Vec<Range>,
    functions: Vec<(Range, bool)>, // (range, is_async)
    methods: Vec<(Range, bool)>,   // (range, is_constructor)
    classes: Vec<Range>,
    enums: Vec<Range>,
    interfaces: Vec<Range>,
    tries: Vec<Range>,
    var_decls: Vec<Range>,
    lets: Vec<Range>,
    consts: Vec<Range>,
    vars: Vec<Range>,
    type_params: Vec<Range>,
    type_aliases: Vec<Range>,
    namespaces: Vec<Range>,
    exports: Vec<Range>,
}

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    out: Out,
}

const MODIFIERS: &[&str] = &[
    "public", "private", "protected", "static", "readonly", "abstract", "override", "declare",
    "async", "get", "set", "accessor",
];

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }
    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }
    fn is_kw(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && self.text(i) == s
    }
    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident
    }
    fn is_comment(&self, i: usize) -> bool {
        i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment)
    }
    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }
    fn newline_before(&self, i: usize) -> bool {
        if i == 0 || i >= self.toks.len() {
            return true;
        }
        self.src[self.toks[i - 1].end..self.toks[i].start].contains('\n')
    }
    fn range(&self, start: usize, end_inclusive: usize) -> Range {
        let e = end_inclusive.min(self.toks.len() - 1);
        self.toks[start].start..self.toks[e].end
    }

    /// Find matching `>` for `<` at i, limited to [i, limit].
    fn close_angle(&self, open: usize, limit: usize) -> usize {
        let mut depth = 0i32;
        let mut i = open;
        let limit = (limit + 1).min(self.toks.len());
        while i < limit {
            if self.toks[i].kind == Kind::Punct {
                match self.text(i) {
                    "<" => depth += 1,
                    ">" => {
                        depth -= 1;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    ">>" => {
                        depth -= 2;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    ">>>" => {
                        depth -= 3;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    "(" | "[" | "{" => i = self.close_of(i),
                    ";" => return i,
                    _ => {}
                }
            }
            i += 1;
        }
        limit.saturating_sub(1).max(open)
    }

    /// Statement end (exclusive) starting at i, honoring `;` and a simple ASI rule.
    fn statement_end(&self, i: usize, limit: usize) -> usize {
        let mut k = i;
        while k < limit {
            if self.is_comment(k) {
                k += 1;
                continue;
            }
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    ";" => return k + 1,
                    "(" | "[" | "{" => {
                        k = self.close_of(k);
                    }
                    "}" => return k,
                    _ => {}
                }
            }
            // ASI
            if k + 1 < limit && self.newline_before(k + 1) && self.ends_expr(k) && !self.continues_expr(k + 1) {
                return k + 1;
            }
            k += 1;
        }
        limit
    }

    fn ends_expr(&self, k: usize) -> bool {
        let t = &self.toks[k];
        match t.kind {
            Kind::Ident => !matches!(
                t.text(self.src),
                "return" | "typeof" | "case" | "do" | "else" | "in" | "instanceof" | "new" | "delete" | "void" | "throw" | "yield" | "await" | "of" | "const" | "let" | "var" | "export" | "import" | "function" | "class" | "extends" | "implements" | "as" | "if" | "for" | "while" | "switch" | "try" | "catch" | "finally" | "type" | "interface" | "enum" | "namespace" | "declare" | "abstract" | "async" | "static" | "public" | "private" | "protected" | "readonly"
            ),
            Kind::Number | Kind::Str | Kind::Char | Kind::Other => true,
            Kind::Punct => matches!(t.text(self.src), ")" | "]" | "}" | "++" | "--"),
            _ => false,
        }
    }

    fn continues_expr(&self, k: usize) -> bool {
        let t = &self.toks[k];
        match t.kind {
            Kind::Punct => matches!(
                t.text(self.src),
                "." | "?." | "(" | "[" | "+" | "-" | "*" | "/" | "%" | "=" | "==" | "===" | "!=" | "!==" | "<" | ">" | "<=" | ">=" | "&&" | "||" | "??" | "?" | ":" | "," | "=>" | "&" | "|" | "^" | "**" | "<<" | ">>" | ">>>" | "+=" | "-=" | "*=" | "/=" | "`"
            ),
            Kind::Ident => matches!(t.text(self.src), "instanceof" | "in" | "as" | "satisfies"),
            _ => false,
        }
    }

    // ----- statements -----

    fn scan_statements(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            let next = self.scan_statement(i, end);
            i = next.max(i + 1);
        }
    }

    /// Returns index after the statement starting at i.
    fn scan_statement(&mut self, i: usize, limit: usize) -> usize {
        // Decorators
        let mut i0 = i;
        while self.is_punct(i0, "@") {
            i0 = self.statement_end_of_decorator(i0, limit);
        }
        let i = i0;
        if i >= limit {
            return limit;
        }
        if self.toks[i].kind == Kind::Ident {
            let s = self.text(i);
            match s {
                "export" => {
                    let e = self.scan_export(i, limit);
                    return e;
                }
                "import" => {
                    if self.is_punct(i + 1, "(") || self.is_punct(i + 1, ".") {
                        // dynamic import expression statement
                    } else {
                        let e = self.statement_end(i, limit).max(i + 1);
                        // module string: after `from`, or the first string if no `from`
                        let mut k = i + 1;
                        let mut found = None;
                        let mut has_from = false;
                        while k < e {
                            if self.is_kw(k, "from") {
                                has_from = true;
                            }
                            if self.toks[k].kind == Kind::Str && (has_from || found.is_none()) {
                                found = Some(k);
                                if has_from {
                                    break;
                                }
                            }
                            if self.is_punct(k, "{") {
                                k = self.close_of(k);
                            }
                            k += 1;
                        }
                        // `import fs = require("x")` is not an import clause
                        let is_require = (i + 2 < e) && self.is_punct(i + 2, "=");
                        if let Some(sk) = found {
                            if !is_require {
                                for (cs, ce) in &self.toks[sk].content {
                                    self.out.imports.push(*cs..*ce);
                                }
                                if self.toks[sk].content.is_empty() {
                                    let t = &self.toks[sk];
                                    self.out.imports.push(t.start + 1..t.end.saturating_sub(1).max(t.start + 1));
                                }
                            }
                        }
                        return e;
                    }
                }
                "function" => return self.scan_function(i, i, limit, false),
                "async" if self.is_kw(i + 1, "function") => return self.scan_function(i, i + 1, limit, true),
                "class" => return self.scan_class(i, i, limit, true),
                "abstract" if self.is_kw(i + 1, "class") => return self.scan_class(i, i + 1, limit, false),
                "enum" => return self.scan_enum(i, i, limit),
                "const" if self.is_kw(i + 1, "enum") => return self.scan_enum(i, i + 1, limit),
                "interface" => {
                    let brace = self.find_brace(i, limit);
                    if brace < limit {
                        let c = self.close_of(brace);
                        self.out.interfaces.push(self.range(i, c));
                        self.scan_type_params_after_name(i + 1, brace);
                        return c + 1;
                    }
                    return self.statement_end(i, limit).max(i + 1);
                }
                "type" if self.is_ident(i + 1) && (self.is_punct(i + 2, "=") || self.is_punct(i + 2, "<")) => {
                    let e = self.statement_end(i, limit).max(i + 1);
                    self.out.type_aliases.push(self.range(i, e - 1));
                    self.scan_type_params_after_name(i + 1, e);
                    return e;
                }
                "namespace" | "module" => {
                    let brace = self.find_brace(i, limit);
                    if brace < limit {
                        let c = self.close_of(brace);
                        if s == "namespace" {
                            self.out.namespaces.push(self.range(i, c));
                        }
                        self.scan_statements(brace + 1, c);
                        return c + 1;
                    }
                    return self.statement_end(i, limit).max(i + 1);
                }
                "declare" => {
                    // declare <declaration>
                    let e = self.scan_statement(i + 1, limit);
                    return e.max(i + 1);
                }
                "let" | "const" | "var" => return self.scan_var_declaration(i, limit),
                "try" => {
                    let mut k = i + 1;
                    let mut last = i;
                    if self.is_punct(k, "{") {
                        let c = self.close_of(k);
                        self.scan_statements(k + 1, c);
                        last = c;
                        k = c + 1;
                    }
                    if self.is_kw(k, "catch") {
                        k += 1;
                        if self.is_punct(k, "(") {
                            k = self.close_of(k) + 1;
                        }
                        if self.is_punct(k, "{") {
                            let c = self.close_of(k);
                            self.scan_statements(k + 1, c);
                            last = c;
                            k = c + 1;
                        }
                    }
                    if self.is_kw(k, "finally") {
                        k += 1;
                        if self.is_punct(k, "{") {
                            let c = self.close_of(k);
                            self.scan_statements(k + 1, c);
                            last = c;
                            k = c + 1;
                        }
                    }
                    self.out.tries.push(self.range(i, last));
                    return k;
                }
                "if" | "for" | "while" | "with" | "switch" => {
                    let mut k = i + 1;
                    if self.is_punct(k, "(") {
                        let c = self.close_of(k);
                        // `for (let i = 0; ...)` declarations
                        if s == "for" {
                            self.scan_for_header(k + 1, c);
                        } else {
                            self.scan_expression(k + 1, c);
                        }
                        k = c + 1;
                    }
                    if s == "switch" {
                        if self.is_punct(k, "{") {
                            let c = self.close_of(k);
                            self.scan_switch_body(k + 1, c);
                            return c + 1;
                        }
                        return k;
                    }
                    let e = self.scan_statement(k, limit).max(k);
                    if s == "if" {
                        let mut m = e;
                        while m < limit && self.is_comment(m) {
                            m += 1;
                        }
                        if self.is_kw(m, "else") {
                            return self.scan_statement(m + 1, limit).max(m + 1);
                        }
                    }
                    return e;
                }
                "do" => {
                    let k = i + 1;
                    let e = self.scan_statement(k, limit).max(k);
                    let mut m = e;
                    if self.is_kw(m, "while") {
                        m += 1;
                        if self.is_punct(m, "(") {
                            let c = self.close_of(m);
                            self.scan_expression(m + 1, c);
                            m = c + 1;
                        }
                        if self.is_punct(m, ";") {
                            m += 1;
                        }
                    }
                    return m;
                }
                "else" => {
                    return self.scan_statement(i + 1, limit).max(i + 1);
                }
                "return" | "throw" => {
                    let e = self.statement_end(i, limit).max(i + 1);
                    self.scan_expression(i + 1, e);
                    return e;
                }
                _ => {
                    // label:
                    if self.is_punct(i + 1, ":") && !matches!(s, "case" | "default") {
                        return self.scan_statement(i + 2, limit).max(i + 2);
                    }
                }
            }
        }
        if self.is_punct(i, "{") {
            let c = self.close_of(i);
            self.scan_statements(i + 1, c);
            return c + 1;
        }
        // expression statement
        let e = self.statement_end(i, limit).max(i + 1);
        self.scan_expression(i, e);
        e
    }

    fn statement_end_of_decorator(&self, i: usize, limit: usize) -> usize {
        // @expr possibly with call
        let mut k = i + 1;
        while k < limit {
            if self.is_ident(k) {
                k += 1;
                if self.is_punct(k, ".") {
                    k += 1;
                    continue;
                }
                if self.is_punct(k, "(") {
                    k = self.close_of(k) + 1;
                }
                return k;
            }
            return k;
        }
        k
    }

    fn find_brace(&self, start: usize, limit: usize) -> usize {
        let mut k = start;
        while k < limit {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "{" => return k,
                    "(" | "[" => k = self.close_of(k),
                    "<" => k = self.close_angle(k, limit),
                    ";" => return limit,
                    _ => {}
                }
            }
            k += 1;
        }
        limit
    }

    /// Type parameters `<...>` immediately after a name at `k` (or at k itself).
    fn scan_type_params_after_name(&mut self, k: usize, limit: usize) {
        let mut m = k;
        if self.is_ident(m) {
            m += 1;
        }
        if self.is_punct(m, "<") {
            let c = self.close_angle(m, limit);
            self.out.type_params.push(self.range(m, c));
        }
    }

    fn scan_export(&mut self, i: usize, limit: usize) -> usize {
        // export default <expr|decl>; export { ... } [from]; export * from; export = x;
        // export <declaration>
        let mut k = i + 1;
        let end;
        if self.is_kw(k, "default") {
            k += 1;
            if self.is_kw(k, "function") || (self.is_kw(k, "async") && self.is_kw(k + 1, "function")) {
                let is_async = self.is_kw(k, "async");
                let fk = if is_async { k + 1 } else { k };
                // Anonymous default functions are not function declarations; named ones are.
                let named = self.is_ident(fk + 1) || (self.is_punct(fk + 1, "*") && self.is_ident(fk + 2));
                if named {
                    end = self.scan_function(k, fk, limit, is_async);
                } else {
                    end = self.scan_function_like(fk, limit);
                }
            } else if self.is_kw(k, "class") || (self.is_kw(k, "abstract") && self.is_kw(k + 1, "class")) {
                let ck = if self.is_kw(k, "class") { k } else { k + 1 };
                end = self.scan_class(k, ck, limit, ck == k);
            } else {
                end = self.statement_end(k, limit).max(k + 1);
                self.scan_expression(k, end);
            }
        } else if self.is_punct(k, "{") || self.is_punct(k, "*") || self.is_punct(k, "=") || (self.is_kw(k, "type") && self.is_punct(k + 1, "{")) {
            end = self.statement_end(k, limit).max(k + 1);
        } else if k < limit {
            end = self.scan_statement(k, limit).max(k + 1);
        } else {
            end = k;
        }
        let mut last = end.saturating_sub(1).max(i);
        while last > i && self.is_comment(last) {
            last -= 1;
        }
        self.out.exports.push(self.range(i, last));
        end
    }

    /// `[async] function [*] name<...>(...)[: type] { body }` starting at `start` (the
    /// first token of the declaration, e.g. `async`), with `fk` the `function` keyword.
    fn scan_function(&mut self, start: usize, fk: usize, limit: usize, is_async: bool) -> usize {
        let mut k = fk + 1;
        let is_generator = self.is_punct(k, "*");
        if is_generator {
            k += 1;
        }
        if self.is_ident(k) {
            k += 1;
        }
        if self.is_punct(k, "<") {
            let c = self.close_angle(k, limit);
            self.out.type_params.push(self.range(k, c));
            k = c + 1;
        }
        if self.is_punct(k, "(") {
            let c = self.close_of(k);
            self.scan_params(k + 1, c);
            k = c + 1;
        }
        if self.is_punct(k, ":") {
            k = self.consume_type(k + 1, limit);
        }
        if self.is_punct(k, "{") {
            let c = self.close_of(k);
            self.scan_statements(k + 1, c);
            if !is_generator {
                self.out.functions.push((self.range(start, c), is_async));
            }
            return c + 1;
        }
        // signature only
        let e = self.statement_end(k, limit).max(k + 1);
        e
    }

    /// A function expression (anonymous or named) at `fk` (the `function` keyword);
    /// scans body; not recorded as a declaration.
    fn scan_function_like(&mut self, fk: usize, limit: usize) -> usize {
        let mut k = fk + 1;
        if self.is_punct(k, "*") {
            k += 1;
        }
        if self.is_ident(k) {
            k += 1;
        }
        if self.is_punct(k, "<") {
            let c = self.close_angle(k, limit);
            self.out.type_params.push(self.range(k, c));
            k = c + 1;
        }
        if self.is_punct(k, "(") {
            let c = self.close_of(k);
            self.scan_params(k + 1, c);
            k = c + 1;
        }
        if self.is_punct(k, ":") {
            k = self.consume_type(k + 1, limit);
        }
        if self.is_punct(k, "{") {
            let c = self.close_of(k);
            self.scan_statements(k + 1, c);
            return c + 1;
        }
        k
    }

    fn scan_params(&mut self, start: usize, end: usize) {
        // Parameters may contain default value expressions (arrow functions etc.).
        let mut k = start;
        while k < end {
            if self.is_punct(k, "=") {
                let mut m = k + 1;
                while m < end && !self.is_punct(m, ",") {
                    if matches!(self.text(m), "(" | "[" | "{") {
                        m = self.close_of(m);
                    }
                    m += 1;
                }
                self.scan_expression(k + 1, m.min(end));
                k = m;
                continue;
            }
            if self.is_punct(k, ":") {
                k = self.consume_type(k + 1, end).max(k + 1);
                continue;
            }
            k += 1;
        }
    }

    /// Consume a type annotation starting at i; returns end (exclusive).
    fn consume_type(&mut self, mut i: usize, limit: usize) -> usize {
        let mut guard = 0;
        while i < limit && guard < 100000 {
            guard += 1;
            match self.toks[i].kind {
                Kind::Punct => match self.text(i) {
                    "(" | "[" | "{" => {
                        let c = self.close_of(i);
                        i = c + 1;
                        // function type `(a) => b`
                        if self.is_punct(i, "=>") {
                            i += 1;
                        }
                    }
                    "<" => {
                        let c = self.close_angle(i, limit);
                        i = c + 1;
                    }
                    "|" | "&" | "." | "?" | "!" | "=>" | "..." => i += 1,
                    "=" if self.is_punct(i, "=") => return i,
                    _ => return i,
                },
                Kind::Ident => {
                    let s = self.text(i);
                    if matches!(s, "extends" | "implements") && i > 0 {
                        return i;
                    }
                    if s == "typeof" || s == "keyof" || s == "readonly" || s == "infer" || s == "new" || s == "is" || s == "asserts" || s == "unique" || s == "abstract" {
                        i += 1;
                        continue;
                    }
                    i += 1;
                    // `T extends U ? X : Y` conditional types — handled loosely via punct loop
                }
                Kind::Str | Kind::Number => i += 1,
                Kind::Other => return i,
                _ => i += 1,
            }
            // Stop at statement/expression boundaries that end a type.
            if i < limit {
                let t = self.text(i);
                if self.toks[i].kind == Kind::Punct && matches!(t, ";" | "," | ")" | "]" | "}" | "=" | "{") && !self.is_punct(i, "=>") {
                    return i;
                }
            }
        }
        i
    }

    fn scan_class(&mut self, start: usize, ck: usize, limit: usize, record: bool) -> usize {
        let mut k = ck + 1;
        if self.is_ident(k) && !self.is_kw(k, "extends") && !self.is_kw(k, "implements") {
            k += 1;
        }
        if self.is_punct(k, "<") {
            let c = self.close_angle(k, limit);
            self.out.type_params.push(self.range(k, c));
            k = c + 1;
        }
        let brace = self.find_brace(k, limit);
        if brace >= limit {
            return k;
        }
        // heritage clause expressions (`extends Base<T>`) may contain type args; ignore.
        self.scan_heritage(k, brace);
        let c = self.close_of(brace);
        self.scan_class_body(brace + 1, c);
        if record {
            self.out.classes.push(self.range(start, c));
        }
        c + 1
    }

    fn scan_heritage(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.is_kw(k, "extends") {
                // expression (may be a call / mixin)
                let mut m = k + 1;
                while m < end && !self.is_kw(m, "implements") {
                    if matches!(self.text(m), "(" | "[") {
                        m = self.close_of(m);
                    }
                    m += 1;
                }
                self.scan_expression(k + 1, m);
                k = m;
                continue;
            }
            k += 1;
        }
    }

    fn scan_class_body(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") || self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            // decorators
            while self.is_punct(i, "@") {
                i = self.statement_end_of_decorator(i, end);
            }
            // static block
            if self.is_kw(i, "static") && self.is_punct(i + 1, "{") {
                let c = self.close_of(i + 1);
                self.scan_statements(i + 2, c);
                i = c + 1;
                continue;
            }
            // modifiers
            let member_start = i;
            let mut k = i;
            let mut is_abstract = false;
            while k < end && self.is_ident(k) && MODIFIERS.contains(&self.text(k)) {
                // A modifier is only a modifier if followed by another token of the member
                // (not `(`, `:`, `=`, `;`, `?`, `<`).
                if self.is_punct(k + 1, "(") || self.is_punct(k + 1, ":") || self.is_punct(k + 1, "=") || self.is_punct(k + 1, ";") || self.is_punct(k + 1, "?") || self.is_punct(k + 1, "<") || self.is_punct(k + 1, "}") || self.newline_before(k + 1) && !self.is_ident(k + 1) {
                    break;
                }
                if self.text(k) == "abstract" {
                    is_abstract = true;
                }
                k += 1;
            }
            if self.is_punct(k, "*") {
                k += 1;
            }
            // name: identifier | string | number | [computed] | #private
            if self.is_punct(k, "#") {
                k += 1;
            }
            if self.is_punct(k, "[") {
                let c = self.close_of(k);
                // index signature `[key: string]: T` vs computed name `[expr](...)`
                self.scan_expression(k + 1, c);
                k = c + 1;
            } else if k < end && matches!(self.toks[k].kind, Kind::Ident | Kind::Str | Kind::Number) {
                k += 1;
            } else {
                i = self.statement_end(k, end).max(i + 1);
                continue;
            }
            let name_tok = k - 1;
            if self.is_punct(k, "?") || self.is_punct(k, "!") {
                k += 1;
            }
            if self.is_punct(k, "<") {
                let c = self.close_angle(k, end);
                self.out.type_params.push(self.range(k, c));
                k = c + 1;
            }
            if self.is_punct(k, "(") {
                // method (definition if followed by a body)
                let c = self.close_of(k);
                self.scan_params(k + 1, c);
                k = c + 1;
                if self.is_punct(k, ":") {
                    k = self.consume_type(k + 1, end).max(k + 1);
                }
                if self.is_punct(k, "{") {
                    let bc = self.close_of(k);
                    self.scan_statements(k + 1, bc);
                    if !is_abstract {
                        let is_ctor = self.toks[name_tok].kind == Kind::Ident && self.text(name_tok) == "constructor";
                        self.out.methods.push((self.range(member_start, bc), is_ctor));
                    }
                    i = bc + 1;
                    continue;
                }
                // signature
                i = self.statement_end(k, end).max(k);
                continue;
            }
            // field
            if self.is_punct(k, ":") {
                k = self.consume_type(k + 1, end).max(k + 1);
            }
            if self.is_punct(k, "=") {
                let e = self.statement_end(k + 1, end).max(k + 1);
                self.scan_expression(k + 1, e);
                i = e;
                continue;
            }
            i = self.statement_end(k, end).max(k + 1);
        }
    }

    fn scan_enum(&mut self, start: usize, ek: usize, limit: usize) -> usize {
        let brace = self.find_brace(ek, limit);
        if brace >= limit {
            return ek + 1;
        }
        let c = self.close_of(brace);
        self.out.enums.push(self.range(start, c));
        self.scan_expression(brace + 1, c);
        c + 1
    }

    /// `let|const|var declarators;`
    fn scan_var_declaration(&mut self, i: usize, limit: usize) -> usize {
        let e = self.statement_end(i, limit).max(i + 1);
        let mut last = e - 1;
        while last > i && self.is_comment(last) {
            last -= 1;
        }
        let r = self.range(i, last);
        match self.text(i) {
            "let" => self.out.lets.push(r),
            "const" => self.out.consts.push(r),
            _ => self.out.vars.push(r),
        }
        self.scan_declarators(i + 1, if self.is_punct(last, ";") { last } else { last + 1 });
        e
    }

    /// Declarators separated by commas in [start, end).
    fn scan_declarators(&mut self, start: usize, end: usize) {
        let mut k = start;
        let mut ds = start;
        while k < end {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "(" | "[" | "{" => k = self.close_of(k),
                    "<" => {
                        // type args in annotation or generic arrow fn
                        k = self.close_angle(k, end);
                    }
                    "," => {
                        self.push_declarator(ds, k);
                        ds = k + 1;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
        self.push_declarator(ds, end);
    }

    fn push_declarator(&mut self, start: usize, end: usize) {
        let mut s = start;
        let mut e = end;
        while s < e && self.is_comment(s) {
            s += 1;
        }
        while e > s && (self.is_comment(e - 1) || self.is_punct(e - 1, ";")) {
            e -= 1;
        }
        if s < e {
            self.out.var_decls.push(self.range(s, e - 1));
            // initializer expression
            let mut k = s;
            while k < e && !self.is_punct(k, "=") {
                if matches!(self.text(k), "(" | "[" | "{") {
                    k = self.close_of(k);
                } else if self.is_punct(k, "<") {
                    k = self.close_angle(k, e);
                }
                k += 1;
            }
            if k < e {
                self.scan_expression(k + 1, e);
            }
        }
    }

    fn scan_for_header(&mut self, start: usize, end: usize) {
        // `let i = 0; cond; step` or `const k of x` / `let k in x`
        let mut k = start;
        if self.is_kw(k, "let") || self.is_kw(k, "const") || self.is_kw(k, "var") {
            // for-in/of: `const k of` → not a declaration
            let mut m = k + 1;
            let mut is_in_of = false;
            while m < end && !self.is_punct(m, ";") {
                if self.is_kw(m, "of") || self.is_kw(m, "in") {
                    is_in_of = true;
                    break;
                }
                if matches!(self.text(m), "(" | "[" | "{") {
                    m = self.close_of(m);
                }
                m += 1;
            }
            if is_in_of {
                self.scan_expression(m + 1, end);
                return;
            }
            let decl_end = m.min(end);
            let r = self.range(k, decl_end.saturating_sub(1).max(k));
            match self.text(k) {
                "let" => self.out.lets.push(r),
                "const" => self.out.consts.push(r),
                _ => self.out.vars.push(r),
            }
            self.scan_declarators(k + 1, decl_end);
            k = decl_end + 1;
        }
        self.scan_expression(k.min(end), end);
    }

    fn scan_switch_body(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_kw(i, "case") {
                let mut k = i + 1;
                while k < end && !self.is_punct(k, ":") {
                    if matches!(self.text(k), "(" | "[" | "{") {
                        k = self.close_of(k);
                    }
                    k += 1;
                }
                self.scan_expression(i + 1, k.min(end));
                i = k + 1;
                continue;
            }
            if self.is_kw(i, "default") {
                i += 1;
                if self.is_punct(i, ":") {
                    i += 1;
                }
                continue;
            }
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            let next = self.scan_statement(i, end);
            i = next.max(i + 1);
        }
    }

    /// Scan an expression region for nested constructs: function expressions, arrow
    /// functions, classes, object literal methods, type parameters of arrow functions.
    fn scan_expression(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.toks[k].kind == Kind::Ident {
                let s = self.text(k);
                if s == "function" {
                    k = self.scan_function_like(k, end).max(k + 1);
                    continue;
                }
                if s == "async" && self.is_kw(k + 1, "function") {
                    k = self.scan_function_like(k + 1, end).max(k + 2);
                    continue;
                }
                if s == "class" {
                    k = self.scan_class(k, k, end, false).max(k + 1);
                    continue;
                }
                if s == "new" && self.is_ident(k + 1) {
                    // skip `new X<T>(...)` type args
                    let mut m = k + 2;
                    while self.is_punct(m, ".") && self.is_ident(m + 1) {
                        m += 2;
                    }
                    if self.is_punct(m, "<") {
                        let c = self.close_angle(m, end);
                        self.scan_expression(m + 1, c);
                        k = c + 1;
                        continue;
                    }
                    k += 1;
                    continue;
                }
                if s == "as" || s == "satisfies" {
                    k = self.consume_type(k + 1, end).max(k + 1);
                    continue;
                }
            }
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "(" => {
                        let c = self.close_of(k);
                        // Arrow function params? `(...) [: type] =>`
                        let mut m = c + 1;
                        if self.is_punct(m, ":") {
                            // could be arrow return type or conditional; try consume
                            let t = self.consume_type(m + 1, end);
                            if self.is_punct(t, "=>") {
                                m = t;
                            }
                        }
                        if self.is_punct(m, "=>") {
                            self.scan_params(k + 1, c);
                            k = self.scan_arrow_body(m + 1, end);
                            continue;
                        }
                        self.scan_expression(k + 1, c);
                        k = c + 1;
                        continue;
                    }
                    "<" => {
                        // Generic arrow function `<T>(x: T) => x` or type assertion `<T>expr`.
                        let c = self.close_angle(k, end);
                        if self.is_punct(c + 1, "(") {
                            let pc = self.close_of(c + 1);
                            let mut m = pc + 1;
                            if self.is_punct(m, ":") {
                                let t = self.consume_type(m + 1, end);
                                if self.is_punct(t, "=>") {
                                    m = t;
                                }
                            }
                            if self.is_punct(m, "=>") {
                                self.out.type_params.push(self.range(k, c));
                                self.scan_params(c + 2, pc);
                                k = self.scan_arrow_body(m + 1, end);
                                continue;
                            }
                        }
                        k += 1;
                        continue;
                    }
                    "[" => {
                        let c = self.close_of(k);
                        self.scan_expression(k + 1, c);
                        k = c + 1;
                        continue;
                    }
                    "{" => {
                        let c = self.close_of(k);
                        self.scan_object_literal(k + 1, c);
                        k = c + 1;
                        continue;
                    }
                    "=>" => {
                        // single identifier param arrow: `x => ...`
                        k = self.scan_arrow_body(k + 1, end);
                        continue;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
    }

    fn scan_arrow_body(&mut self, k: usize, end: usize) -> usize {
        if self.is_punct(k, "{") {
            let c = self.close_of(k);
            self.scan_statements(k + 1, c);
            return c + 1;
        }
        // expression body until , ; ) ] } at depth 0
        let mut m = k;
        while m < end {
            if self.toks[m].kind == Kind::Punct {
                let s = self.text(m);
                if matches!(s, "," | ";" | ")" | "]" | "}") {
                    break;
                }
            }
            m += 1;
        }
        self.scan_expression(k, m.min(end));
        m.min(end)
    }

    /// Object literal members in [start, end).
    fn scan_object_literal(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            let member_start = i;
            let mut k = i;
            // spread
            if self.is_punct(k, "...") {
                let mut m = k + 1;
                while m < end && !self.is_punct(m, ",") {
                    if matches!(self.text(m), "(" | "[" | "{") {
                        m = self.close_of(m);
                    }
                    m += 1;
                }
                self.scan_expression(k + 1, m.min(end));
                i = m;
                continue;
            }
            // modifiers: async, get, set, *
            while k < end && self.is_ident(k) && matches!(self.text(k), "async" | "get" | "set") {
                if self.is_punct(k + 1, "(") || self.is_punct(k + 1, ":") || self.is_punct(k + 1, ",") || self.is_punct(k + 1, "}") || self.is_punct(k + 1, "=") {
                    break;
                }
                k += 1;
            }
            if self.is_punct(k, "*") {
                k += 1;
            }
            // key
            if self.is_punct(k, "[") {
                let c = self.close_of(k);
                self.scan_expression(k + 1, c);
                k = c + 1;
            } else if k < end && matches!(self.toks[k].kind, Kind::Ident | Kind::Str | Kind::Number) {
                k += 1;
            } else {
                i += 1;
                continue;
            }
            if self.is_punct(k, "<") {
                let c = self.close_angle(k, end);
                self.out.type_params.push(self.range(k, c));
                k = c + 1;
            }
            if self.is_punct(k, "(") {
                let c = self.close_of(k);
                self.scan_params(k + 1, c);
                k = c + 1;
                if self.is_punct(k, ":") {
                    k = self.consume_type(k + 1, end).max(k + 1);
                }
                if self.is_punct(k, "{") {
                    let bc = self.close_of(k);
                    self.scan_statements(k + 1, bc);
                    self.out.methods.push((self.range(member_start, bc), false));
                    i = bc + 1;
                    continue;
                }
                i = k;
                continue;
            }
            if self.is_punct(k, ":") {
                // value until ','
                let mut m = k + 1;
                while m < end && !self.is_punct(m, ",") {
                    if matches!(self.text(m), "(" | "[" | "{") {
                        m = self.close_of(m);
                    }
                    m += 1;
                }
                self.scan_expression(k + 1, m.min(end));
                i = m;
                continue;
            }
            // shorthand / default
            let mut m = k;
            while m < end && !self.is_punct(m, ",") {
                if matches!(self.text(m), "(" | "[" | "{") {
                    m = self.close_of(m);
                }
                m += 1;
            }
            self.scan_expression(k, m.min(end));
            i = m;
        }
    }
}

pub fn ranges(name: &str, src: &str) -> Vec<Range> {
    let toks = Lexer::new(src, Flavor::TypeScript).lex();
    if toks.is_empty() {
        return Vec::new();
    }
    let n = toks.len();
    let mut ctx = Ctx {
        src,
        toks,
        out: Out::default(),
    };
    ctx.scan_statements(0, n);
    match name {
        "comments" => ctx
            .toks
            .iter()
            .filter(|t| matches!(t.kind, Kind::LineComment | Kind::BlockComment))
            .map(|t| t.start..t.end)
            .collect(),
        "strings" => {
            let mut out = Vec::new();
            for t in &ctx.toks {
                if t.kind == Kind::Str {
                    for (s, e) in &t.content {
                        out.push(*s..*e);
                    }
                }
            }
            out
        }
        "imports" => ctx.out.imports,
        "function" => ctx.out.functions.into_iter().map(|(r, _)| r).collect(),
        "async-function" => ctx.out.functions.into_iter().filter(|(_, a)| *a).map(|(r, _)| r).collect(),
        "sync-function" => ctx.out.functions.into_iter().filter(|(_, a)| !*a).map(|(r, _)| r).collect(),
        "method" => ctx.out.methods.into_iter().map(|(r, _)| r).collect(),
        "constructor" => ctx.out.methods.into_iter().filter(|(_, c)| *c).map(|(r, _)| r).collect(),
        "class" => ctx.out.classes,
        "enum" => ctx.out.enums,
        "interface" => ctx.out.interfaces,
        "try-catch" => ctx.out.tries,
        "var-decl" => ctx.out.var_decls,
        "let" => ctx.out.lets,
        "const" => ctx.out.consts,
        "var" => ctx.out.vars,
        "type-params" => ctx.out.type_params,
        "type-alias" => ctx.out.type_aliases,
        "namespace" => ctx.out.namespaces,
        "export" => ctx.out.exports,
        _ => Vec::new(),
    }
}
