//! Language support: C.

use super::lexer::{matching_close, Flavor, Kind, Lexer, Token};
use super::Range;

#[derive(Default)]
struct Out {
    includes: Vec<Range>,
    type_defs: Vec<Range>,
    enums: Vec<Range>,
    structs: Vec<Range>,
    unions: Vec<Range>,
    declarations: Vec<Range>,
    function_declarators: Vec<Range>,
    function_defs: Vec<Range>,
    calls: Vec<Range>,
    switches: Vec<Range>,
    ifs: Vec<Range>,
    fors: Vec<Range>,
    whiles: Vec<Range>,
    dos: Vec<Range>,
    identifiers: Vec<Range>,
}

const KEYWORDS: &[&str] = &[
    "auto", "break", "case", "char", "const", "continue", "default", "do", "double", "else",
    "enum", "extern", "float", "for", "goto", "if", "inline", "int", "long", "register",
    "restrict", "return", "short", "signed", "sizeof", "static", "struct", "switch", "typedef",
    "union", "unsigned", "void", "volatile", "while", "_Bool", "_Complex", "_Atomic",
    "_Static_assert", "_Alignof", "_Alignas", "_Noreturn", "_Thread_local", "__attribute__",
    "__extension__", "__inline", "__inline__", "__restrict", "__volatile__", "__asm__", "asm",
    "true", "false", "NULL",
];

const TYPE_KEYWORDS: &[&str] = &[
    "char", "double", "float", "int", "long", "short", "signed", "unsigned", "void", "_Bool",
    "_Complex", "size_t", "ssize_t", "uint8_t", "uint16_t", "uint32_t", "uint64_t", "int8_t",
    "int16_t", "int32_t", "int64_t", "bool", "uintptr_t", "intptr_t", "ptrdiff_t", "wchar_t",
    "FILE",
];

const QUALIFIERS: &[&str] = &[
    "static", "extern", "const", "volatile", "inline", "register", "auto", "restrict",
    "_Atomic", "_Noreturn", "_Thread_local", "__inline", "__inline__", "__restrict",
    "__extension__", "typedef",
];

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    out: Out,
    /// Token roles: true = identifier (variable-like), false = not an identifier.
    ident: Vec<bool>,
}

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }
    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }
    fn is_kw(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && self.text(i) == s
    }
    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && !KEYWORDS.contains(&self.text(i))
    }
    fn is_comment(&self, i: usize) -> bool {
        i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment)
    }
    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }
    fn range(&self, start: usize, end_inclusive: usize) -> Range {
        let e = end_inclusive.min(self.toks.len() - 1);
        self.toks[start].start..self.toks[e].end
    }
    fn newline_before(&self, i: usize) -> bool {
        if i == 0 || i >= self.toks.len() {
            return true;
        }
        self.src[self.toks[i - 1].end..self.toks[i].start].contains('\n')
    }
    fn mark(&mut self, i: usize) {
        if self.is_ident(i) {
            self.ident[i] = true;
        }
    }

    /// End (exclusive) of a preprocessor directive starting at the `#` token.
    fn directive_end(&self, i: usize) -> usize {
        let mut k = i + 1;
        while k < self.toks.len() && !self.newline_before(k) {
            // line continuation: a backslash token at end of line
            k += 1;
        }
        // handle `\` continuations
        let mut e = k;
        while e < self.toks.len() && e > 0 && self.is_punct(e - 1, "\\") && !self.is_comment(e) {
            let mut m = e;
            while m < self.toks.len() && !self.newline_before(m) {
                m += 1;
            }
            e = m;
            if e == k {
                break;
            }
            k = e;
        }
        k
    }

    fn scan_directive(&mut self, i: usize) -> usize {
        let end = self.directive_end(i);
        let name_idx = i + 1;
        if name_idx >= end {
            return end;
        }
        let name = self.text(name_idx);
        match name {
            "include" => {
                let mut last = end - 1;
                while last > i && self.is_comment(last) {
                    last -= 1;
                }
                // `#include <stdio.h>`: the tokens `<`, `stdio`, `.`, `h`, `>` — treat as one string.
                self.out.includes.push(self.range(i, last));
            }
            "define" => {
                if self.is_ident(name_idx + 1) {
                    self.mark(name_idx + 1);
                    // function-like macro params
                    let p = name_idx + 2;
                    if self.is_punct(p, "(") && self.toks[p].start == self.toks[name_idx + 1].end {
                        let c = self.close_of(p).min(end.saturating_sub(1));
                        for k in p + 1..c {
                            self.mark(k);
                        }
                    }
                }
            }
            "ifdef" | "ifndef" | "undef" | "elifdef" | "elifndef" => {
                if self.is_ident(name_idx + 1) {
                    self.mark(name_idx + 1);
                }
            }
            "if" | "elif" => {
                for k in name_idx + 1..end {
                    if self.is_ident(k) && !self.is_kw(k, "defined") {
                        self.mark(k);
                    }
                }
            }
            _ => {}
        }
        end
    }

    /// Scan a sequence of declarations/statements in [start, end).
    fn scan_block(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            if self.toks[i].kind == Kind::Directive {
                i = self.scan_directive(i).max(i + 1);
                continue;
            }
            let next = self.scan_statement(i, end);
            i = next.max(i + 1);
        }
    }

    /// End (exclusive) of a simple statement: `;` at depth 0 or end.
    fn semi_end(&self, i: usize, end: usize) -> usize {
        let mut k = i;
        while k < end {
            if self.toks[k].kind == Kind::Directive {
                // directives inside statements: skip line
                k = self.directive_end(k);
                continue;
            }
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    ";" => return k + 1,
                    "(" | "[" | "{" => k = self.close_of(k),
                    "}" => return k,
                    _ => {}
                }
            }
            k += 1;
        }
        end
    }

    fn scan_statement(&mut self, i: usize, end: usize) -> usize {
        if self.toks[i].kind == Kind::Ident {
            let s = self.text(i);
            match s {
                "if" => {
                    let mut k = i + 1;
                    if self.is_punct(k, "(") {
                        let c = self.close_of(k);
                        self.scan_expression(k + 1, c);
                        k = c + 1;
                    }
                    let mut e = self.scan_statement(k, end).max(k);
                    let mut m = e;
                    while m < end && self.is_comment(m) {
                        m += 1;
                    }
                    if self.is_kw(m, "else") {
                        e = self.scan_statement(m + 1, end).max(m + 1);
                    }
                    self.out.ifs.push(self.range(i, e.saturating_sub(1).max(i)));
                    return e;
                }
                "for" | "while" | "switch" => {
                    let mut k = i + 1;
                    if self.is_punct(k, "(") {
                        let c = self.close_of(k);
                        if s == "for" {
                            self.scan_for_header(k + 1, c);
                        } else {
                            self.scan_expression(k + 1, c);
                        }
                        k = c + 1;
                    }
                    let e = self.scan_statement(k, end).max(k);
                    let r = self.range(i, e.saturating_sub(1).max(i));
                    match s {
                        "for" => self.out.fors.push(r),
                        "while" => self.out.whiles.push(r),
                        _ => self.out.switches.push(r),
                    }
                    return e;
                }
                "do" => {
                    let k = i + 1;
                    let e = self.scan_statement(k, end).max(k);
                    let mut m = e;
                    while m < end && self.is_comment(m) {
                        m += 1;
                    }
                    if self.is_kw(m, "while") {
                        m += 1;
                        if self.is_punct(m, "(") {
                            let c = self.close_of(m);
                            self.scan_expression(m + 1, c);
                            m = c + 1;
                        }
                        if self.is_punct(m, ";") {
                            m += 1;
                        }
                    }
                    self.out.dos.push(self.range(i, m.saturating_sub(1).max(i)));
                    return m;
                }
                "else" => return self.scan_statement(i + 1, end).max(i + 1),
                "return" => {
                    let e = self.semi_end(i, end);
                    self.scan_expression(i + 1, e);
                    return e;
                }
                "break" | "continue" => return self.semi_end(i, end),
                "goto" => return self.semi_end(i, end),
                "case" => {
                    let mut k = i + 1;
                    while k < end && !self.is_punct(k, ":") {
                        k += 1;
                    }
                    self.scan_expression(i + 1, k.min(end));
                    return k + 1;
                }
                "default" => {
                    if self.is_punct(i + 1, ":") {
                        return i + 2;
                    }
                }
                _ => {
                    // label
                    if self.is_punct(i + 1, ":") && self.is_ident(i) && !self.is_punct(i + 1, "::") {
                        return i + 2;
                    }
                }
            }
        }
        if self.is_punct(i, "{") {
            let c = self.close_of(i);
            self.scan_block(i + 1, c);
            return c + 1;
        }
        // Declaration or expression statement?
        if self.looks_like_declaration(i, end) {
            return self.scan_declaration(i, end);
        }
        let e = self.semi_end(i, end);
        self.scan_expression(i, e);
        e
    }

    fn is_type_start(&self, i: usize) -> bool {
        if i >= self.toks.len() || self.toks[i].kind != Kind::Ident {
            return false;
        }
        let s = self.text(i);
        TYPE_KEYWORDS.contains(&s) || QUALIFIERS.contains(&s) || matches!(s, "struct" | "enum" | "union" | "typedef" | "__attribute__")
    }

    fn looks_like_declaration(&self, i: usize, end: usize) -> bool {
        if self.is_type_start(i) {
            return true;
        }
        // typedef-name declarator: `Ident Ident`, `Ident *Ident`, `Ident (*name)(`
        if self.is_ident(i) {
            let mut k = i + 1;
            while k < end && self.is_punct(k, "*") {
                k += 1;
            }
            if k > i + 1 && self.is_ident(k) {
                return true;
            }
            if k == i + 1 && self.is_ident(k) && !self.is_punct(k + 1, "(") {
                return true;
            }
            if k == i + 1 && self.is_ident(k) && self.is_punct(k + 1, "(") {
                // `Type name(` — function declaration/definition
                return true;
            }
            if self.is_punct(k, "(") && self.is_punct(k + 1, "*") {
                return true;
            }
        }
        false
    }

    /// Declaration (or function definition / typedef) starting at i.
    fn scan_declaration(&mut self, i: usize, end: usize) -> usize {
        let is_typedef = self.is_kw(i, "typedef");
        // Specifiers: qualifiers, type keywords, struct/enum/union specifiers, typedef name.
        let mut k = i;
        let mut seen_type = false;
        while k < end {
            if self.toks[k].kind != Kind::Ident {
                break;
            }
            let s = self.text(k);
            if QUALIFIERS.contains(&s) {
                k += 1;
                continue;
            }
            if s == "__attribute__" {
                k += 1;
                if self.is_punct(k, "(") {
                    k = self.close_of(k) + 1;
                }
                continue;
            }
            if TYPE_KEYWORDS.contains(&s) {
                seen_type = true;
                k += 1;
                continue;
            }
            if matches!(s, "struct" | "enum" | "union") {
                k = self.scan_tagged_type(k, end);
                seen_type = true;
                continue;
            }
            if !seen_type && !KEYWORDS.contains(&s) {
                // typedef name as type (only if followed by a declarator-ish token)
                let n = k + 1;
                if self.is_ident(n) || self.is_punct(n, "*") || (self.is_punct(n, "(") && self.is_punct(n + 1, "*")) {
                    seen_type = true;
                    k += 1;
                    continue;
                }
            }
            break;
        }
        // Declarators separated by commas until ';' or '{' (function body).
        let stmt_end = self.semi_end(k, end);
        let mut d = k;
        let mut is_fn_def = false;
        let mut body_close = None;
        while d < stmt_end {
            // declarator until ',' / '=' / ';' / '{' at depth 0
            let ds = d;
            let mut m = d;
            let mut eq = None;
            while m < stmt_end {
                if self.toks[m].kind == Kind::Punct {
                    match self.text(m) {
                        "," | ";" => break,
                        "=" => {
                            eq = Some(m);
                            break;
                        }
                        "{" => {
                            // function body
                            is_fn_def = true;
                            break;
                        }
                        "(" | "[" => {
                            // function declarator?
                            let c = self.close_of(m);
                            if self.text(m) == "(" {
                                // name before '(' or `(*name)(`
                                let declarator_start = ds;
                                let has_name = m > ds;
                                if has_name && !(self.is_punct(m - 1, ")") && false) {
                                    // function_declarator spans from declarator start to ')'
                                    // but excludes leading `*` pointer declarators.
                                    let mut fs = declarator_start;
                                    while fs < m && self.is_punct(fs, "*") {
                                        fs += 1;
                                    }
                                    if fs < m {
                                        self.out.function_declarators.push(self.range(fs, c));
                                    }
                                    self.scan_params(m + 1, c);
                                }
                            }
                            m = c;
                        }
                        _ => {}
                    }
                }
                m += 1;
            }
            // identifiers within the declarator (the declared name)
            for t in ds..m.min(stmt_end) {
                if self.is_ident(t) && !self.in_function_params(t, ds, m) {
                    self.mark(t);
                }
            }
            if is_fn_def {
                // body at m
                let c = self.close_of(m);
                self.scan_block(m + 1, c);
                body_close = Some(c);
                self.out.function_defs.push(self.range(i, c));
                return c + 1;
            }
            if let Some(e) = eq {
                // initializer until ','
                let mut n = e + 1;
                while n < stmt_end {
                    if self.toks[n].kind == Kind::Punct {
                        match self.text(n) {
                            "," | ";" => break,
                            "(" | "[" | "{" => n = self.close_of(n),
                            _ => {}
                        }
                    }
                    n += 1;
                }
                self.scan_expression(e + 1, n.min(stmt_end));
                m = n;
            }
            d = m + 1;
        }
        let _ = body_close;
        let last = stmt_end.saturating_sub(1).max(i);
        if is_typedef {
            self.out.type_defs.push(self.range(i, last));
        } else if !self.is_punct(i, "}") {
            self.out.declarations.push(self.range(i, last));
        }
        stmt_end
    }

    fn in_function_params(&self, t: usize, _ds: usize, _m: usize) -> bool {
        // Identifiers inside a parameter list were handled by scan_params.
        let mut depth = 0i32;
        let mut k = t;
        while k > _ds {
            k -= 1;
            if self.is_punct(k, ")") {
                depth += 1;
            } else if self.is_punct(k, "(") {
                if depth == 0 {
                    // inside parens: parameter list if preceded by an identifier (function)
                    return k > _ds && (self.is_ident(k - 1) || self.is_punct(k - 1, ")"));
                }
                depth -= 1;
            }
        }
        false
    }

    /// `struct X { ... }` / `enum X { ... }` / `union X { ... }` at k; returns index after.
    fn scan_tagged_type(&mut self, k: usize, end: usize) -> usize {
        let kw = self.text(k);
        let mut m = k + 1;
        if self.is_kw(m, "__attribute__") {
            m += 1;
            if self.is_punct(m, "(") {
                m = self.close_of(m) + 1;
            }
        }
        if self.is_ident(m) {
            m += 1; // tag (type_identifier)
        }
        let last;
        if self.is_punct(m, "{") {
            let c = self.close_of(m);
            match kw {
                "enum" => self.scan_enumerators(m + 1, c),
                _ => self.scan_block(m + 1, c),
            }
            last = c;
            m = c + 1;
        } else {
            last = m - 1;
        }
        let r = self.range(k, last);
        match kw {
            "struct" => self.out.structs.push(r),
            "enum" => self.out.enums.push(r),
            _ => self.out.unions.push(r),
        }
        let _ = end;
        m
    }

    fn scan_enumerators(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.is_ident(k) && (k == start || self.is_punct(k - 1, ",")) {
                self.mark(k);
                k += 1;
                if self.is_punct(k, "=") {
                    let mut m = k + 1;
                    while m < end && !self.is_punct(m, ",") {
                        if matches!(self.text(m), "(" | "[" | "{") {
                            m = self.close_of(m);
                        }
                        m += 1;
                    }
                    self.scan_expression(k + 1, m.min(end));
                    k = m;
                }
                continue;
            }
            k += 1;
        }
    }

    /// Parameter list: `type name, type *name[]` — names are identifiers.
    fn scan_params(&mut self, start: usize, end: usize) {
        let mut k = start;
        let mut item_start = start;
        while k <= end {
            if k == end || self.is_punct(k, ",") {
                // last identifier of the item (not followed by `(`) is the name
                let mut last_ident = None;
                let mut m = item_start;
                while m < k {
                    if self.is_ident(m) {
                        last_ident = Some(m);
                    } else if self.is_punct(m, "(") || self.is_punct(m, "[") {
                        let c = self.close_of(m);
                        // function pointer param `int (*cb)(int)`: name inside first parens
                        if self.is_punct(m + 1, "*") && self.is_ident(m + 2) {
                            self.mark(m + 2);
                            last_ident = None;
                        }
                        m = c;
                    }
                    m += 1;
                }
                if let Some(li) = last_ident {
                    // a lone type name like `void` or `Point` is a type, not a name
                    let only_token = k - item_start == 1;
                    if !only_token || !self.text(li).chars().next().map_or(false, |c| c.is_uppercase()) && !only_token {
                        self.mark(li);
                    }
                }
                item_start = k + 1;
            }
            k += 1;
        }
    }

    fn scan_for_header(&mut self, start: usize, end: usize) {
        // init; cond; step
        let mut k = start;
        if k < end && self.looks_like_declaration(k, end) {
            k = self.scan_declaration(k, end);
            // declaration includes ';'
        } else {
            let e = self.semi_end(k, end);
            self.scan_expression(k, e.saturating_sub(1).max(k));
            k = e;
        }
        self.scan_expression(k.min(end), end);
    }

    /// Expression region: identifiers, calls, compound literals.
    fn scan_expression(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            let tk = self.toks[k].kind;
            if tk == Kind::Directive {
                k = self.scan_directive(k).max(k + 1);
                continue;
            }
            if tk == Kind::Ident {
                let s = self.text(k);
                if s == "sizeof" || s == "_Alignof" {
                    k += 1;
                    continue;
                }
                if !KEYWORDS.contains(&s) {
                    // call?
                    if self.is_punct(k + 1, "(") {
                        let c = self.close_of(k + 1);
                        self.out.calls.push(self.range(k, c));
                        self.mark(k);
                        self.scan_expression(k + 2, c);
                        k = c + 1;
                        // chained calls `f(x)(y)`
                        while self.is_punct(k, "(") {
                            let c2 = self.close_of(k);
                            self.scan_expression(k + 1, c2);
                            k = c2 + 1;
                        }
                        continue;
                    }
                    // field access after . or ->
                    if k > start && (self.is_punct(k - 1, ".") || self.is_punct(k - 1, "->")) {
                        k += 1;
                        continue;
                    }
                    // cast / compound literal `(Type)` : identifier alone inside parens
                    // followed by `)` and then `{` or an operand → type.
                    if k > start && self.is_punct(k - 1, "(") && self.is_punct(k + 1, ")") && k + 2 < end
                        && (self.is_punct(k + 2, "{") || self.is_ident(k + 2) || self.is_punct(k + 2, "(") || self.is_punct(k + 2, "&") || self.is_punct(k + 2, "*") || self.toks[k + 2].kind == Kind::Number)
                        && s.chars().next().map_or(false, |c| c.is_uppercase() || s.ends_with("_t"))
                    {
                        k += 1;
                        continue;
                    }
                    self.mark(k);
                }
                k += 1;
                continue;
            }
            if tk == Kind::Punct {
                match self.text(k) {
                    "(" => {
                        let c = self.close_of(k);
                        // call on parenthesized expression / function pointer
                        if k > start && (self.is_punct(k - 1, ")") || self.is_punct(k - 1, "]")) {
                            // (*fp)(args) → call expression from the start of the primary
                            let mut s0 = k - 1;
                            if self.is_punct(s0, ")") {
                                // find matching open
                                let mut depth = 0;
                                while s0 > start {
                                    if self.is_punct(s0, ")") {
                                        depth += 1;
                                    } else if self.is_punct(s0, "(") {
                                        depth -= 1;
                                        if depth == 0 {
                                            break;
                                        }
                                    }
                                    s0 -= 1;
                                }
                            }
                            self.out.calls.push(self.range(s0, c));
                        }
                        self.scan_expression(k + 1, c);
                        k = c + 1;
                        continue;
                    }
                    "[" | "{" => {
                        let c = self.close_of(k);
                        self.scan_expression(k + 1, c);
                        k = c + 1;
                        continue;
                    }
                    _ => {}
                }
            }
            k += 1;
        }
    }
}

pub fn ranges(name: &str, src: &str) -> Vec<Range> {
    let toks = Lexer::new(src, Flavor::C).lex();
    if toks.is_empty() {
        return Vec::new();
    }
    let n = toks.len();
    let mut ctx = Ctx {
        src,
        toks,
        out: Out::default(),
        ident: vec![false; n],
    };
    ctx.scan_block(0, n);
    match name {
        "comments" => ctx
            .toks
            .iter()
            .filter(|t| matches!(t.kind, Kind::LineComment | Kind::BlockComment))
            .map(|t| t.start..t.end)
            .collect(),
        "strings" => {
            let mut out: Vec<Range> = ctx
                .toks
                .iter()
                .filter(|t| t.kind == Kind::Str)
                .map(|t| t.start..t.end)
                .collect();
            // `#include <...>` system lib strings
            for inc in &ctx.out.includes {
                let text = &src[inc.clone()];
                if let Some(lt) = text.find('<') {
                    if let Some(gt) = text.rfind('>') {
                        if gt > lt {
                            out.push(inc.start + lt..inc.start + gt + 1);
                        }
                    }
                }
            }
            out
        }
        "includes" => ctx.out.includes,
        "type-def" => ctx.out.type_defs,
        "enum" => ctx.out.enums,
        "struct" => ctx.out.structs,
        "union" => ctx.out.unions,
        "variable" | "declaration" => ctx.out.declarations,
        "function" => {
            let mut out = ctx.out.function_declarators.clone();
            out.extend(ctx.out.calls.clone());
            out
        }
        "function-def" => ctx.out.function_defs,
        "function-decl" => ctx.out.function_declarators,
        "switch" => ctx.out.switches,
        "if" => ctx.out.ifs,
        "for" => ctx.out.fors,
        "while" => ctx.out.whiles,
        "do" => ctx.out.dos,
        "identifier" => {
            let mut out = Vec::new();
            for (i, t) in ctx.toks.iter().enumerate() {
                if ctx.ident[i] {
                    out.push(t.start..t.end);
                }
            }
            out
        }
        "call-expression" => ctx.out.calls,
        _ => Vec::new(),
    }
}
