//! Language support: C#.

use super::lexer::{matching_close, Flavor, Kind, Lexer, Token};
use super::Range;

#[derive(Default)]
struct Out {
    usings: Vec<Range>,
    structs: Vec<Range>,
    enums: Vec<Range>,
    interfaces: Vec<Range>,
    classes: Vec<Range>,
    methods: Vec<Range>,
    var_decls: Vec<Range>,
    properties: Vec<Range>,
    constructors: Vec<Range>,
    destructors: Vec<Range>,
    fields: Vec<Range>,
    attributes: Vec<Range>,
}

const KEYWORDS: &[&str] = &[
    "abstract", "as", "base", "bool", "break", "byte", "case", "catch", "char", "checked",
    "class", "const", "continue", "decimal", "default", "delegate", "do", "double", "else",
    "enum", "event", "explicit", "extern", "false", "finally", "fixed", "float", "for",
    "foreach", "goto", "if", "implicit", "in", "int", "interface", "internal", "is", "lock",
    "long", "namespace", "new", "null", "object", "operator", "out", "override", "params",
    "private", "protected", "public", "readonly", "ref", "return", "sbyte", "sealed", "short",
    "sizeof", "stackalloc", "static", "string", "struct", "switch", "this", "throw", "true",
    "try", "typeof", "uint", "ulong", "unchecked", "unsafe", "ushort", "using", "virtual",
    "void", "volatile", "while", "var", "dynamic", "nint", "nuint", "record", "async", "await",
    "get", "set", "init", "value", "where", "yield", "partial", "global", "add", "remove",
    "when", "nameof", "notnull", "unmanaged", "required", "scoped", "file", "with", "and",
    "or", "not", "managed", "alias", "ascending", "descending", "by", "equals", "from", "group",
    "into", "join", "let", "on", "orderby", "select",
];

/// Contextual keywords which are identifiers when used as names.
const CONTEXTUAL: &[&str] = &[
    "var", "dynamic", "record", "async", "await", "get", "set", "init", "value", "where", "yield",
    "partial", "global", "add", "remove", "when", "nameof", "notnull", "unmanaged", "required",
    "scoped", "file", "with", "and", "or", "not", "managed", "alias", "ascending", "descending",
    "by", "equals", "from", "group", "into", "join", "let", "on", "orderby", "select", "nint",
    "nuint",
];

const MODIFIERS: &[&str] = &[
    "public", "private", "protected", "internal", "static", "readonly", "const", "abstract",
    "virtual", "override", "sealed", "extern", "unsafe", "volatile", "async", "partial", "new",
    "required", "fixed", "ref", "file", "scoped",
];

const PREDEFINED: &[&str] = &[
    "bool", "byte", "sbyte", "char", "decimal", "double", "float", "int", "uint", "long", "ulong",
    "object", "short", "ushort", "string", "void", "var", "dynamic", "nint", "nuint",
];

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    out: Out,
    not_ident: Vec<bool>,
}

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }
    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }
    fn is_kw(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && self.text(i) == s
    }
    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident && (!KEYWORDS.contains(&self.text(i)) || CONTEXTUAL.contains(&self.text(i)))
    }
    fn is_comment(&self, i: usize) -> bool {
        i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment)
    }
    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }
    fn range(&self, start: usize, end_inclusive: usize) -> Range {
        let e = end_inclusive.min(self.toks.len() - 1);
        self.toks[start].start..self.toks[e].end
    }

    fn close_angle(&self, open: usize, limit: usize) -> usize {
        let mut depth = 0i32;
        let mut i = open;
        let limit = (limit + 1).min(self.toks.len());
        while i < limit {
            if self.toks[i].kind == Kind::Punct {
                match self.text(i) {
                    "<" => depth += 1,
                    ">" => {
                        depth -= 1;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    ">>" => {
                        depth -= 2;
                        if depth <= 0 {
                            return i;
                        }
                    }
                    "(" | "[" | "{" => i = self.close_of(i),
                    ";" => return i,
                    _ => {}
                }
            }
            i += 1;
        }
        limit.saturating_sub(1).max(open)
    }

    fn semi_end(&self, i: usize, end: usize) -> usize {
        let mut k = i;
        while k < end {
            if self.toks[k].kind == Kind::Directive {
                k = self.directive_end(k);
                continue;
            }
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    ";" => return k + 1,
                    "(" | "[" | "{" => k = self.close_of(k),
                    "}" => return k,
                    _ => {}
                }
            }
            k += 1;
        }
        end
    }

    fn directive_end(&self, i: usize) -> usize {
        let mut k = i + 1;
        while k < self.toks.len() && !self.src[self.toks[k - 1].end..self.toks[k].start].contains('\n') {
            k += 1;
        }
        for m in i..k.min(self.toks.len()) {
            // directive content is not identifiers
            let _ = m;
        }
        k
    }

    /// Attributes `[...]` at i; returns index after them.
    fn scan_attributes(&mut self, i: usize, end: usize) -> usize {
        let mut k = i;
        while k < end && self.is_punct(k, "[") {
            let c = self.close_of(k);
            // attribute list: [target:] attr(args), attr2
            let mut a = k + 1;
            if self.is_ident(a) && self.is_punct(a + 1, ":") {
                a += 2;
            }
            let mut astart = a;
            let mut m = a;
            while m <= c {
                if m == c || self.is_punct(m, ",") {
                    if astart < m {
                        self.out.attributes.push(self.range(astart, m - 1));
                    }
                    astart = m + 1;
                } else if self.is_punct(m, "(") {
                    let pc = self.close_of(m);
                    self.scan_expression(m + 1, pc);
                    m = pc;
                }
                m += 1;
            }
            k = c + 1;
        }
        k
    }

    /// Consume a type at i; returns index after.
    fn consume_type(&self, mut i: usize, end: usize) -> usize {
        if i >= end {
            return i;
        }
        if self.is_punct(i, "(") {
            // tuple type
            i = self.close_of(i) + 1;
        } else if self.toks[i].kind == Kind::Ident {
            i += 1;
            loop {
                if self.is_punct(i, "::") && self.is_ident(i + 1) {
                    i += 2;
                    continue;
                }
                if self.is_punct(i, "<") {
                    let c = self.close_angle(i, end);
                    i = c + 1;
                }
                if self.is_punct(i, ".") && self.is_ident(i + 1) {
                    i += 2;
                    continue;
                }
                break;
            }
        } else {
            return i;
        }
        loop {
            if self.is_punct(i, "?") {
                i += 1;
                continue;
            }
            if self.is_punct(i, "*") {
                i += 1;
                continue;
            }
            if self.is_punct(i, "[") {
                let c = self.close_of(i);
                // array rank specifier: only commas inside
                let mut ok = true;
                for m in i + 1..c {
                    if !self.is_punct(m, ",") {
                        ok = false;
                    }
                }
                if ok {
                    i = c + 1;
                    continue;
                }
            }
            break;
        }
        i
    }

    fn scan_file(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            if self.toks[i].kind == Kind::Directive {
                i = self.directive_end(i).max(i + 1);
                continue;
            }
            if self.is_kw(i, "using") && !self.is_punct(i + 1, "(") {
                let e = self.semi_end(i, end);
                let mut k = i + 1;
                if self.is_kw(k, "static") || self.is_kw(k, "global") {
                    k += 1;
                    if self.is_kw(k, "static") {
                        k += 1;
                    }
                }
                let last = e.saturating_sub(1);
                let last = if self.is_punct(last, ";") { last - 1 } else { last };
                // alias: `Alias = Name`
                if self.is_ident(k) && self.is_punct(k + 1, "=") {
                    self.out.usings.push(self.range(k, k));
                    if k + 2 <= last {
                        self.out.usings.push(self.range(k + 2, last));
                    }
                } else if k <= last {
                    self.out.usings.push(self.range(k, last));
                }
                i = e.max(i + 1);
                continue;
            }
            if self.is_kw(i, "namespace") {
                let mut k = i + 1;
                while k < end && !self.is_punct(k, "{") && !self.is_punct(k, ";") {
                    k += 1;
                }
                if self.is_punct(k, "{") {
                    let c = self.close_of(k);
                    self.scan_file(k + 1, c);
                    i = c + 1;
                } else {
                    i = k + 1;
                }
                continue;
            }
            // Type declaration (with attributes/modifiers) or top-level statement.
            let next = self.scan_member(i, end, None);
            i = next.max(i + 1);
        }
    }

    /// Scan a member (type declaration, method, field, property, ...) at i; `enclosing` is
    /// the enclosing type name (for constructors). Returns index after.
    fn scan_member(&mut self, i: usize, end: usize, enclosing: Option<&str>) -> usize {
        let start = i;
        let mut k = self.scan_attributes(i, end);
        while k < end && self.toks[k].kind == Kind::Ident && MODIFIERS.contains(&self.text(k)) {
            // `new` as modifier only if followed by a type/ident; `ref struct` etc.
            if self.text(k) == "new" && !self.is_ident(k + 1) {
                break;
            }
            // contextual: `partial` followed by class/struct...
            k += 1;
        }
        if k >= end {
            return end;
        }
        let kw = if self.toks[k].kind == Kind::Ident { self.text(k) } else { "" };
        match kw {
            "class" | "struct" | "interface" | "enum" | "record" => {
                let mut m = k + 1;
                let mut kind = kw;
                if kw == "record" && (self.is_kw(m, "struct") || self.is_kw(m, "class")) {
                    kind = if self.is_kw(m, "struct") { "struct" } else { "class" };
                    m += 1;
                }
                let name = if self.is_ident(m) { self.text(m).to_owned() } else { String::new() };
                let mut n = m;
                while n < end && !self.is_punct(n, "{") && !self.is_punct(n, ";") {
                    if self.is_punct(n, "(") {
                        n = self.close_of(n);
                    }
                    n += 1;
                }
                let last;
                if self.is_punct(n, "{") {
                    let c = self.close_of(n);
                    if kind == "enum" {
                        self.scan_expression(n + 1, c);
                    } else {
                        self.scan_type_body(n + 1, c, &name);
                    }
                    last = c;
                    n = c + 1;
                    if self.is_punct(n, ";") {
                        n += 1;
                    }
                } else {
                    last = n;
                    n += 1;
                }
                let r = self.range(start, last);
                match kind {
                    "class" => self.out.classes.push(r),
                    "struct" => self.out.structs.push(r),
                    "interface" => self.out.interfaces.push(r),
                    "enum" => self.out.enums.push(r),
                    _ => {}
                }
                return n;
            }
            "delegate" | "event" => {
                let e = self.semi_end(k, end);
                return e.max(k + 1);
            }
            "namespace" => {
                let mut m = k + 1;
                while m < end && !self.is_punct(m, "{") && !self.is_punct(m, ";") {
                    m += 1;
                }
                if self.is_punct(m, "{") {
                    let c = self.close_of(m);
                    self.scan_file(m + 1, c);
                    return c + 1;
                }
                return m + 1;
            }
            _ => {}
        }
        // Destructor
        if self.is_punct(k, "~") && self.is_ident(k + 1) && self.is_punct(k + 2, "(") {
            let c = self.close_of(k + 2);
            let mut m = c + 1;
            let last;
            if self.is_punct(m, "{") {
                let bc = self.close_of(m);
                self.scan_statements(m + 1, bc);
                last = bc;
                m = bc + 1;
            } else {
                m = self.semi_end(m, end);
                last = m.saturating_sub(1);
            }
            self.out.destructors.push(self.range(start, last));
            return m;
        }
        // Constructor: Name( where Name == enclosing
        if let Some(enc) = enclosing {
            if self.is_ident(k) && self.text(k) == enc && self.is_punct(k + 1, "(") {
                let c = self.close_of(k + 1);
                self.scan_params(k + 2, c);
                let mut m = c + 1;
                // : base(...) / : this(...)
                if self.is_punct(m, ":") {
                    m += 1;
                    if m < end {
                        m += 1;
                    }
                    if self.is_punct(m, "(") {
                        let pc = self.close_of(m);
                        self.scan_expression(m + 1, pc);
                        m = pc + 1;
                    }
                }
                let last;
                if self.is_punct(m, "{") {
                    let bc = self.close_of(m);
                    self.scan_statements(m + 1, bc);
                    last = bc;
                    m = bc + 1;
                } else {
                    m = self.semi_end(m, end);
                    last = m.saturating_sub(1);
                }
                self.out.constructors.push(self.range(start, last));
                return m;
            }
        }
        // Type then name: method / property / field / local declaration / statement.
        let t_end = self.consume_type(k, end);
        if t_end > k && t_end < end {
            // explicit interface implementation `IFoo.Bar(`
            let mut name_idx = t_end;
            if self.is_ident(name_idx) || self.is_kw(name_idx, "this") || (self.is_kw(name_idx, "operator")) {
                let after_name = if self.is_kw(name_idx, "operator") { name_idx + 2 } else { name_idx + 1 };
                let mut m = after_name;
                if self.is_punct(m, "<") {
                    m = self.close_angle(m, end) + 1;
                }
                if self.is_punct(m, "(") && enclosing.is_some() || (self.is_punct(m, "(") && self.is_method_like(m, end)) {
                    // method
                    let c = self.close_of(m);
                    self.scan_params(m + 1, c);
                    let mut n = c + 1;
                    // where constraints
                    while self.is_kw(n, "where") {
                        while n < end && !self.is_punct(n, "{") && !self.is_punct(n, ";") && !self.is_punct(n, "=>") && !self.is_kw(n, "where") || self.is_kw(n, "where") && n == c + 1 {
                            n += 1;
                            if self.is_kw(n, "where") {
                                break;
                            }
                        }
                    }
                    let last;
                    if self.is_punct(n, "{") {
                        let bc = self.close_of(n);
                        self.scan_statements(n + 1, bc);
                        last = bc;
                        n = bc + 1;
                    } else if self.is_punct(n, "=>") {
                        n = self.semi_end(n, end);
                        last = n.saturating_sub(1);
                    } else {
                        n = self.semi_end(n, end);
                        last = n.saturating_sub(1);
                    }
                    self.out.methods.push(self.range(start, last));
                    return n.max(start + 1);
                }
                if self.is_punct(m, "{") && enclosing.is_some() || (self.is_punct(m, "{") && self.is_accessor_block(m)) {
                    // property
                    let c = self.close_of(m);
                    self.scan_accessors(m + 1, c);
                    let mut n = c + 1;
                    let mut last = c;
                    if self.is_punct(n, "=") {
                        n = self.semi_end(n, end);
                        last = n.saturating_sub(1);
                    }
                    self.out.properties.push(self.range(start, last));
                    return n;
                }
                if self.is_punct(m, "=>") && enclosing.is_some() {
                    // expression-bodied property
                    let n = self.semi_end(m, end);
                    self.scan_expression(m + 1, n);
                    self.out.properties.push(self.range(start, n.saturating_sub(1)));
                    return n;
                }
                if self.is_punct(m, "[") && enclosing.is_some() {
                    // indexer
                    let c = self.close_of(m);
                    let mut n = c + 1;
                    if self.is_punct(n, "{") {
                        let bc = self.close_of(n);
                        self.scan_accessors(n + 1, bc);
                        n = bc + 1;
                    }
                    return n.max(start + 1);
                }
                if self.is_punct(m, "=") || self.is_punct(m, ",") || self.is_punct(m, ";") {
                    // field / local variable declaration
                    let e = self.semi_end(k, end);
                    let last = e.saturating_sub(1);
                    let decl_last = if self.is_punct(last, ";") { last.saturating_sub(1) } else { last };
                    if decl_last >= k {
                        self.out.var_decls.push(self.range(k, decl_last));
                    }
                    if enclosing.is_some() {
                        self.out.fields.push(self.range(start, last));
                    }
                    // initializers
                    self.scan_declarator_inits(name_idx, e);
                    return e.max(start + 1);
                }
                let _ = &mut name_idx;
            }
        }
        // Fallback: statement.
        self.scan_statement(start, end)
    }

    fn is_method_like(&self, paren: usize, end: usize) -> bool {
        // `Type Name(params) {` or `;` or `=>` at top-level (local function).
        let c = self.close_of(paren);
        let n = c + 1;
        n < end && (self.is_punct(n, "{") || self.is_punct(n, "=>") || self.is_kw(n, "where"))
    }

    fn is_accessor_block(&self, brace: usize) -> bool {
        let c = self.close_of(brace);
        let mut k = brace + 1;
        while k < c {
            if self.is_punct(k, "[") {
                k = self.close_of(k) + 1;
                continue;
            }
            if self.toks[k].kind == Kind::Ident && MODIFIERS.contains(&self.text(k)) {
                k += 1;
                continue;
            }
            return self.is_kw(k, "get") || self.is_kw(k, "set") || self.is_kw(k, "init");
        }
        false
    }

    fn scan_accessors(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.is_punct(k, "{") {
                let c = self.close_of(k);
                self.scan_statements(k + 1, c);
                k = c + 1;
                continue;
            }
            if self.is_punct(k, "=>") {
                let e = self.semi_end(k, end);
                self.scan_expression(k + 1, e);
                k = e;
                continue;
            }
            k += 1;
        }
    }

    fn scan_params(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.is_punct(k, "[") {
                k = self.scan_attributes(k, end);
                continue;
            }
            if self.is_punct(k, "=") {
                let mut m = k + 1;
                while m < end && !self.is_punct(m, ",") {
                    if matches!(self.text(m), "(" | "[" | "{") {
                        m = self.close_of(m);
                    }
                    m += 1;
                }
                self.scan_expression(k + 1, m.min(end));
                k = m;
                continue;
            }
            k += 1;
        }
    }

    fn scan_declarator_inits(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.is_punct(k, "=") {
                let mut m = k + 1;
                while m < end && !self.is_punct(m, ",") && !self.is_punct(m, ";") {
                    if matches!(self.text(m), "(" | "[" | "{") {
                        m = self.close_of(m);
                    }
                    m += 1;
                }
                self.scan_expression(k + 1, m.min(end));
                k = m;
                continue;
            }
            k += 1;
        }
    }

    fn scan_type_body(&mut self, start: usize, end: usize, name: &str) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") || self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            if self.toks[i].kind == Kind::Directive {
                i = self.directive_end(i).max(i + 1);
                continue;
            }
            let next = self.scan_member(i, end, Some(name));
            i = next.max(i + 1);
        }
    }

    fn scan_statements(&mut self, start: usize, end: usize) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ";") {
                i += 1;
                continue;
            }
            if self.toks[i].kind == Kind::Directive {
                i = self.directive_end(i).max(i + 1);
                continue;
            }
            let next = self.scan_statement(i, end);
            i = next.max(i + 1);
        }
    }

    fn scan_statement(&mut self, i: usize, end: usize) -> usize {
        if self.toks[i].kind == Kind::Ident {
            let s = self.text(i);
            match s {
                "if" | "while" | "switch" | "for" | "foreach" | "using" | "lock" | "fixed" if self.is_punct(i + 1, "(") => {
                    let c = self.close_of(i + 1);
                    if s == "for" || s == "foreach" || s == "using" || s == "fixed" {
                        self.scan_header(i + 2, c);
                    } else {
                        self.scan_expression(i + 2, c);
                    }
                    let mut k = c + 1;
                    if s == "switch" && self.is_punct(k, "{") {
                        let bc = self.close_of(k);
                        self.scan_switch_body(k + 1, bc);
                        return bc + 1;
                    }
                    let e = self.scan_statement(k, end).max(k);
                    if s == "if" {
                        let mut m = e;
                        while m < end && self.is_comment(m) {
                            m += 1;
                        }
                        if self.is_kw(m, "else") {
                            return self.scan_statement(m + 1, end).max(m + 1);
                        }
                    }
                    k = e;
                    return k;
                }
                "do" => {
                    let e = self.scan_statement(i + 1, end).max(i + 1);
                    let mut m = e;
                    if self.is_kw(m, "while") && self.is_punct(m + 1, "(") {
                        let c = self.close_of(m + 1);
                        self.scan_expression(m + 2, c);
                        m = c + 1;
                        if self.is_punct(m, ";") {
                            m += 1;
                        }
                    }
                    return m;
                }
                "try" => {
                    let mut k = i + 1;
                    if self.is_punct(k, "{") {
                        let c = self.close_of(k);
                        self.scan_statements(k + 1, c);
                        k = c + 1;
                    }
                    while self.is_kw(k, "catch") || self.is_kw(k, "finally") {
                        k += 1;
                        if self.is_punct(k, "(") {
                            k = self.close_of(k) + 1;
                        }
                        if self.is_kw(k, "when") && self.is_punct(k + 1, "(") {
                            let c = self.close_of(k + 1);
                            self.scan_expression(k + 2, c);
                            k = c + 1;
                        }
                        if self.is_punct(k, "{") {
                            let c = self.close_of(k);
                            self.scan_statements(k + 1, c);
                            k = c + 1;
                        }
                    }
                    return k;
                }
                "else" => return self.scan_statement(i + 1, end).max(i + 1),
                "return" | "throw" | "yield" | "await" => {
                    let e = self.semi_end(i, end);
                    self.scan_expression(i + 1, e);
                    return e;
                }
                "break" | "continue" | "goto" => return self.semi_end(i, end),
                "case" => {
                    let mut k = i + 1;
                    while k < end && !self.is_punct(k, ":") {
                        if matches!(self.text(k), "(" | "[" | "{") {
                            k = self.close_of(k);
                        }
                        k += 1;
                    }
                    self.scan_expression(i + 1, k.min(end));
                    return k + 1;
                }
                "default" if self.is_punct(i + 1, ":") => return i + 2,
                "const" => {
                    // local const declaration
                    let e = self.semi_end(i, end);
                    let t_end = self.consume_type(i + 1, e);
                    if t_end > i + 1 && t_end < e {
                        let last = e.saturating_sub(1);
                        let decl_last = if self.is_punct(last, ";") { last - 1 } else { last };
                        self.out.var_decls.push(self.range(i + 1, decl_last));
                        self.scan_declarator_inits(t_end, e);
                    }
                    return e;
                }
                "var" | "using" | "static" | "unsafe" | "checked" | "unchecked" | "async" => {}
                _ => {}
            }
        }
        if self.is_punct(i, "{") {
            let c = self.close_of(i);
            self.scan_statements(i + 1, c);
            return c + 1;
        }
        // Local declaration?  `Type name [= ...][, name...];`
        let mut k = i;
        if self.is_kw(k, "using") || self.is_kw(k, "ref") || self.is_kw(k, "scoped") {
            k += 1;
            if self.is_kw(k, "readonly") {
                k += 1;
            }
        }
        let t_end = self.consume_type(k, end);
        if t_end > k && t_end < end && self.is_ident(t_end) && (self.is_punct(t_end + 1, "=") || self.is_punct(t_end + 1, ";") || self.is_punct(t_end + 1, ",")) {
            let e = self.semi_end(k, end);
            let last = e.saturating_sub(1);
            let decl_last = if self.is_punct(last, ";") { last.saturating_sub(1) } else { last };
            if decl_last >= k {
                self.out.var_decls.push(self.range(k, decl_last));
            }
            self.scan_declarator_inits(t_end, e);
            return e.max(i + 1);
        }
        // Local function?
        if t_end > k && t_end < end && self.is_ident(t_end) {
            let mut m = t_end + 1;
            if self.is_punct(m, "<") {
                m = self.close_angle(m, end) + 1;
            }
            if self.is_punct(m, "(") && self.is_method_like(m, end) {
                let c = self.close_of(m);
                self.scan_params(m + 1, c);
                let mut n = c + 1;
                let last;
                if self.is_punct(n, "{") {
                    let bc = self.close_of(n);
                    self.scan_statements(n + 1, bc);
                    last = bc;
                    n = bc + 1;
                } else {
                    n = self.semi_end(n, end);
                    last = n.saturating_sub(1);
                }
                let _ = last;
                return n.max(i + 1);
            }
        }
        // Expression statement.
        let e = self.semi_end(i, end);
        self.scan_expression(i, e);
        e.max(i + 1)
    }

    fn scan_header(&mut self, start: usize, end: usize) {
        // for: init; cond; step   foreach: Type x in expr   using: Type x = expr
        let mut k = start;
        let t_end = self.consume_type(k, end);
        if t_end > k && t_end < end && self.is_ident(t_end) && (self.is_punct(t_end + 1, "=") || self.is_kw(t_end + 1, "in") || self.is_punct(t_end + 1, ",")) {
            // declaration
            let mut e = t_end;
            while e < end && !self.is_punct(e, ";") && !self.is_kw(e, "in") {
                if matches!(self.text(e), "(" | "[" | "{") {
                    e = self.close_of(e);
                }
                e += 1;
            }
            let last = e.saturating_sub(1);
            if last >= k {
                self.out.var_decls.push(self.range(k, last));
            }
            self.scan_declarator_inits(t_end, e.min(end));
            k = e + 1;
        }
        if k < end {
            self.scan_expression(k, end);
        }
    }

    fn scan_switch_body(&mut self, start: usize, end: usize) {
        self.scan_statements(start, end);
    }

    /// Expression region: lambdas with block bodies, anonymous methods, object initializers.
    fn scan_expression(&mut self, start: usize, end: usize) {
        let mut k = start;
        while k < end {
            if self.toks[k].kind == Kind::Punct {
                match self.text(k) {
                    "{" => {
                        let c = self.close_of(k);
                        // lambda / anonymous method body
                        if k > 0 && (self.is_punct(k - 1, "=>") || self.is_punct(k - 1, ")") || self.is_kw(k - 1, "delegate")) {
                            self.scan_statements(k + 1, c);
                        } else {
                            self.scan_expression(k + 1, c);
                        }
                        k = c + 1;
                        continue;
                    }
                    "(" | "[" => {
                        let c = self.close_of(k);
                        self.scan_expression(k + 1, c);
                        k = c + 1;
                        continue;
                    }
                    _ => {}
                }
            }
            if self.toks[k].kind == Kind::Str {
                // interpolation holes contain expressions (identifiers inside are identifiers)
            }
            k += 1;
        }
    }
}

pub fn ranges(name: &str, src: &str) -> Vec<Range> {
    let toks = Lexer::new(src, Flavor::CSharp).lex();
    if toks.is_empty() {
        return Vec::new();
    }
    let n = toks.len();
    let mut ctx = Ctx {
        src,
        toks,
        out: Out::default(),
        not_ident: vec![false; n],
    };
    // Directive lines: tokens are not identifiers.
    let mut i = 0;
    while i < n {
        if ctx.toks[i].kind == Kind::Directive {
            let e = ctx.directive_end(i);
            for m in i..e.min(n) {
                ctx.not_ident[m] = true;
            }
            i = e.max(i + 1);
        } else {
            i += 1;
        }
    }
    ctx.scan_file(0, n);
    match name {
        "comments" => ctx
            .toks
            .iter()
            .filter(|t| matches!(t.kind, Kind::LineComment | Kind::BlockComment))
            .map(|t| t.start..t.end)
            .collect(),
        "strings" => {
            let mut out = Vec::new();
            for t in &ctx.toks {
                if t.kind != Kind::Str {
                    continue;
                }
                if t.prefix.contains('$') && !t.prefix.contains('@') && !src[t.start..t.end].starts_with(&format!("{}\"\"\"", t.prefix)) {
                    // Interpolated: text segments, extended to include the delimiters.
                    let n = t.content.len();
                    for (idx, (s, e)) in t.content.iter().enumerate() {
                        let s2 = if idx == 0 { t.start } else { *s };
                        let e2 = if idx + 1 == n { t.end } else { *e };
                        out.push(s2..e2);
                    }
                    if n == 0 {
                        out.push(t.start..t.end);
                    }
                } else {
                    out.push(t.start..t.end);
                }
            }
            out
        }
        "usings" => ctx.out.usings,
        "struct" => ctx.out.structs,
        "enum" => ctx.out.enums,
        "interface" => ctx.out.interfaces,
        "class" => ctx.out.classes,
        "method" => ctx.out.methods,
        "variable-declaration" => ctx.out.var_decls,
        "property" => ctx.out.properties,
        "constructor" => ctx.out.constructors,
        "destructor" => ctx.out.destructors,
        "field" => ctx.out.fields,
        "attribute" => ctx.out.attributes,
        "identifier" => {
            let mut out = Vec::new();
            for (i, t) in ctx.toks.iter().enumerate() {
                if t.kind == Kind::Ident && !ctx.not_ident[i] {
                    let s = t.text(src);
                    let is_kw = KEYWORDS.contains(&s) && !CONTEXTUAL.contains(&s);
                    if !is_kw && !PREDEFINED.contains(&s) && s != "var" {
                        // `@identifier` verbatim identifiers: strip the `@`
                        if let Some(stripped) = s.strip_prefix('@') {
                            let _ = stripped;
                            out.push(t.start + 1..t.end);
                        } else {
                            out.push(t.start..t.end);
                        }
                    }
                }
                if t.kind == Kind::Str && t.prefix.contains('$') {
                    // identifiers inside interpolation holes
                    let text = &src[t.start..t.end];
                    let bytes = text.as_bytes();
                    let mut p = 0;
                    while p < bytes.len() {
                        if bytes[p] == b'{' && bytes.get(p + 1) != Some(&b'{') {
                            let mut depth = 0;
                            let mut q = p;
                            while q < bytes.len() {
                                if bytes[q] == b'{' {
                                    depth += 1;
                                } else if bytes[q] == b'}' {
                                    depth -= 1;
                                    if depth == 0 {
                                        break;
                                    }
                                }
                                q += 1;
                            }
                            let inner = &text[p + 1..q.min(bytes.len())];
                            // stop at ':' (format) or ',' (alignment) at depth 0
                            let mut cut = inner.len();
                            let mut d = 0;
                            for (ci, ch) in inner.char_indices() {
                                match ch {
                                    '(' | '[' => d += 1,
                                    ')' | ']' => d -= 1,
                                    ':' | ',' if d == 0 => {
                                        cut = ci;
                                        break;
                                    }
                                    _ => {}
                                }
                            }
                            let expr = &inner[..cut];
                            let sub = Lexer::new(expr, Flavor::CSharp).lex();
                            for st in sub {
                                if st.kind == Kind::Ident {
                                    let s = st.text(expr);
                                    if !(KEYWORDS.contains(&s) && !CONTEXTUAL.contains(&s)) && !PREDEFINED.contains(&s) {
                                        let base = t.start + p + 1;
                                        out.push(base + st.start..base + st.end);
                                    }
                                }
                            }
                            p = q + 1;
                            continue;
                        }
                        if bytes[p] == b'{' {
                            p += 2;
                            continue;
                        }
                        p += 1;
                    }
                }
            }
            out.sort_by_key(|r| r.start);
            out
        }
        _ => Vec::new(),
    }
}
