//! Language support: HCL (Terraform).

use super::lexer::{matching_close, Flavor, Kind, Lexer, Token};
use super::Range;

#[derive(Default)]
struct Out {
    blocks: Vec<(String, Range)>,
    required_providers: Vec<Range>,
    variables: Vec<Range>,
    resource_names: Vec<Range>,
    resource_types: Vec<Range>,
    data_names: Vec<Range>,
    data_sources: Vec<Range>,
    /// String tokens used as block labels.
    label_strings: Vec<usize>,
}

struct Ctx<'a> {
    src: &'a str,
    toks: Vec<Token>,
    out: Out,
}

const RESERVED_ROOTS: &[&str] = &[
    "var", "local", "module", "data", "each", "count", "path", "terraform", "self", "true",
    "false", "null",
];

impl<'a> Ctx<'a> {
    fn text(&self, i: usize) -> &'a str {
        self.toks[i].text(self.src)
    }
    fn is_punct(&self, i: usize, s: &str) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Punct && self.text(i) == s
    }
    fn is_ident(&self, i: usize) -> bool {
        i < self.toks.len() && self.toks[i].kind == Kind::Ident
    }
    fn is_comment(&self, i: usize) -> bool {
        i < self.toks.len() && matches!(self.toks[i].kind, Kind::LineComment | Kind::BlockComment)
    }
    fn close_of(&self, open: usize) -> usize {
        matching_close(&self.toks, self.src, open).unwrap_or(self.toks.len() - 1)
    }
    fn range(&self, start: usize, end_inclusive: usize) -> Range {
        let e = end_inclusive.min(self.toks.len() - 1);
        self.toks[start].start..self.toks[e].end
    }
    fn newline_before(&self, i: usize) -> bool {
        if i == 0 || i >= self.toks.len() {
            return true;
        }
        self.src[self.toks[i - 1].end..self.toks[i].start].contains('\n')
    }

    fn string_content(&self, i: usize) -> Range {
        let t = &self.toks[i];
        if let Some((s, e)) = t.content.first() {
            if t.content.len() == 1 {
                return *s..*e;
            }
        }
        (t.start + 1)..(t.end.saturating_sub(1).max(t.start + 1))
    }

    /// Body: sequence of attributes and blocks in [start, end).
    fn scan_body(&mut self, start: usize, end: usize, parents: &[String]) {
        let mut i = start;
        while i < end {
            if self.is_comment(i) || self.is_punct(i, ",") {
                i += 1;
                continue;
            }
            if self.is_ident(i) {
                // attribute: ident = expr
