                    let e = self.expr_end(i + 2, end);
                    if parents.len() == 2 && parents[0] == "terraform" && parents[1] == "required_providers" {
                        self.out.required_providers.push(self.range(i, e.saturating_sub(1).max(i)));
                    }
                    self.scan_expression(i + 2, e);
                    i = e.max(i + 1);
                    continue;
                }
                // block: ident labels* {
                let mut k = i + 1;
                let mut labels: Vec<usize> = Vec::new();
                while k < end && (self.toks[k].kind == Kind::Str || self.is_ident(k)) {
                    labels.push(k);
                    k += 1;
                }
