                            self.out.label_strings.push(*l);
                        }
                    }
                    match kind.as_str() {
                        "variable" => {
                            if let Some(l) = labels.first() {
                                if self.toks[*l].kind == Kind::Str {
                                    self.out.variables.push(self.string_content(*l));
                                }
                            }
                        }
                        "resource" => {
                            if labels.len() >= 2 {
                                if self.toks[labels[0]].kind == Kind::Str {
                                    self.out.resource_types.push(self.string_content(labels[0]));
                                }
                                if self.toks[labels[1]].kind == Kind::Str {
                                    self.out.resource_names.push(self.string_content(labels[1]));
                                }
                            }
                        }
                        "data" => {
                            if labels.len() >= 2 {
                                if self.toks[labels[0]].kind == Kind::Str {
                                    self.out.data_sources.push(self.string_content(labels[0]));
                                }
                                if self.toks[labels[1]].kind == Kind::Str {
                                    self.out.data_names.push(self.string_content(labels[1]));
                                }
                            }
                        }
                        _ => {}
                    }
                    self.out.blocks.push((kind.clone(), self.range(i, c)));
                    let mut np: Vec<String> = parents.to_vec();
                    np.push(kind);
                    self.scan_body(k + 1, c, &np);
