                }
                i = k.max(i + 1);
                continue;
            }
            if self.is_punct(i, "{") || self.is_punct(i, "[") || self.is_punct(i, "(") {
                let c = self.close_of(i);
                self.scan_expression(i + 1, c);
                i = c + 1;
                continue;
            }
            i += 1;
