                        continue;
                    }
                    p += 1;
                }
                k += 1;
                continue;
            }
            if matches!(self.text(k), "(" | "[") {
                let c = self.close_of(k);
                self.scan_expression(k + 1, c);
                k = c + 1;
                continue;
            }
            k += 1;
        }
    }
}

pub fn ranges(name: &str, src: &str) -> Vec<Range> {
    let toks = Lexer::new(src, Flavor::Hcl).lex();
    if toks.is_empty() {
        return Vec::new();
    }
    let n = toks.len();
