        src,
        toks,
        out: Out::default(),
    };
    ctx.scan_body(0, n, &[]);
    let blocks = |kind: &str| -> Vec<Range> {
        ctx.out
            .blocks
            .iter()
            .filter(|(k, _)| k == kind)
            .map(|(_, r)| r.clone())
            .collect()
    };
    match name {
        "variable" | "resource" | "data" | "output" | "provider" | "terraform" | "locals" | "module" => blocks(name),
        "required-providers" => ctx.out.required_providers.clone(),
        "variables" => ctx.out.variables.clone(),
        "resource-names" => ctx.out.resource_names.clone(),
        "resource-types" => ctx.out.resource_types.clone(),
        "data-names" => ctx.out.data_names.clone(),
        "data-sources" => ctx.out.data_sources.clone(),
        "comments" => ctx
            .toks
            .iter()
            .filter(|t| matches!(t.kind, Kind::LineComment | Kind::BlockComment))
            .map(|t| t.start..t.end)
            .collect(),
        "strings" => {
            let mut out = Vec::new();
            for (i, t) in ctx.toks.iter().enumerate() {
                if t.kind == Kind::Str && !ctx.out.label_strings.contains(&i) {
                    for (s, e) in &t.content {
                        out.push(*s..*e);
                    }
                }
            }
            out
        }
        _ => Vec::new(),
    }
}
