//! Minimal support for custom tree-sitter style queries.

use super::query::QueryError;
use super::tree::Node;
use super::{LangKind, Range};

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum Pat {
    /// `(kind children...) @cap`
    Node {
        kind: String,
        children: Vec<Pat>,
        captures: Vec<String>,
        quant: char,
        field: Option<String>,
        negated_fields: Vec<String>,
