        LangKind::C => &[
            ("comments", "comment"),
            ("strings", "string_literal"),
            ("includes", "preproc_include"),
            ("type-def", "type_definition"),
            ("enum", "enum_specifier"),
            ("struct", "struct_specifier"),
            ("union", "union_specifier"),
            ("declaration", "declaration"),
            ("function-def", "function_definition"),
            ("function-decl", "function_declarator"),
            ("switch", "switch_statement"),
            ("if", "if_statement"),
            ("for", "for_statement"),
            ("while", "while_statement"),
            ("do", "do_statement"),
            ("identifier", "identifier"),
            ("call-expression", "call_expression"),
        ],
        LangKind::CSharp => &[
            ("comments", "comment"),
            ("strings", "string_literal"),
            ("usings", "using_directive"),
            ("struct", "struct_declaration"),
            ("enum", "enum_declaration"),
            ("interface", "interface_declaration"),
            ("class", "class_declaration"),
            ("method", "method_declaration"),
            ("variable-declaration", "variable_declaration"),
            ("property", "property_declaration"),
            ("constructor", "constructor_declaration"),
            ("destructor", "destructor_declaration"),
            ("field", "field_declaration"),
            ("attribute", "attribute"),
            ("identifier", "identifier"),
        ],
        LangKind::Hcl => &[
            ("variable", "block"),
            ("resource", "block"),
            ("data", "block"),
            ("output", "block"),
            ("provider", "block"),
            ("terraform", "block"),
            ("locals", "block"),
            ("module", "block"),
            ("comments", "comment"),
            ("strings", "template_literal"),
            ("variables", "identifier"),
        ],
        LangKind::Python => &[],
    };
    let mut nodes: Vec<Node> = Vec::new();
    for (q, k) in specs {
        let kind_str: &'static str = k;
        for r in super::prepared_ranges(kind, q, src) {
            let mut n = Node::new(kind_str, r.start, r.end);
            if kind == LangKind::Rust && kind_str == "line_comment" && src[r.clone()].starts_with("/*") {
                n.kind = "block_comment";
            }
            if kind == LangKind::Go && kind_str == "interpreted_string_literal" && src[r.clone()].starts_with('`') {
                n.kind = "raw_string_literal";
            }
            nodes.push(n);
        }
    }
    // Deduplicate identical (kind, range).
    nodes.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)).then(a.kind.cmp(b.kind)));
    nodes.dedup_by(|a, b| a.start == b.start && a.end == b.end && a.kind == b.kind);
    // Build hierarchy by containment.
    let root_kind = match kind {
        LangKind::Rust | LangKind::Go | LangKind::TypeScript | LangKind::CSharp => "source_file",
        LangKind::C => "translation_unit",
        LangKind::Hcl => "config_file",
        LangKind::Python => "module",
    };
    let mut root = Node::new(root_kind, 0, src.len());
    let mut stack: Vec<Node> = Vec::new();
    for n in nodes {
        while let Some(top) = stack.last() {
            if n.start >= top.end || (n.start == top.start && n.end == top.end) && false {
                let done = stack.pop().unwrap();
                attach(&mut stack, &mut root, done);
            } else {
                break;
            }
        }
        stack.push(n);
    }
    while let Some(done) = stack.pop() {
        attach(&mut stack, &mut root, done);
    }
    root
}

fn attach(stack: &mut Vec<Node>, root: &mut Node, node: Node) {
    match stack.last_mut() {
        Some(parent) => parent.children.push(node),
        None => root.children.push(node),
    }
}
