//! Minimal support for custom tree-sitter style queries.

use super::query::QueryError;
use super::tree::Node;
use super::{LangKind, Range};

// ---------------------------------------------------------------------------
// Parsing
// ---------------------------------------------------------------------------

#[derive(Debug, Clone)]
enum Pat {
    /// `(kind children...) @cap`
    Node {
        kind: String,
        children: Vec<Pat>,
        captures: Vec<String>,
        quant: char,
        field: Option<String>,
        negated_fields: Vec<String>,
    },
    /// `"literal"` anonymous node.
    Anon {
        text: String,
        captures: Vec<String>,
        field: Option<String>,
        quant: char,
    },
    /// `_` wildcard (any node).
    Wild {
        captures: Vec<String>,
        field: Option<String>,
        quant: char,
    },
    /// `[a b c]`
    Alt {
        alts: Vec<Pat>,
        captures: Vec<String>,
        field: Option<String>,
        quant: char,
    },
    /// `(#pred? @a "x")`
    Predicate {
        name: String,
        args: Vec<PredArg>,
    },
    /// `.` anchor (ignored)
    Anchor,
}

#[derive(Debug, Clone)]
enum PredArg {
    Capture(String),
    Str(String),
}

#[derive(Debug, Clone)]
pub struct Compiled {
    patterns: Vec<Pat>,
}

struct QParser<'a> {
    src: &'a str,
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> QParser<'a> {
    fn err(&self, pos: usize) -> QueryError {
        // Compute row/col (1-based) and the offending line with a caret.
        let pos = pos.min(self.src.len());
        let before = &self.src[..pos];
        let row = before.matches('\n').count() + 1;
        let line_start = before.rfind('\n').map(|i| i + 1).unwrap_or(0);
        let col = pos - line_start + 1;
        let line_end = self.src[pos..].find('\n').map(|i| pos + i).unwrap_or(self.src.len());
        let line = &self.src[line_start..line_end];
        QueryError(format!(
            "Query error at {row}:{col}. Invalid syntax:\n{line}\n{}^",
            " ".repeat(col - 1)
        ))
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c == b';' {
                while self.pos < self.bytes.len() && self.bytes[self.pos] != b'\n' {
                    self.pos += 1;
                }
            } else if c.is_ascii_whitespace() {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        self.bytes.get(self.pos).copied()
    }

    fn ident(&mut self) -> String {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_alphanumeric() || c == b'_' || c == b'-' || c == b'.' || c == b'?' || c == b'!' {
                self.pos += 1;
            } else {
                break;
            }
        }
        self.src[start..self.pos].to_owned()
    }

    fn string(&mut self) -> Result<String, QueryError> {
        // at '"'
        let start = self.pos;
        self.pos += 1;
        let mut out = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c == b'\\' && self.pos + 1 < self.bytes.len() {
                let n = self.bytes[self.pos + 1];
                out.push(match n {
                    b'n' => '\n',
                    b't' => '\t',
                    b'r' => '\r',
                    b'0' => '\0',
                    _ => n as char,
                });
                self.pos += 2;
                continue;
            }
            if c == b'"' {
                self.pos += 1;
                return Ok(out);
            }
            out.push(self.src[self.pos..].chars().next().unwrap());
            self.pos += self.src[self.pos..].chars().next().unwrap().len_utf8();
        }
        Err(self.err(start))
    }

    fn captures_and_quant(&mut self) -> (Vec<String>, char) {
        let mut caps = Vec::new();
        let mut quant = ' ';
        loop {
            let save = self.pos;
            self.skip_ws();
            match self.peek() {
                Some(b'@') => {
                    self.pos += 1;
                    let name = self.ident();
                    caps.push(name);
                }
                Some(b'*') | Some(b'+') | Some(b'?') if quant == ' ' => {
                    quant = self.peek().unwrap() as char;
                    self.pos += 1;
                }
                _ => {
                    self.pos = save;
                    break;
                }
            }
        }
        (caps, quant)
    }

    fn pattern(&mut self) -> Result<Pat, QueryError> {
        self.skip_ws();
        let start = self.pos;
        // Field name prefix: `name:`
        let mut field: Option<String> = None;
        if let Some(c) = self.peek() {
            if c.is_ascii_alphabetic() || c == b'_' {
                let save = self.pos;
                let id = self.ident();
                self.skip_ws();
                if self.peek() == Some(b':') {
                    self.pos += 1;
                    field = Some(id);
                    self.skip_ws();
                } else {
                    self.pos = save;
                }
            }
            if c == b'!' {
                // negated field
                self.pos += 1;
                let id = self.ident();
                return Ok(Pat::Node {
                    kind: String::new(),
                    children: vec![],
                    captures: vec![],
                    quant: '!',
                    field: Some(id),
                    negated_fields: vec![],
                });
            }
        }
        match self.peek() {
            Some(b'(') => {
                self.pos += 1;
                self.skip_ws();
                if self.peek() == Some(b'#') {
                    // predicate
                    self.pos += 1;
                    let name = self.ident();
                    let mut args = Vec::new();
                    loop {
                        self.skip_ws();
                        match self.peek() {
                            Some(b')') => {
                                self.pos += 1;
                                break;
                            }
                            Some(b'@') => {
                                self.pos += 1;
                                args.push(PredArg::Capture(self.ident()));
                            }
                            Some(b'"') => args.push(PredArg::Str(self.string()?)),
                            Some(_) => {
                                let id = self.ident();
                                if id.is_empty() {
                                    return Err(self.err(self.pos));
                                }
                                args.push(PredArg::Str(id));
                            }
                            None => return Err(self.err(self.pos)),
                        }
                    }
                    return Ok(Pat::Predicate { name, args });
                }
                let kind = if self.peek() == Some(b'_') && !self.bytes.get(self.pos + 1).map_or(false, |c| c.is_ascii_alphanumeric() || *c == b'_') {
                    self.pos += 1;
                    "_".to_owned()
                } else {
                    let id = self.ident();
                    if id.is_empty() {
                        return Err(self.err(self.pos));
                    }
                    id
                };
                let mut children = Vec::new();
                let mut negated = Vec::new();
                loop {
                    self.skip_ws();
                    match self.peek() {
                        Some(b')') => {
                            self.pos += 1;
                            break;
                        }
                        Some(b'.') => {
                            self.pos += 1;
                            children.push(Pat::Anchor);
                        }
                        None => return Err(self.err(self.pos)),
                        Some(_) => {
                            let child = self.pattern()?;
                            if let Pat::Node { quant: '!', field: Some(f), .. } = &child {
                                negated.push(f.clone());
                            } else {
                                children.push(child);
                            }
                        }
                    }
                }
                let (captures, quant) = self.captures_and_quant();
                Ok(Pat::Node {
                    kind,
                    children,
                    captures,
                    quant,
                    field,
                    negated_fields: negated,
                })
            }
            Some(b'[') => {
                self.pos += 1;
                let mut alts = Vec::new();
                loop {
                    self.skip_ws();
                    match self.peek() {
                        Some(b']') => {
                            self.pos += 1;
                            break;
                        }
                        None => return Err(self.err(self.pos)),
                        Some(_) => alts.push(self.pattern()?),
                    }
                }
                let (captures, quant) = self.captures_and_quant();
                Ok(Pat::Alt {
                    alts,
                    captures,
                    field,
                    quant,
                })
            }
            Some(b'"') => {
                let text = self.string()?;
                let (captures, quant) = self.captures_and_quant();
                Ok(Pat::Anon {
                    text,
                    captures,
                    field,
                    quant,
                })
            }
            Some(b'_') => {
                self.pos += 1;
                let (captures, quant) = self.captures_and_quant();
                Ok(Pat::Wild {
                    captures,
                    field,
                    quant,
                })
            }
            _ => Err(self.err(start)),
        }
    }

    fn parse_all(&mut self) -> Result<Compiled, QueryError> {
        let mut patterns = Vec::new();
        loop {
            self.skip_ws();
            if self.pos >= self.bytes.len() {
                break;
            }
            let p = self.pattern()?;
            patterns.push(p);
        }
        Ok(Compiled { patterns })
    }
}

pub fn compile(source: &str) -> Result<Compiled, QueryError> {
    let mut p = QParser {
        src: source,
        bytes: source.as_bytes(),
        pos: 0,
    };
    p.parse_all()
}

pub fn validate(source: &str) -> Result<(), QueryError> {
    compile(source).map(|_| ())
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

type Caps<'a> = Vec<(String, &'a Node)>;

fn match_pat<'a>(pat: &Pat, node: &'a Node, src: &str, caps: &mut Caps<'a>) -> bool {
    match pat {
        Pat::Node { kind, children, captures, field, .. } => {
            if let Some(f) = field {
                if node.field.as_deref() != Some(f.as_str()) {
                    return false;
                }
            }
            if kind != "_" && node.kind != kind {
                return false;
            }
            if kind == "_" && node.anonymous {
                return false;
            }
            let mark = caps.len();
            // Each child pattern must match some (named) child of the node.
            let mut used: Vec<bool> = vec![false; node.children.len()];
            let mut preds = Vec::new();
            for child in children {
                match child {
                    Pat::Anchor => continue,
                    Pat::Predicate { .. } => {
                        preds.push(child);
                        continue;
                    }
                    _ => {}
                }
                let quant = pat_quant(child);
                let mut found = false;
                let mut any = true;
                while any {
                    any = false;
                    for (ci, c) in node.children.iter().enumerate() {
                        if used[ci] {
                            continue;
                        }
                        let before = caps.len();
                        if match_pat(child, c, src, caps) {
                            used[ci] = true;
                            found = true;
                            any = quant == '*' || quant == '+';
                            break;
                        } else {
                            caps.truncate(before);
                        }
                    }
                }
                if !found && quant != '?' && quant != '*' {
                    caps.truncate(mark);
                    return false;
                }
            }
            if let Pat::Node { negated_fields, .. } = pat {
                for nf in negated_fields {
                    if node.child_by_field(nf).is_some() {
                        caps.truncate(mark);
                        return false;
                    }
                }
            }
            for c in captures {
                caps.push((c.clone(), node));
            }
            for p in preds {
                if !eval_pred(p, caps, src) {
                    caps.truncate(mark);
                    return false;
                }
            }
            true
        }
        Pat::Anon { text, captures, field, .. } => {
            if let Some(f) = field {
                if node.field.as_deref() != Some(f.as_str()) {
                    return false;
                }
            }
            if node.text(src) != text {
                return false;
            }
            for c in captures {
                caps.push((c.clone(), node));
            }
            true
        }
        Pat::Wild { captures, field, .. } => {
            if let Some(f) = field {
                if node.field.as_deref() != Some(f.as_str()) {
                    return false;
                }
            }
            for c in captures {
                caps.push((c.clone(), node));
            }
            true
        }
        Pat::Alt { alts, captures, field, .. } => {
            if let Some(f) = field {
                if node.field.as_deref() != Some(f.as_str()) {
                    return false;
                }
            }
            for a in alts {
                let before = caps.len();
                if match_pat(a, node, src, caps) {
                    for c in captures {
                        caps.push((c.clone(), node));
                    }
                    return true;
                }
                caps.truncate(before);
            }
            false
        }
        Pat::Predicate { .. } | Pat::Anchor => true,
    }
}

fn pat_quant(p: &Pat) -> char {
    match p {
        Pat::Node { quant, .. } | Pat::Anon { quant, .. } | Pat::Wild { quant, .. } | Pat::Alt { quant, .. } => *quant,
        _ => ' ',
    }
}

fn eval_pred(p: &Pat, caps: &Caps, src: &str) -> bool {
    let (name, args) = match p {
        Pat::Predicate { name, args } => (name, args),
        _ => return true,
    };
    let texts = |a: &PredArg| -> Vec<String> {
        match a {
            PredArg::Capture(c) => caps.iter().filter(|(n, _)| n == c).map(|(_, nd)| nd.text(src).to_owned()).collect(),
            PredArg::Str(s) => vec![s.clone()],
        }
    };
    let negate = name.starts_with("not-");
    let base = name.trim_start_matches("not-").trim_end_matches('?');
    let result = match base {
        "eq" => {
            if args.len() < 2 {
                return true;
            }
            let a = texts(&args[0]);
            let b = texts(&args[1]);
            a.iter().any(|x| b.iter().any(|y| x == y))
        }
        "match" => {
            if args.len() < 2 {
                return true;
            }
            let a = texts(&args[0]);
            let re = match &args[1] {
                PredArg::Str(s) => regex::Regex::new(s).ok(),
                _ => None,
            };
            match re {
                Some(re) => a.iter().any(|x| re.is_match(x)),
                None => false,
            }
        }
        "any-of" => {
            if args.is_empty() {
                return true;
            }
            let a = texts(&args[0]);
            let rest: Vec<String> = args[1..].iter().flat_map(|x| texts(x)).collect();
            a.iter().any(|x| rest.contains(x))
        }
        _ => true,
    };
    if negate {
        !result
    } else {
        result
    }
}

fn run(compiled: &Compiled, root: &Node, src: &str) -> Vec<Range> {
    let mut out = Vec::new();
    for pat in &compiled.patterns {
        if matches!(pat, Pat::Predicate { .. } | Pat::Anchor) {
            continue;
        }
        root.walk(&mut |node, _| {
            let mut caps: Caps = Vec::new();
            if match_pat(pat, node, src, &mut caps) {
                for (_, n) in caps {
                    out.push(n.range());
                }
            }
        });
    }
    out
}

pub fn ranges(kind: LangKind, source: &str, src: &str) -> Vec<Range> {
    let compiled = match compile(source) {
        Ok(c) => c,
        Err(_) => return Vec::new(),
    };
    let tree = build_tree(kind, src);
    run(&compiled, &tree, src)
}

// ---------------------------------------------------------------------------
// Trees for languages without a real parser: assembled from prepared queries.
// ---------------------------------------------------------------------------

fn build_tree(kind: LangKind, src: &str) -> Node {
    if kind == LangKind::Python {
        return super::python::parse(src);
    }
    // (prepared query, node kind, optional child kind for content)
    let specs: &[(&str, &str)] = match kind {
        LangKind::Rust => &[
            ("comments", "line_comment"),
            ("doc-comments", "line_comment"),
            ("strings", "string_content"),
            ("attribute", "attribute"),
            ("struct", "struct_item"),
            ("enum", "enum_item"),
            ("enum-variant", "enum_variant"),
            ("fn", "function_item"),
            ("trait", "trait_item"),
            ("impl", "impl_item"),
            ("mod", "mod_item"),
            ("identifier", "identifier"),
            ("type-identifier", "type_identifier"),
            ("closure", "closure_expression"),
            ("uses", "use_declaration"),
        ],
        LangKind::Go => &[
            ("comments", "comment"),
            ("strings", "interpreted_string_literal"),
            ("imports", "import_spec"),
            ("type-def", "type_declaration"),
            ("type-alias", "type_alias"),
            ("const", "const_spec"),
            ("var", "var_spec"),
            ("func", "function_declaration"),
            ("method", "method_declaration"),
            ("type-params", "type_parameter_declaration"),
            ("defer", "defer_statement"),
            ("select", "select_statement"),
            ("go", "go_statement"),
            ("switch", "expression_switch_statement"),
            ("labeled", "labeled_statement"),
            ("goto", "goto_statement"),
            ("struct-tags", "raw_string_literal"),
        ],
        LangKind::TypeScript => &[
            ("comments", "comment"),
            ("strings", "string_fragment"),
            ("function", "function_declaration"),
            ("method", "method_definition"),
            ("class", "class_declaration"),
            ("enum", "enum_declaration"),
            ("interface", "interface_declaration"),
            ("try-catch", "try_statement"),
            ("var-decl", "variable_declarator"),
            ("let", "lexical_declaration"),
            ("const", "lexical_declaration"),
            ("var", "variable_declaration"),
            ("type-params", "type_parameters"),
            ("type-alias", "type_alias_declaration"),
            ("namespace", "internal_module"),
            ("export", "export_statement"),
        ],
        LangKind::C => &[
            ("comments", "comment"),
            ("strings", "string_literal"),
            ("includes", "preproc_include"),
            ("type-def", "type_definition"),
            ("enum", "enum_specifier"),
            ("struct", "struct_specifier"),
            ("union", "union_specifier"),
            ("declaration", "declaration"),
            ("function-def", "function_definition"),
            ("function-decl", "function_declarator"),
            ("switch", "switch_statement"),
            ("if", "if_statement"),
            ("for", "for_statement"),
            ("while", "while_statement"),
            ("do", "do_statement"),
            ("identifier", "identifier"),
            ("call-expression", "call_expression"),
        ],
        LangKind::CSharp => &[
            ("comments", "comment"),
            ("strings", "string_literal"),
            ("usings", "using_directive"),
            ("struct", "struct_declaration"),
            ("enum", "enum_declaration"),
            ("interface", "interface_declaration"),
            ("class", "class_declaration"),
            ("method", "method_declaration"),
            ("variable-declaration", "variable_declaration"),
            ("property", "property_declaration"),
            ("constructor", "constructor_declaration"),
            ("destructor", "destructor_declaration"),
            ("field", "field_declaration"),
            ("attribute", "attribute"),
            ("identifier", "identifier"),
        ],
        LangKind::Hcl => &[
            ("variable", "block"),
            ("resource", "block"),
            ("data", "block"),
            ("output", "block"),
            ("provider", "block"),
            ("terraform", "block"),
            ("locals", "block"),
            ("module", "block"),
            ("comments", "comment"),
            ("strings", "template_literal"),
            ("variables", "identifier"),
        ],
        LangKind::Python => &[],
    };
    let mut nodes: Vec<Node> = Vec::new();
    for (q, k) in specs {
        let kind_str: &'static str = k;
        for r in super::prepared_ranges(kind, q, src) {
            let mut n = Node::new(kind_str, r.start, r.end);
            if kind == LangKind::Rust && kind_str == "line_comment" && src[r.clone()].starts_with("/*") {
                n.kind = "block_comment";
            }
            if kind == LangKind::Go && kind_str == "interpreted_string_literal" && src[r.clone()].starts_with('`') {
                n.kind = "raw_string_literal";
            }
            nodes.push(n);
        }
    }
    // Deduplicate identical (kind, range).
    nodes.sort_by(|a, b| a.start.cmp(&b.start).then(b.end.cmp(&a.end)).then(a.kind.cmp(b.kind)));
    nodes.dedup_by(|a, b| a.start == b.start && a.end == b.end && a.kind == b.kind);
    // Build hierarchy by containment.
    let root_kind = match kind {
        LangKind::Rust | LangKind::Go | LangKind::TypeScript | LangKind::CSharp => "source_file",
        LangKind::C => "translation_unit",
        LangKind::Hcl => "config_file",
        LangKind::Python => "module",
    };
