#![allow(dead_code)]
//! Module docs.

use std::{collections::HashMap, fmt::{self, Display}};

pub(crate) mod inner {
    pub(super) fn helper<'a, T: Display + ?Sized>(x: &'a T) -> String where T: 'a { format!("{x}") }
}

#[derive(Debug, Default)]
#[serde(rename_all = "camelCase")]
pub struct Config<'a, T = u8> {
    pub name: &'a str,
    values: Vec<T>,
    #[allow(unused)]
    map: HashMap<String, Box<dyn Fn(i32) -> i32 + Send>>,
}

impl<'a, T> Config<'a, T> where T: Clone {
    pub const DEFAULT: usize = 4;
    type Item = T;
    pub fn new(name: &'a str) -> Self { Self { name, values: Vec::new(), map: HashMap::default() } }
    fn total(&self) -> usize { self.values.iter().map(|v| 1).filter(|&n| n > 0).sum::<usize>() }
    pub async fn run(self: Box<Self>) -> Result<(), fmt::Error> { Ok(()) }
}

pub trait Shape: fmt::Debug {
    const SIDES: u32;
    type Output;
    fn area(&self) -> f64;
    fn describe(&self) -> String { format!("{:?} with {} sides", self, Self::SIDES) }
}

#[derive(Clone, Copy, PartialEq)]
pub enum Token<'s> { Ident(&'s str), Num { value: i64, neg: bool }, Eof }

fn classify(t: Token<'_>) -> &'static str {
    match t {
        Token::Ident(s) if s.starts_with('_') => "private",
        Token::Ident(_) | Token::Eof => "other",
        Token::Num { value: v @ 0..=9, .. } => { let _ = v; "digit" }
        Token::Num { neg: true, .. } => "negative",
        _ => "number",
    }
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cfg = Config::<u8>::new("x");
    let mut counts: HashMap<&str, usize> = HashMap::new();
    for (i, w) in "a b".split(' ').enumerate() {
        *counts.entry(w).or_insert(0) += i;
    }
    let add = move |a: i32, b: i32| -> i32 { a + b };
    let v: Vec<_> = (0..3).map(|x| x as u64).collect();
    if let [first, .., last] = v.as_slice() { println!("{first} {last}"); }
    'outer: loop { while let Some(x) = None::<u8> { break 'outer; } break; }
    unsafe { let p = &cfg as *const Config<u8>; let _ = (*p).name; }
    let s = String::from("é");
    let c = 'x'; let b = b'y'; let r = r"raw\n";
    assert_eq!(add(1, 2), 3, "math is broken: {}", add(1, 2));
    Ok(())
